async function dns(name:string,type:"TXT"|"MX"|"CNAME"){
  try{
    const r=await fetch("https://dns.google/resolve?name="+encodeURIComponent(name)+"&type="+type,{
      cache:"no-store",
      headers:{accept:"application/dns-json"}
    });
    if(!r.ok)return [];
    const body=await r.json();
    return Array.isArray(body?.Answer)?body.Answer.map((a:any)=>String(a?.data||"").replace(/^"|"$/g,"").replace(/\\"/g,'"')):[];
  }catch{return []}
}

export async function GET(){
  const [resend,dkim,spf,mx,cname]=await Promise.all([
    getResendServiceStatus(),
    dns(expected.dkim.name,"TXT"),
    dns(expected.spf.name,"TXT"),
    dns(expected.mx.name,"MX"),
    dns(expected.cname.name,"CNAME")
  ]);

  const checks={
    dkim:dkim.some((v:string)=>v.includes(expected.dkim.value)),
    spf:spf.some((v:string)=>v.includes(expected.spf.value)),
    mx:mx.some((v:string)=>v.toLowerCase().includes(expected.mx.value.toLowerCase())),
    cname:cname.some((v:string)=>v.toLowerCase().replace(/\.$/,"")===expected.cname.value.toLowerCase())
  };
  const dnsVerified=Object.values(checks).every(Boolean);
  const sendOnlyKey=resend.domainStatus==="send_only_key";

  return NextResponse.json({
    configured:resend.configured,
    connected:resend.connected,
    domain,
    verified:(resend.verified||sendOnlyKey)&&dnsVerified,
    domainStatus:resend.domainStatus,
    apiStatus:resend.apiStatus,
    errorCode:resend.errorCode,
    keyFormatValid:resend.keyFormatValid,
    sendingEnabled:resend.sendingEnabled||sendOnlyKey,
    permissionMode:sendOnlyKey?"send_only":"full",
    senderAdjusted:resend.senderAdjusted,
    requestedDomain:resend.requestedDomain,
    checks,
  });
}

import {after,NextRequest,NextResponse} from "next/server";
import {getSupabaseServiceClient,getUserFromAccessToken} from "@/lib/server-supabase";
import {compareGuardianVerificationWithGo,guardianVerificationShadowEnabled,normalizeGuardianVerification} from "@/lib/go-guardian-verification-shadow";
import {guardianVerificationCanaryEnabled,recordGuardianVerificationCanaryComparison,tryGuardianVerificationCanary} from "@/lib/go-guardian-verification-canary";

function tokenFrom(req:NextRequest){
  const bearer=req.headers.get("authorization");
  return bearer?.startsWith("Bearer ")?bearer.slice(7):null;
}

export async function GET(req:NextRequest){
  const accessToken=tokenFrom(req);
  const user=await getUserFromAccessToken(accessToken);
  const service=getSupabaseServiceClient();
  if(!user||!service)return NextResponse.json({error:"Нужен вход в аккаунт."},{status:401});

  const {data:profile}=await service.from("profiles")
    .select("role,onboarding,guardian_verified")
    .eq("id",user.id).maybeSingle();

  const ageGroup=profile?.onboarding?.ageGroup||"18+";
  const needed=profile?.role==="editor"&&ageGroup!=="18+";
  let request:null|{status:string;review_note:string|null}=null;
  if(needed){
    const {data}=await service.from("guardian_verification_requests")
      .select("status,review_note")
      .eq("user_id",user.id)
      .order("created_at",{ascending:false})
      .limit(1).maybeSingle();
    request=data||null;
  }

  const result=normalizeGuardianVerification({needed,verified:Boolean(profile?.guardian_verified),request});
  if(!result)return NextResponse.json({error:"Не удалось загрузить статус подтверждения."},{status:503});
  const canary=await tryGuardianVerificationCanary(accessToken!);
  if(canary.attempted&&canary.value){
    after(()=>recordGuardianVerificationCanaryComparison(canary.value!,result));
    return NextResponse.json(canary.value,{headers:{"Cache-Control":"no-store"}});
  }
  if(!guardianVerificationCanaryEnabled()&&guardianVerificationShadowEnabled()){
    after(()=>compareGuardianVerificationWithGo(accessToken!,result));
  }
  return NextResponse.json(result,{headers:{"Cache-Control":"no-store"}});
}

export async function POST(req:NextRequest){
  const user=await getUserFromAccessToken(tokenFrom(req));
  const service=getSupabaseServiceClient();
  if(!user||!service)return NextResponse.json({error:"Нужен вход в аккаунт."},{status:401});

  const {data:profile}=await service.from("profiles")
    .select("role,onboarding,guardian_verified")
    .eq("id",user.id).maybeSingle();

  const ageGroup=profile?.onboarding?.ageGroup||"18+";
  if(profile?.role!=="editor"||ageGroup==="18+"){
    return NextResponse.json({error:"Этот аккаунт уже доступен по возрасту."},{status:400});
  }
  if(profile?.guardian_verified)return NextResponse.json({ok:true,verified:true});

  const body=await req.json();
  const guardianName=String(body?.guardianName||"").trim().slice(0,160);
  const guardianEmail=String(body?.guardianEmail||"").trim().toLowerCase().slice(0,254);
  const relationship=String(body?.relationship||"").trim().slice(0,80);

  if(!guardianName||!guardianEmail.includes("@")||!relationship){
    return NextResponse.json({error:"Заполни имя родителя, его электронную почту и кем он тебе приходится."},{status:400});
  }

  const {data,error}=await service.from("guardian_verification_requests").insert({
    user_id:user.id,
    guardian_name:guardianName,
    guardian_email:guardianEmail,
    relationship,
    method:"manual",
    status:"pending"
  }).select("id,status,created_at").single();

  if(error)return NextResponse.json({error:error.message},{status:500});
  return NextResponse.json({ok:true,request:data});
}

import {after,NextRequest,NextResponse} from "next/server";
import {curriculum,curriculumModules,learningStartIndex,lessonBySlug,normalizeExperienceLevel} from "@/lib/curriculum";
import {savedAcademyAssessments} from "@/lib/academy-assessment";
import {academyProgressShadowEnabled,compareAcademyProgressWithGo,normalizeAcademyProgress} from "@/lib/go-academy-shadow";
import {academyProgressCanaryEnabled,recordAcademyProgressCanaryComparison,tryAcademyProgressCanary} from "@/lib/go-academy-canary";
import {getLessonProgress,getSupabaseServiceClient,getUserFromAccessToken} from "@/lib/server-supabase";

function bearer(req:NextRequest){
  const header=req.headers.get("authorization")||"";
  const match=/^Bearer ([^\s]+)$/i.exec(header);
  return match?.[1]||null;
}

export async function GET(req:NextRequest){
  const token=bearer(req);
  const user=await getUserFromAccessToken(token);
  if(!user||!token)return NextResponse.json({error:"Нужен вход в аккаунт."},{status:401});

  const canary=await tryAcademyProgressCanary(token);
  if(canary.attempted&&canary.value){
    after(async()=>{
      try{
        const {data,error}=await getLessonProgress(token,user.id);
        const legacy=!error?normalizeAcademyProgress(data):null;
        recordAcademyProgressCanaryComparison(canary.value!,legacy);
      }catch{
        recordAcademyProgressCanaryComparison(canary.value!,null);
      }
    });
    return NextResponse.json(canary.value,{headers:{"Cache-Control":"no-store"}});
  }

  const {data,error}=await getLessonProgress(token,user.id);
  if(error)return NextResponse.json({error:"Не удалось загрузить прогресс."},{status:503});
  const legacy=normalizeAcademyProgress(data);
  if(!legacy)return NextResponse.json({error:"Прогресс повреждён."},{status:500});

  if(!academyProgressCanaryEnabled()&&academyProgressShadowEnabled())after(()=>compareAcademyProgressWithGo(token,legacy));
  return NextResponse.json(legacy,{headers:{"Cache-Control":"no-store"}});
}

export async function POST(req:NextRequest){
  const user=await getUserFromAccessToken(bearer(req));
  const service=getSupabaseServiceClient();
  if(!user||!service)return NextResponse.json({error:"Нужен вход в аккаунт."},{status:401});

  const body=await req.json().catch(()=>({}));
  const lesson=lessonBySlug(String(body?.slug||""));
  const completed=body?.completed!==false;
  const taskConfirmed=body?.taskConfirmed===true;
  const submissionNote=String(body?.submissionNote||"").trim().slice(0,1000);
  if(!lesson)return NextResponse.json({error:"Урок отсутствует."},{status:404});
  if(completed&&!taskConfirmed)return NextResponse.json({error:lesson.theoryOnly?"Подтверди, что главная мысль урока понятна.":"Сначала выполни практическое задание урока."},{status:400});

  const lessonIndex=curriculum.findIndex(item=>item.slug===lesson.slug);
  if(completed&&lessonIndex>0){
    const [{data:profile},{data:completedRows}]=await Promise.all([
      service.from("profiles").select("onboarding").eq("id",user.id).maybeSingle(),
      service.from("lesson_progress").select("status,lessons!inner(slug)").eq("user_id",user.id).eq("status","completed")
    ]);
    const completedSlugs=new Set((completedRows||[]).map((row:any)=>row.lessons?.slug).filter(Boolean));
    if(completedSlugs.has(lesson.slug))return NextResponse.json({ok:true,completed:true,slug:lesson.slug,alreadyCompleted:true});
    const level=normalizeExperienceLevel(profile?.onboarding?.level);
    const startIndex=learningStartIndex(level);
    const startModuleIndex=curriculumModules.findIndex(group=>group.lessons.some(item=>item.slug===curriculum[startIndex]?.slug));
    const moduleIndex=curriculumModules.findIndex(group=>group.module===lesson.module);
    if(level!=="pro"&&moduleIndex>startModuleIndex){
      const requiredAssessmentIndexes=Array.from({length:moduleIndex-startModuleIndex},(_,offset)=>startModuleIndex+offset);
      const tableResult=await service.from("academy_assessments").select("module_index,passed").eq("user_id",user.id).eq("passed",true);
      const passed=new Set(savedAcademyAssessments(profile?.onboarding).map(item=>item.moduleIndex));
      if(!tableResult.error)for(const row of tableResult.data||[])passed.add(Number(row.module_index));
      if(requiredAssessmentIndexes.some(requiredIndex=>!passed.has(requiredIndex)))return NextResponse.json({error:"Сначала пройди аттестацию предыдущей ступени."},{status:409});
    }
  }

  const {data:lessonRow,error:lessonError}=await service.from("lessons").upsert({
    slug:lesson.slug,
    title:lesson.title,
    xp_reward:lesson.xp,
    content:{module:lesson.module,track:lesson.track,software:lesson.software,level:lesson.level,minutes:lesson.minutes},
    published:true
  },{onConflict:"slug"}).select("id").single();
  if(lessonError||!lessonRow)return NextResponse.json({error:"Ошибка синхронизации урока."},{status:503});

  if(completed){
    const {error}=await service.from("lesson_progress").upsert({
      user_id:user.id,
      lesson_id:lessonRow.id,
      status:"completed",
      completed_at:new Date().toISOString(),
      submission_note:submissionNote||null
    },{onConflict:"user_id,lesson_id"});
    if(error)return NextResponse.json({error:"Ошибка сохранения прогресса."},{status:503});
  }else{
    const {error}=await service.from("lesson_progress").delete().eq("user_id",user.id).eq("lesson_id",lessonRow.id);
    if(error)return NextResponse.json({error:"Ошибка снятия отметки."},{status:503});
  }

  const {data:progress}=await service.from("lesson_progress")
    .select("status,lessons!inner(xp_reward)")
    .eq("user_id",user.id)
    .eq("status","completed");
  const xp=(progress||[]).reduce((sum:number,row:any)=>sum+Number(row.lessons?.xp_reward||0),0);
  await service.from("profiles").update({xp}).eq("id",user.id);

  return NextResponse.json({ok:true,completed,slug:lesson.slug,xp});
}

