import {after,NextRequest,NextResponse} from "next/server";
import {getSupabaseServiceClient,getUserFromAccessToken} from "@/lib/server-supabase";
import {tryPracticeSessionSaveCanary} from "@/lib/go-practice-session-canary";
import {practiceSessionReadCanaryEnabled,recordPracticeSessionReadCanaryComparison,tryPracticeSessionReadCanary} from "@/lib/go-practice-session-read-canary";
import {comparePracticeSessionWithGo,normalizePracticeSessionResponse,practiceSessionShadowEnabled} from "@/lib/go-practice-session-shadow";

function bearer(req:NextRequest){
  const value=req.headers.get("authorization");
  return value?.startsWith("Bearer ")?value.slice(7):null;
}

async function access(req:NextRequest){
  const token=bearer(req);
  const user=await getUserFromAccessToken(token);
  const service=getSupabaseServiceClient();
  return user&&service&&token?{user,service,token}:null;
}

export async function GET(req:NextRequest){
  const a=await access(req);
  if(!a)return NextResponse.json({error:"Нужен вход."},{status:401});

  const canary=await tryPracticeSessionReadCanary(a.token);
  if(canary.attempted&&canary.value){
    after(async()=>{
      try{
        const {data,error}=await a.service.from("practice_sessions")
          .select("scenario,messages,result,updated_at")
          .eq("user_id",a.user.id)
          .maybeSingle();
        const legacy=!error?normalizePracticeSessionResponse(data):null;
        recordPracticeSessionReadCanaryComparison(canary.value!,legacy);
      }catch{
        recordPracticeSessionReadCanaryComparison(canary.value!,null);
      }
    });
    return NextResponse.json(canary.value,{headers:{"Cache-Control":"no-store"}});
  }

  const {data,error}=await a.service.from("practice_sessions")
    .select("scenario,messages,result,updated_at")
    .eq("user_id",a.user.id)
    .maybeSingle();
  if(error)return NextResponse.json({error:"Ошибка загрузки тренировки."},{status:503});
  const legacy=normalizePracticeSessionResponse(data);
  if(!legacy)return NextResponse.json({error:"Данные тренировки повреждены."},{status:500});
  if(!practiceSessionReadCanaryEnabled()&&practiceSessionShadowEnabled())after(()=>comparePracticeSessionWithGo(a.token,legacy));
  return NextResponse.json(legacy,{headers:{"Cache-Control":"no-store"}});
}

export async function POST(req:NextRequest){
  const a=await access(req);
  if(!a)return NextResponse.json({error:"Нужен вход."},{status:401});
  const body=await req.json().catch(()=>({}));
  const scenario=String(body?.scenario||"").trim().slice(0,2000);
  const messages=Array.isArray(body?.messages)?body.messages.slice(-50).map((item:any)=>({
    from:item?.from==="client"?"client":"user",
    text:String(item?.text||"").trim().slice(0,2000)
  })).filter((item:any)=>item.text):[];
  const rawResult=body?.result&&typeof body.result==="object"?body.result:null;
  const result=rawResult?{
    client_reply:String(rawResult.client_reply||"").slice(0,2000),
    score:Math.max(0,Math.min(100,Number(rawResult.score)||0)),
    feedback:String(rawResult.feedback||"").slice(0,3000),
    coach_hint:String(rawResult.coach_hint||"").slice(0,3000),
    deal_status:rawResult.deal_status==="won"||rawResult.deal_status==="lost"?rawResult.deal_status:"ongoing",
    deal_reason:String(rawResult.deal_reason||"").slice(0,2000),
    scenario_meta:normalizeScenario(rawResult.scenario_meta)
  }:null;
  const session={scenario,messages,result};
  if(await tryPracticeSessionSaveCanary(a.token,session)){
    return NextResponse.json({ok:true},{headers:{"Cache-Control":"no-store"}});
  }
  const {error}=await a.service.from("practice_sessions").upsert({
    user_id:a.user.id,...session,updated_at:new Date().toISOString()
  },{onConflict:"user_id"});
  if(error)return NextResponse.json({error:"Ошибка сохранения тренировки."},{status:503});
  return NextResponse.json({ok:true},{headers:{"Cache-Control":"no-store"}});
}

function normalizeScenario(value:any){
  if(!value||typeof value!=="object")return null;
  return {
    id:String(value.id||"").slice(0,160),
    client_name:String(value.client_name||"").slice(0,100),
    client_role:String(value.client_role||"").slice(0,180),
    personality:String(value.personality||"").slice(0,300),
    project:String(value.project||"").slice(0,500),
    budget:String(value.budget||"").slice(0,100),
    deadline:String(value.deadline||"").slice(0,160),
    hidden_concern:String(value.hidden_concern||"").slice(0,500),
    difficulty:value.difficulty==="Средняя"||value.difficulty==="Сложная"?value.difficulty:"Базовая",
    opening_message:String(value.opening_message||"").slice(0,1000),
  };
}

import {after,NextRequest,NextResponse} from "next/server";
import {randomUUID} from "node:crypto";
import {getSupabaseServiceClient,getUserFromAccessToken} from "@/lib/server-supabase";
import {findPrivateChatBlockReason,privateChatBlockMessage} from "@/lib/private-chat-moderation";
import {ensurePrivateConversation} from "@/lib/private-chat-server";
import {comparePrivateChatThreadWithGo,normalizePrivateChatThread,privateChatShadowEnabled} from "@/lib/go-private-chat-shadow";
import {privateChatCanaryEnabled,recordPrivateChatCanaryComparison,tryPrivateChatCanary} from "@/lib/go-private-chat-canary";
import {comparePrivateChatListWithGo,normalizePrivateChatList,privateChatListShadowEnabled} from "@/lib/go-private-chat-list-shadow";
import {privateChatListCanaryEnabled,recordPrivateChatListCanaryComparison,tryPrivateChatListCanary} from "@/lib/go-private-chat-list-canary";
import {tryPrivateChatWriteCanary} from "@/lib/go-private-chat-write-canary";
import {privateChatAtomicOrderingEnabled} from "@/lib/private-chat-ordering";

function accessToken(req:NextRequest){
  const value=req.headers.get("authorization");
  return value?.startsWith("Bearer ")?value.slice(7):null;
}

async function authenticate(req:NextRequest){
  const token=accessToken(req);
  const user=await getUserFromAccessToken(token);
  const service=getSupabaseServiceClient();
  if(!user||!service||!token)return null;
  const {data:profile}=await service.from("profiles")
    .select("id,role,display_name,username,onboarding")
    .eq("id",user.id)
    .maybeSingle();
  return profile?{user,service,profile,token}:null;
}

function canOpen(conversation:any,userId:string){
  return conversation.editor_id===userId||conversation.business_owner_id===userId;
}

async function readLegacyThread(auth:NonNullable<Awaited<ReturnType<typeof authenticate>>>,conversationId:string){
  const {data:conversation}=await auth.service.from("private_conversations")
    .select("id,editor_id,business_owner_id,status,company_name,title,source_kind")
    .eq("id",conversationId)
    .maybeSingle();
  if(!conversation)return {ok:false as const,status:404,error:"Чат отсутствует."};
  if(!canOpen(conversation,auth.user.id))return {ok:false as const,status:403,error:"Доступ к чату закрыт."};

  const {data:messages,error}=await auth.service.from("private_messages")
    .select("id,conversation_id,sender_id,body,created_at")
    .eq("conversation_id",conversation.id)
    .order("created_at",{ascending:true})
    .order("id",{ascending:true})
    .limit(200);
  if(error)return {ok:false as const,status:500,error:"Ошибка загрузки сообщений."};
  const value=normalizePrivateChatThread({viewerId:auth.user.id,conversation,messages:messages||[]});
  if(!value)return {ok:false as const,status:503,error:"Ошибка контракта закрытого чата."};
  return {ok:true as const,value};
}

async function readLegacyConversationList(auth:NonNullable<Awaited<ReturnType<typeof authenticate>>>){
  const {data:conversations,error}=await auth.service.from("private_conversations")
    .select("id,editor_id,business_owner_id,source_kind,source_id,company_name,title,status,last_message_at,created_at")
    .or(`editor_id.eq.${auth.user.id},business_owner_id.eq.${auth.user.id}`)
    .order("last_message_at",{ascending:false})
    .order("id",{ascending:true})
    .limit(100);
  if(error)return null;

  const editorIds=[...new Set((conversations||[]).map((item:any)=>item.editor_id))];
  const conversationIds=(conversations||[]).map((item:any)=>item.id);
  const {data:orders,error:ordersError}=conversationIds.length?await auth.service.from("work_orders")
    .select("id,conversation_id,gross_points,editor_points,platform_fee_points,status,work_order_deliverables(preview_name,original_name,submitted_at)")
    .in("conversation_id",conversationIds)
    .or(`customer_id.eq.${auth.user.id},editor_id.eq.${auth.user.id}`)
    .limit(100):{data:[] as any[],error:null};
  if(ordersError)return null;
  const orderMap=Object.fromEntries((orders||[]).map((item:any)=>[item.conversation_id,item]));
  const {data:editors,error:editorsError}=editorIds.length
    ?await auth.service.from("public_profiles").select("id,display_name,username,avatar_url").in("id",editorIds).limit(100)
    :{data:[] as any[],error:null};
  if(editorsError)return null;
  const editorMap=Object.fromEntries((editors||[]).map((item:any)=>[item.id,item]));
  return normalizePrivateChatList({
    viewerId:auth.user.id,
    conversations:(conversations||[]).map((item:any)=>({
      id:item.id,
      side:item.editor_id===auth.user.id?"editor":"company",
      source_kind:item.source_kind,
      source_id:item.source_id,
      otherName:item.editor_id===auth.user.id?item.company_name:(editorMap[item.editor_id]?.display_name||"Монтажёр"),
      otherUsername:item.editor_id===auth.user.id?null:(editorMap[item.editor_id]?.username??null),
      otherAvatar:item.editor_id===auth.user.id?null:(editorMap[item.editor_id]?.avatar_url??null),
      company_name:item.company_name,
      title:item.title,
      status:item.status,
      last_message_at:item.last_message_at,
      created_at:item.created_at,
      workOrder:orderMap[item.id]||null,
    })),
  });
}

export async function GET(req:NextRequest){
  const auth=await authenticate(req);
  if(!auth)return NextResponse.json({error:"Войдите в аккаунт."},{status:401});

  const conversationId=req.nextUrl.searchParams.get("conversationId");
  if(conversationId){
    const canary=await tryPrivateChatCanary(auth.token,conversationId);
    if(canary.attempted&&canary.value){
      after(async()=>{
        try{
          const legacy=await readLegacyThread(auth,conversationId);
          recordPrivateChatCanaryComparison(canary.value!,legacy.ok?legacy.value:null);
        }catch{
          recordPrivateChatCanaryComparison(canary.value!,null);
        }
      });
      return NextResponse.json(canary.value,{headers:{"Cache-Control":"no-store"}});
    }

    const legacy=await readLegacyThread(auth,conversationId);
    if(!legacy.ok)return NextResponse.json({error:legacy.error},{status:legacy.status});
    if(!privateChatCanaryEnabled()&&privateChatShadowEnabled())after(()=>comparePrivateChatThreadWithGo(auth.token,conversationId,legacy.value));
    return NextResponse.json(legacy.value,{headers:{"Cache-Control":"no-store"}});
  }

  const listCanary=await tryPrivateChatListCanary(auth.token);
  if(listCanary.attempted&&listCanary.value){
    after(async()=>{
      try{
        recordPrivateChatListCanaryComparison(listCanary.value!,await readLegacyConversationList(auth));
      }catch{
        recordPrivateChatListCanaryComparison(listCanary.value!,null);
      }
    });
    return NextResponse.json(listCanary.value,{headers:{"Cache-Control":"no-store"}});
  }

  const legacy=await readLegacyConversationList(auth);
  if(!legacy)return NextResponse.json({error:"Ошибка загрузки чатов."},{status:500});
  if(!privateChatListCanaryEnabled()&&privateChatListShadowEnabled())after(()=>comparePrivateChatListWithGo(auth.token,legacy));
  return NextResponse.json(legacy,{headers:{"Cache-Control":"no-store"}});
}

export async function POST(req:NextRequest){
  const auth=await authenticate(req);
  if(!auth)return NextResponse.json({error:"Войдите в аккаунт."},{status:401});
  const body=await req.json().catch(()=>({}));
  const action=String(body?.action||"send");

  if(action==="send"){
    const conversationId=String(body?.conversationId||"");
    const message=String(body?.message||"").trim().replace(/\s{3,}/g,"  ").slice(0,1500);
    if(message.length<1)return NextResponse.json({error:"Напишите сообщение."},{status:400});
    if(findPrivateChatBlockReason(message))return NextResponse.json({error:privateChatBlockMessage()},{status:400});

    const {data:conversation}=await auth.service.from("private_conversations")
      .select("id,editor_id,business_owner_id,status")
      .eq("id",conversationId)
      .maybeSingle();
    if(!conversation)return NextResponse.json({error:"Чат отсутствует."},{status:404});
    if(!canOpen(conversation,auth.user.id))return NextResponse.json({error:"Доступ к чату закрыт."},{status:403});
    if(conversation.status!=="active")return NextResponse.json({error:"Чат завершён."},{status:409});

    const id=randomUUID();
    let created=await tryPrivateChatWriteCanary(auth.token,id,conversation.id,auth.user.id,message);
    if(!created){
      const {data:saved,error}=await auth.service.from("private_messages").upsert({
        id,
        conversation_id:conversation.id,
        sender_id:auth.user.id,
        body:message
      },{onConflict:"id",ignoreDuplicates:true}).select("id,conversation_id,sender_id,body,created_at").maybeSingle();
      if(error){
        if(error.code==="23514")return NextResponse.json({error:privateChatBlockMessage()},{status:400});
        return NextResponse.json({error:"Ошибка отправки сообщения."},{status:500});
      }
      created=saved;
      if(!created){
        const {data:existing,error:readError}=await auth.service.from("private_messages")
          .select("id,conversation_id,sender_id,body,created_at")
          .eq("id",id)
          .eq("conversation_id",conversation.id)
          .maybeSingle();
        if(readError||!existing||existing.sender_id!==auth.user.id||existing.body!==message)return NextResponse.json({error:"Ошибка безопасного повтора сообщения."},{status:409});
        created=existing;
      }
    }
    if(!privateChatAtomicOrderingEnabled()){
      const {error:orderingError}=await auth.service.from("private_conversations")
        .update({last_message_at:created.created_at})
        .eq("id",conversation.id)
        .lte("last_message_at",created.created_at);
      if(orderingError)console.warn("private_chat_ordering",{outcome:"legacy_update_failed"});
    }
    return NextResponse.json({ok:true,message:created});
  }

  if(action==="open_challenge_winner"){
    const submissionId=String(body?.submissionId||"");
    const {data:submission}=await auth.service.from("challenge_submissions")
      .select("id,challenge_id,editor_id,status")
      .eq("id",submissionId)
      .maybeSingle();
    if(!submission||submission.status!=="winner")return NextResponse.json({error:"Сначала выберите победителя."},{status:409});
    const {data:challenge}=await auth.service.from("challenges")
      .select("id,business_id,title")
      .eq("id",submission.challenge_id)
      .maybeSingle();
    const {data:business}=challenge?.business_id?await auth.service.from("businesses")
      .select("id,owner_id,name")
      .eq("id",challenge.business_id)
      .maybeSingle():{data:null};
    if(!challenge||!business||business.owner_id!==auth.user.id)return NextResponse.json({error:"Доступ к заданию закрыт."},{status:403});
    const conversation=await ensurePrivateConversation({
      service:auth.service,
      editorId:submission.editor_id,
      businessId:business.id,
      businessOwnerId:business.owner_id,
      sourceKind:"challenge",
      sourceId:challenge.id,
      companyName:business.name,
      title:"Победитель конкурса: "+challenge.title
    });
    return NextResponse.json({ok:true,conversationId:conversation.id});
  }

  if(action==="accept_job_application"){
    const jobId=String(body?.jobId||"");
    const editorId=String(body?.editorId||"");
    const {data:job}=await auth.service.from("jobs")
      .select("id,business_id,title")
      .eq("id",jobId)
      .maybeSingle();
    const {data:business}=job?.business_id?await auth.service.from("businesses")
      .select("id,owner_id,name,verified")
      .eq("id",job.business_id)
      .maybeSingle():{data:null};
    if(!job||!business||business.owner_id!==auth.user.id)return NextResponse.json({error:"Доступ к вакансии закрыт."},{status:403});
    if(!business.verified)return NextResponse.json({error:"Сначала пройдите проверку компании."},{status:403});

    const {data:application}=await auth.service.from("job_applications")
      .select("job_id,editor_id,status")
      .eq("job_id",job.id)
      .eq("editor_id",editorId)
      .maybeSingle();
    if(!application)return NextResponse.json({error:"Отклик отсутствует."},{status:404});

    const conversation=await ensurePrivateConversation({
      service:auth.service,
      editorId,
      businessId:business.id,
      businessOwnerId:business.owner_id,
      sourceKind:"job",
      sourceId:job.id,
      companyName:business.name||"Компания",
      title:"Вакансия: "+job.title
    });
    if(process.env.PAYMENTS_ENABLED!=="true"){
      await auth.service.from("job_applications").update({status:"accepted"}).eq("job_id",job.id).eq("editor_id",editorId);
      await auth.service.from("jobs").update({status:"closed"}).eq("id",job.id);
      return NextResponse.json({ok:true,conversationId:conversation.id,paymentStatus:"prelaunch"});
    }
    const {data:orderId,error:reserveError}=await auth.service.rpc("reserve_job_points",{
      p_customer:auth.user.id,p_job:job.id,p_editor:editorId,p_conversation:conversation.id
    });
    if(reserveError){
      const reason=String(reserveError.message||"");
      return NextResponse.json({error:reason.includes("NOT_ENOUGH_WORK_POINTS")?"Недостаточно KIVRONIX Points. Сначала пополните баланс.":reason.includes("POINT_PRICE_REQUIRED")?"В задании не указана оплата в Points.":"Не удалось зарезервировать оплату."},{status:409});
    }
    const {error:updateError}=await auth.service.from("job_applications").update({status:"accepted"}).eq("job_id",job.id).eq("editor_id",editorId);
    if(updateError)return NextResponse.json({error:"Оплата зарезервирована, но статус отклика не обновился. Обратитесь в поддержку."},{status:500});
    await auth.service.from("jobs").update({status:"closed"}).eq("id",job.id);
    return NextResponse.json({ok:true,conversationId:conversation.id,workOrderId:orderId});
  }

  if(action==="open_editor"){
    if(auth.profile.role!=="business")return NextResponse.json({error:"Каталог доступен компаниям и блогерам."},{status:403});
    const editorId=String(body?.editorId||"");
    const {data:editor}=await auth.service.from("profiles").select("id,role,display_name").eq("id",editorId).maybeSingle();
    if(!editor||editor.role!=="editor")return NextResponse.json({error:"Монтажёр не найден."},{status:404});
    let {data:business}=await auth.service.from("businesses").select("id,owner_id,name").eq("owner_id",auth.user.id).maybeSingle();
    if(!business){
      const accountKind=auth.profile?.onboarding?.accountKind;
      const {data:created}=await auth.service.from("businesses").insert({owner_id:auth.user.id,name:accountKind==="creator"?(auth.profile.display_name||"Блогер"):(auth.profile.display_name||"Компания")}).select("id,owner_id,name").single();
      business=created;
    }
    if(!business)return NextResponse.json({error:"Не удалось открыть рабочий профиль."},{status:409});
    const conversation=await ensurePrivateConversation({service:auth.service,editorId:editor.id,businessId:business.id,businessOwnerId:auth.user.id,sourceKind:"direct",sourceId:business.id,companyName:business.name||"Заказчик",title:"Знакомство с монтажёром: "+(editor.display_name||"профиль")});
    return NextResponse.json({ok:true,conversationId:conversation.id});
  }

  if(action==="complete_work"){
    const orderId=String(body?.workOrderId||"");
    const {error}=await auth.service.rpc("complete_work_order",{p_customer:auth.user.id,p_order:orderId});
    if(error)return NextResponse.json({error:"Не удалось завершить работу. Проверьте, что вы заказчик и работа ещё активна."},{status:409});
    return NextResponse.json({ok:true});
  }

  if(action==="refund_work"){
    const orderId=String(body?.workOrderId||"");
    const {error}=await auth.service.rpc("refund_work_order",{p_customer:auth.user.id,p_order:orderId});
    if(error)return NextResponse.json({error:"Возврат недоступен: возможно, заказ уже завершён или отменён."},{status:409});
    return NextResponse.json({ok:true});
  }

  if(action==="submit_work"){
    const orderId=String(body?.workOrderId||"");
    const previewPath=String(body?.previewPath||"");
    const originalPath=String(body?.originalPath||"");
    const previewName=String(body?.previewName||"").trim().slice(0,160);
    const originalName=String(body?.originalName||"").trim().slice(0,160);
    const {data:order}=await auth.service.from("work_orders")
      .select("id,conversation_id,editor_id,status")
      .eq("id",orderId)
      .maybeSingle();
    if(!order||order.editor_id!==auth.user.id)return NextResponse.json({error:"Передать результат может только выбранный монтажёр."},{status:403});
    if(!["funded","submitted"].includes(order.status))return NextResponse.json({error:"Этот заказ уже завершён или отменён."},{status:409});
    const prefix=`${order.conversation_id}/delivery/${order.id}`;
    if(!previewName||!originalName
      ||!previewPath.startsWith(`${prefix}/preview/${auth.user.id}/`)
      ||!originalPath.startsWith(`${prefix}/original/${auth.user.id}/`)){
      return NextResponse.json({error:"Некорректные файлы результата."},{status:400});
    }
    const {error}=await auth.service.rpc("submit_work_order",{
      p_editor:auth.user.id,
      p_order:order.id,
      p_preview_path:previewPath,
      p_original_path:originalPath,
      p_preview_name:previewName,
      p_original_name:originalName
    });
    if(error)return NextResponse.json({error:"Не удалось передать работу. Проверьте, что оба файла загрузились."},{status:409});
    const submittedAt=new Date().toISOString();
    const {error:orderingError}=await auth.service.from("private_conversations")
      .update({last_message_at:submittedAt})
      .eq("id",order.conversation_id)
      .lte("last_message_at",submittedAt);
    if(orderingError)console.warn("private_chat_ordering",{outcome:"delivery_update_failed"});
    return NextResponse.json({ok:true});
  }

  if(action==="open_delivery"){
    const orderId=String(body?.workOrderId||"");
    const kind=body?.kind==="original"?"original":"preview";
    const {data:order}=await auth.service.from("work_orders")
      .select("id,customer_id,editor_id,status,work_order_deliverables(preview_path,original_path)")
      .eq("id",orderId)
      .maybeSingle();
    if(!order||![order.customer_id,order.editor_id].includes(auth.user.id))return NextResponse.json({error:"Доступ к файлу закрыт."},{status:403});
    const delivery=Array.isArray(order.work_order_deliverables)?order.work_order_deliverables[0]:order.work_order_deliverables;
    if(!delivery)return NextResponse.json({error:"Монтажёр ещё не передал результат."},{status:404});
    if(kind==="preview"&&!['submitted','completed'].includes(order.status))return NextResponse.json({error:"Превью ещё недоступно."},{status:409});
    if(kind==="original"&&auth.user.id!==order.editor_id&&order.status!=="completed")return NextResponse.json({error:"Оригинал откроется после принятия и оплаты работы."},{status:403});
    const path=kind==="original"?delivery.original_path:delivery.preview_path;
    const {data,error}=await auth.service.storage.from("work-files").createSignedUrl(path,60);
    if(error||!data?.signedUrl)return NextResponse.json({error:"Не удалось открыть файл."},{status:500});
    return NextResponse.json({url:data.signedUrl,expiresIn:60});
  }

  return NextResponse.json({error:"Выберите действие."},{status:400});
}

import {after,NextRequest,NextResponse} from "next/server";
import {getProfileLearningPreferences,getSupabaseServiceClient,getUserFromAccessToken} from "@/lib/server-supabase";
import {compareLearningPreferencesWithGo,learningPreferencesShadowEnabled,normalizeLearningPreferences} from "@/lib/go-profile-shadow";
import {learningPreferencesCanaryEnabled,recordLearningPreferencesCanaryComparison,tryLearningPreferencesCanary} from "@/lib/go-profile-canary";
import {tryLearningPreferencesUpdateCanary} from "@/lib/go-profile-update-canary";

function accessToken(req:NextRequest){
  const header=req.headers.get("authorization")||"";
  const match=/^Bearer ([^\s]+)$/i.exec(header);
  return match?.[1]||null;
}

export async function GET(req:NextRequest){
  const token=accessToken(req);
  const user=await getUserFromAccessToken(token);
  if(!user||!token)return NextResponse.json({error:"Нужен вход."},{status:401});

  const canary=await tryLearningPreferencesCanary(token);
  if(canary.attempted&&canary.value){
    after(async()=>{
      try{
        const {data:profile,error}=await getProfileLearningPreferences(token,user.id);
        const legacy=!error&&profile?normalizeLearningPreferences(profile.role,profile.onboarding):null;
        recordLearningPreferencesCanaryComparison(canary.value!,legacy);
      }catch{
        recordLearningPreferencesCanaryComparison(canary.value!,null);
      }
    });
    return NextResponse.json(canary.value,{headers:{"Cache-Control":"no-store"}});
  }

  const {data:profile,error}=await getProfileLearningPreferences(token,user.id);
  if(error)return NextResponse.json({error:"Не удалось загрузить профиль."},{status:503});
  if(!profile)return NextResponse.json({error:"Профиль отсутствует."},{status:404});
  const legacy=normalizeLearningPreferences(profile.role,profile.onboarding);
  if(!legacy)return NextResponse.json({error:"Профиль повреждён."},{status:500});

  if(!learningPreferencesCanaryEnabled()&&learningPreferencesShadowEnabled())after(()=>compareLearningPreferencesWithGo(token,legacy));
  return NextResponse.json(legacy,{headers:{"Cache-Control":"no-store"}});
}

export async function POST(req:NextRequest){
	const token=accessToken(req);
	const user=await getUserFromAccessToken(token);
  const service=getSupabaseServiceClient();
  if(!user||!service)return NextResponse.json({error:"Нужен вход."},{status:401});

  const body=await req.json().catch(()=>({}));
  const level=String(body?.level||"").slice(0,80);
  const software=String(body?.software||"").slice(0,80);
  const goal=String(body?.goal||"").slice(0,80);

  if(token){
    const canary=await tryLearningPreferencesUpdateCanary(token,{level,software,goal});
    if(canary)return NextResponse.json(canary,{headers:{"Cache-Control":"no-store"}});
  }

  const {data:profile}=await service.from("profiles").select("role,onboarding").eq("id",user.id).maybeSingle();
  if(!profile)return NextResponse.json({error:"Профиль отсутствует."},{status:404});
  if(profile.role!=="editor")return NextResponse.json({error:"Эти настройки доступны только монтажёру."},{status:403});

  const onboarding={...(profile.onboarding||{}),level,software,goal};
  const {error}=await service.from("profiles").update({onboarding}).eq("id",user.id);
  if(error)return NextResponse.json({error:error.message},{status:500});
  return NextResponse.json({ok:true,onboarding},{headers:{"Cache-Control":"no-store"}});
}

import {after,NextRequest,NextResponse} from "next/server";
import {profileSettingsCanaryEnabled,recordProfileSettingsCanaryComparison,tryProfileSettingsCanary} from "@/lib/go-profile-settings-canary";
import {tryProfileSettingsUpdateCanary} from "@/lib/go-profile-settings-update-canary";
import {compareProfileSettingsWithGo,normalizeProfileSettings,profileSettingsShadowEnabled,sameProfileSettings} from "@/lib/go-profile-settings-shadow";
import {getSupabaseServiceClient,getUserFromAccessToken,updateProfileSettings} from "@/lib/server-supabase";

function bearer(req:NextRequest){
  const header=req.headers.get("authorization")||"";
  return /^Bearer ([^\s]+)$/i.exec(header)?.[1]||null;
}

export async function GET(req:NextRequest){
  const token=bearer(req);
  const user=await getUserFromAccessToken(token);
  const service=getSupabaseServiceClient();
  if(!user||!token)return NextResponse.json({error:"Нужен вход в аккаунт."},{status:401});
  if(!service)return NextResponse.json({error:"Сервис профиля недоступен."},{status:503});

  const canary=await tryProfileSettingsCanary(token);
  if(canary.attempted&&canary.value){
    after(async()=>{
      try{
        const {data,error}=await service.from("profiles")
          .select("display_name,username,school_name,avatar_url,show_school_publicly")
          .eq("id",user.id)
          .maybeSingle();
        const legacy=!error&&data?normalizeProfileSettings(data):null;
        recordProfileSettingsCanaryComparison(canary.value!,legacy);
      }catch{
        recordProfileSettingsCanaryComparison(canary.value!,null);
      }
    });
    return NextResponse.json(canary.value,{headers:{"Cache-Control":"no-store"}});
  }

  const {data,error}=await service.from("profiles")
    .select("display_name,username,school_name,avatar_url,show_school_publicly")
    .eq("id",user.id)
    .maybeSingle();
  if(error)return NextResponse.json({error:"Не удалось загрузить профиль."},{status:503});
  if(!data)return NextResponse.json({error:"Профиль отсутствует."},{status:404});
  const legacy=normalizeProfileSettings(data);
  if(!legacy)return NextResponse.json({error:"Профиль повреждён."},{status:500});

  if(!profileSettingsCanaryEnabled()&&profileSettingsShadowEnabled())after(()=>compareProfileSettingsWithGo(token,legacy));
  return NextResponse.json(legacy,{headers:{"Cache-Control":"no-store"}});
}

export async function POST(req:NextRequest){
  const token=bearer(req);
  const user=await getUserFromAccessToken(token);
  if(!user||!token)return NextResponse.json({error:"Нужен вход в аккаунт."},{status:401});
  if(!req.headers.get("content-type")?.toLowerCase().startsWith("application/json")){
    return NextResponse.json({error:"Ожидаются настройки профиля в формате JSON."},{status:400});
  }

  const input=normalizeUpdate(await req.json().catch(()=>null));
  if(!input)return NextResponse.json({error:"Проверь имя, адрес страницы и остальные поля профиля."},{status:400});

  const canary=await tryProfileSettingsUpdateCanary(token,input);
  if(canary)return NextResponse.json(canary,{headers:{"Cache-Control":"no-store"}});

  const {data,error}=await updateProfileSettings(token,user.id,input);
  if(error){
    if(error.code==="23505")return NextResponse.json({error:"Этот адрес страницы уже занят. Попробуй другой."},{status:409});
    return NextResponse.json({error:"Не удалось сохранить профиль."},{status:503});
  }
  const saved=normalizeProfileSettings(data);
  if(!saved||!sameProfileSettings(saved,input))return NextResponse.json({error:"Профиль сохранился с некорректным ответом."},{status:503});
  return NextResponse.json(saved,{headers:{"Cache-Control":"no-store"}});
}

function normalizeUpdate(value:unknown){
  const normalized=normalizeProfileSettings(value);
  if(!normalized)return null;
  const displayName=normalized.displayName.trim().replace(/\s+/g," ");
  const username=normalized.username.trim().replace(/^@/,"").toLowerCase();
  const schoolName=normalized.schoolName.trim().replace(/\s+/g," ");
  const avatarUrl=normalized.avatarUrl.trim();
  if(displayName.length<2||[...displayName].length>120||!/^[a-z0-9][a-z0-9._-]{2,29}$/.test(username))return null;
  if(schoolName&&([...schoolName].length<2||[...schoolName].length>160))return null;
  if(avatarUrl){
    try{
      const parsed=new URL(avatarUrl);
      if(parsed.protocol!=="https:"||parsed.username||parsed.password||parsed.hash||avatarUrl.length>4096)return null;
    }catch{return null;}
  }
  return {displayName,username,schoolName,avatarUrl,showSchoolPublicly:Boolean(schoolName&&normalized.showSchoolPublicly)};
}

import {NextRequest,NextResponse} from "next/server";
import {getSupabaseServiceClient,getUserFromAccessToken} from "@/lib/server-supabase";

function token(req:NextRequest){
  const h=req.headers.get("authorization");
  return h?.startsWith("Bearer ")?h.slice(7):null;
}

export async function POST(req:NextRequest){
  const user=await getUserFromAccessToken(token(req));
  const service=getSupabaseServiceClient();
  if(!user||!service)return NextResponse.json({ok:false},{status:401});
  if(!user.email_confirmed_at)return NextResponse.json({ok:true,qualified:false,reason:"email"});

  const {data:ref}=await service.from("referrals").select("id,status").eq("referred_id",user.id).maybeSingle();
  if(!ref||ref.status!=="pending")return NextResponse.json({ok:true,qualified:ref?.status==="qualified"});

  const {count}=await service.from("lesson_progress").select("lesson_id",{count:"exact",head:true})
    .eq("user_id",user.id).eq("status","completed");
  if((count||0)<3)return NextResponse.json({ok:true,qualified:false,reason:"lessons",completed:count||0});

  const {error}=await service.from("referrals")
    .update({status:"qualified",qualified_at:new Date().toISOString()})
    .eq("id",ref.id).eq("status","pending");
  if(error)return NextResponse.json({error:error.message},{status:500});
  return NextResponse.json({ok:true,qualified:true});
}

import {NextRequest,NextResponse} from "next/server";
import {getSupabaseServiceClient,getUserFromAccessToken} from "@/lib/server-supabase";

function token(req:NextRequest){const h=req.headers.get("authorization");return h?.startsWith("Bearer ")?h.slice(7):null}

async function ensureNextKivronixSeason(service:any){
  const {data:first}=await service.from("learning_competitions")
    .select("slug,title,description,task,audience,points_reward,starts_at,ends_at,competition_kind,prize_pool_cents,prize_split_cents,max_entries,selection_metric,requires_public_post,social_tag,season_number,recurs_every_months")
    .eq("competition_kind","prize")
    .not("recurs_every_months","is",null)
    .order("season_number",{ascending:false})
    .limit(1)
    .maybeSingle();
  let latest=first;
  for(let safety=0;latest?.ends_at&&safety<12&&new Date(latest.ends_at).getTime()<=Date.now();safety++){
    await service.from("learning_competitions").update({status:"closed"}).eq("slug",latest.slug);
    const months=Math.max(1,Math.min(12,Number(latest.recurs_every_months||2)));
    const season=Number(latest.season_number||1)+1;
    const startsAt=new Date(latest.ends_at);
    const endsAt=new Date(startsAt);
    endsAt.setUTCMonth(endsAt.getUTCMonth()+months);
    const {data:next}=await service.from("learning_competitions").upsert({
      slug:`kivronix-reels-season-${season}`,
      title:`Сними ролик про KIVRONIX · Сезон ${season}`,
      description:latest.description,
      task:latest.task,
      audience:latest.audience,
      points_reward:latest.points_reward,
      status:"open",
      starts_at:startsAt.toISOString(),
      ends_at:endsAt.toISOString(),
      competition_kind:latest.competition_kind,
      prize_pool_cents:latest.prize_pool_cents,
      prize_split_cents:latest.prize_split_cents,
      max_entries:latest.max_entries,
      selection_metric:latest.selection_metric,
      requires_public_post:latest.requires_public_post,
      social_tag:latest.social_tag,
      season_number:season,
      recurs_every_months:months
    },{onConflict:"slug"}).select("slug,title,description,task,audience,points_reward,starts_at,ends_at,competition_kind,prize_pool_cents,prize_split_cents,max_entries,selection_metric,requires_public_post,social_tag,season_number,recurs_every_months").single();
    if(!next)break;
    latest=next;
  }
}

export async function GET(req:NextRequest){
  const user=await getUserFromAccessToken(token(req));
  const service=getSupabaseServiceClient();
  if(!user||!service)return NextResponse.json({error:"Нужен вход."},{status:401});
  await ensureNextKivronixSeason(service);
  const {data:profile}=await service.from("profiles").select("onboarding,guardian_verified").eq("id",user.id).maybeSingle();
  const adult=(profile?.onboarding?.ageGroup||"18+")==="18+";
  const {data:comps,error}=await service.from("learning_competitions")
    .select("id,slug,title,description,task,audience,points_reward,starts_at,ends_at,competition_kind,prize_pool_cents,prize_split_cents,max_entries,selection_metric,requires_public_post,social_tag,season_number,recurs_every_months")
    .eq("status","open")
    .or(adult?"audience.eq.all,audience.eq.adult":"audience.eq.all,audience.eq.youth")
    .order("created_at",{ascending:false});
  if(error)return NextResponse.json({error:error.message},{status:500});
  const ids=(comps||[]).map((c:any)=>c.id);
  const {data:entries}=ids.length
    ? await service.from("learning_competition_entries").select("id,competition_id,status,judge_score,work_url,verified_views,views_checked_at,place,prize_cents").eq("user_id",user.id).in("competition_id",ids)
    : {data:[] as any[]};
  const {data:allEntries}=ids.length
    ?await service.from("learning_competition_entries").select("competition_id,user_id,verified_views,views_checked_at,place,prize_cents,status").in("competition_id",ids)
    :{data:[] as any[]};
  const userIds=[...new Set((allEntries||[]).map((entry:any)=>entry.user_id))];
  const {data:publicProfiles}=userIds.length
    ?await service.from("public_profiles").select("id,username,display_name,avatar_url,school_name").in("id",userIds)
    :{data:[] as any[]};
  const profileMap=Object.fromEntries((publicProfiles||[]).map((item:any)=>[item.id,item]));
  const map=Object.fromEntries((entries||[]).map((e:any)=>[e.competition_id,e]));
  return NextResponse.json({competitions:(comps||[]).map((c:any)=>{
    const competitionEntries=(allEntries||[]).filter((entry:any)=>entry.competition_id===c.id);
    const leaders=competitionEntries.slice().sort((a:any,b:any)=>Number(b.verified_views||0)-Number(a.verified_views||0)).slice(0,10).map((entry:any)=>({
      ...entry,profile:profileMap[entry.user_id]||null
    }));
    const ageGroup=profile?.onboarding?.ageGroup||"18+";
    return {...c,entry:map[c.id]||null,entry_count:competitionEntries.length,leaders,age_eligible:c.competition_kind!=="prize"||ageGroup!=="under14",guardian_required:!adult&&!profile?.guardian_verified&&c.competition_kind==="prize"};
  })});
}

export async function POST(req:NextRequest){
  const user=await getUserFromAccessToken(token(req));
  const service=getSupabaseServiceClient();
  if(!user||!service)return NextResponse.json({error:"Нужен вход."},{status:401});
  const body=await req.json().catch(()=>({}));
  const competitionId=String(body?.competitionId||"");
  const workUrl=String(body?.workUrl||"").trim().slice(0,800);
  const note=String(body?.note||"").trim().slice(0,500);
  if(!/^https?:\/\//i.test(workUrl))return NextResponse.json({error:"Нужна ссылка на работу, начинающаяся с http:// или https://."},{status:400});

  const [{data:profile},{data:comp}]=await Promise.all([
    service.from("profiles").select("role,onboarding,guardian_verified,level,xp").eq("id",user.id).maybeSingle(),
    service.from("learning_competitions").select("id,audience,status,ends_at,competition_kind,max_entries,requires_public_post").eq("id",competitionId).maybeSingle()
  ]);
  if(profile?.role!=="editor")return NextResponse.json({error:"Участвовать может только монтажёр."},{status:403});
  if(Number(profile?.level||1)<2||Number(profile?.xp||0)<300)return NextResponse.json({error:"Конкурсы откроются на уровне 2 после 300 XP."},{status:403});
  if(!comp||comp.status!=="open"||(comp.ends_at&&new Date(comp.ends_at).getTime()<Date.now()))return NextResponse.json({error:"Соревнование уже закрыто."},{status:400});
  const adult=(profile?.onboarding?.ageGroup||"18+")==="18+";
  if(comp.competition_kind==="prize"&&profile?.onboarding?.ageGroup==="under14")return NextResponse.json({error:"Денежный конкурс KIVRONIX доступен участникам с 14 лет."},{status:403});
  if((comp.audience==="adult"&&!adult)||(comp.audience==="youth"&&adult))return NextResponse.json({error:"Это соревнование для другой возрастной категории."},{status:403});
  if(comp.competition_kind==="prize"&&!adult&&!profile?.guardian_verified)return NextResponse.json({error:"Для участия в денежном конкурсе до 18 лет нужно подтверждение законного представителя."},{status:403});
  if(comp.requires_public_post&&!/^https:\/\//i.test(workUrl))return NextResponse.json({error:"Для конкурса нужна публичная HTTPS-ссылка на опубликованный ролик."},{status:400});

  const {data,error}=await service.from("learning_competition_entries").upsert({
    competition_id:competitionId,user_id:user.id,work_url:workUrl,note,status:"submitted"
  },{onConflict:"competition_id,user_id"}).select("id,status").single();
  if(error){
    const full=String(error.message||"");
    return NextResponse.json({error:full.includes("COMPETITION_CAPACITY_REACHED")?"Лимит в 100 участников уже достигнут.":error.message},{status:400});
  }
  return NextResponse.json({ok:true,entry:data});
}

import {after,NextRequest,NextResponse} from "next/server";
import {getSupabaseServiceClient,getUserFromAccessToken} from "@/lib/server-supabase";
import {compareSocialFriendsWithGo,normalizeSocialFriends,socialFriendsShadowEnabled} from "@/lib/go-social-friends-shadow";
import {recordSocialFriendsCanaryComparison,socialFriendsCanaryEnabled,trySocialFriendsCanary} from "@/lib/go-social-friends-canary";
import {tryFriendshipCancelCanary} from "@/lib/go-social-friend-cancel-canary";
import {tryFriendshipResponseCanary} from "@/lib/go-social-friend-response-canary";

function token(req:NextRequest){
  const h=req.headers.get("authorization");
  return h?.startsWith("Bearer ")?h.slice(7):null;
}
async function auth(req:NextRequest){
  const accessToken=token(req);
  const user=await getUserFromAccessToken(accessToken);
  const service=getSupabaseServiceClient();
  return user&&service&&accessToken?{user,service,token:accessToken}:null;
}
function ageBand(profile:any){return profile?.onboarding?.ageGroup||"18+"}

async function readLegacyFriends(a:NonNullable<Awaited<ReturnType<typeof auth>>>){
  const {data:rels,error}=await a.service.from("friendships")
    .select("id,requester_id,addressee_id,status,created_at")
    .or("requester_id.eq."+a.user.id+",addressee_id.eq."+a.user.id)
    .order("created_at",{ascending:false})
    .limit(200);
  if(error)return null;

  const ids=[...new Set((rels||[]).flatMap((r:any)=>[r.requester_id,r.addressee_id]).filter((id:string)=>id!==a.user.id))];
  const {data:profiles,error:profilesError}=ids.length
    ? await a.service.from("public_profiles").select("id,username,display_name,level,xp,rating_points,ai_score,avatar_url,school_name").in("id",ids)
    : {data:[] as any[],error:null};
  if(profilesError)return null;
  const map=Object.fromEntries((profiles||[]).map((p:any)=>[p.id,p]));
  return normalizeSocialFriends((rels||[]).map((r:any)=>({
    ...r,
    direction:r.requester_id===a.user.id?"outgoing":"incoming",
    other:map[r.requester_id===a.user.id?r.addressee_id:r.requester_id]||null
  })),a.user.id);
}

export async function GET(req:NextRequest){
  const a=await auth(req);
  if(!a)return NextResponse.json({error:"Нужен вход."},{status:401});
  const search=(req.nextUrl.searchParams.get("search")||"").trim().replace(/^@/,"").toLowerCase();

  if(search){
    const {data}=await a.service.from("public_profiles")
      .select("id,username,display_name,level,xp,rating_points,ai_score,avatar_url,school_name")
      .ilike("username",search)
      .neq("id",a.user.id)
      .limit(8);
    return NextResponse.json({results:data||[]});
  }

  const canary=await trySocialFriendsCanary(a.token);
  if(canary.attempted&&canary.value){
    after(async()=>recordSocialFriendsCanaryComparison(canary.value!,await readLegacyFriends(a)));
    return NextResponse.json(canary.value,{headers:{"Cache-Control":"no-store"}});
  }

  const legacy=await readLegacyFriends(a);
  if(!legacy)return NextResponse.json({error:"Не удалось загрузить список друзей."},{status:503});
  if(!socialFriendsCanaryEnabled()&&socialFriendsShadowEnabled())after(()=>compareSocialFriendsWithGo(a.token,legacy));
  return NextResponse.json(legacy,{headers:{"Cache-Control":"no-store"}});
}

export async function POST(req:NextRequest){
  const a=await auth(req);
  if(!a)return NextResponse.json({error:"Нужен вход."},{status:401});
  const body=await req.json().catch(()=>({}));
  const action=String(body?.action||"");

  if(action==="send"){
    const username=String(body?.username||"").trim().replace(/^@/,"").toLowerCase();
    const {data:target}=await a.service.from("public_profiles").select("id,username").ilike("username",username).maybeSingle();
    if(!target||target.id===a.user.id)return NextResponse.json({error:"Пользователь отсутствует."},{status:404});

    const [{data:me},{data:them}]=await Promise.all([
      a.service.from("profiles").select("onboarding").eq("id",a.user.id).maybeSingle(),
      a.service.from("profiles").select("onboarding").eq("id",target.id).maybeSingle()
    ]);
    if(ageBand(me)!==ageBand(them)){
      return NextResponse.json({error:"Для безопасности дружба доступна только между аккаунтами одной возрастной группы."},{status:403});
    }

    const [low,high]=a.user.id<target.id?[a.user.id,target.id]:[target.id,a.user.id];
    const {data:existing}=await a.service.from("friendships")
      .select("id,status,requester_id,addressee_id")
      .or(`and(requester_id.eq.${low},addressee_id.eq.${high}),and(requester_id.eq.${high},addressee_id.eq.${low})`)
      .maybeSingle();
    if(existing)return NextResponse.json({ok:true,existing});

    const {data,error}=await a.service.from("friendships").insert({
      requester_id:a.user.id,
      addressee_id:target.id,
      status:"pending"
    }).select("id,status").single();
    if(error)return NextResponse.json({error:error.message},{status:400});
    return NextResponse.json({ok:true,relation:data});
  }

  const id=String(body?.id||"");
  if(action==="cancel"&&await tryFriendshipCancelCanary(a.token,id)){
    return NextResponse.json({ok:true},{headers:{"Cache-Control":"no-store"}});
  }
  if((action==="accept"||action==="decline")){
    const canary=await tryFriendshipResponseCanary(a.token,id,action);
    if(canary)return NextResponse.json(canary,{headers:{"Cache-Control":"no-store"}});
  }
  const {data:rel}=await a.service.from("friendships").select("*").eq("id",id).maybeSingle();
  if(!rel){
    if(action==="cancel")return NextResponse.json({ok:true},{headers:{"Cache-Control":"no-store"}});
    return NextResponse.json({error:"Запрос отсутствует."},{status:404});
  }

  if(action==="accept"||action==="decline"){
    const status=action==="accept"?"accepted":"declined";
    if(rel.addressee_id!==a.user.id)return NextResponse.json({error:"Нет доступа."},{status:403});
    if(rel.status===status)return NextResponse.json({ok:true,status},{headers:{"Cache-Control":"no-store"}});
    if(rel.status!=="pending")return NextResponse.json({error:"Нет доступа."},{status:403});
    const {error}=await a.service.from("friendships").update({status,responded_at:new Date().toISOString()}).eq("id",id);
    if(error)return NextResponse.json({error:error.message},{status:500});
    return NextResponse.json({ok:true,status},{headers:{"Cache-Control":"no-store"}});
  }

  if(action==="cancel"){
    if(rel.requester_id!==a.user.id||rel.status!=="pending")return NextResponse.json({error:"Нет доступа."},{status:403});
    await a.service.from("friendships").delete().eq("id",id);
    return NextResponse.json({ok:true},{headers:{"Cache-Control":"no-store"}});
  }

  return NextResponse.json({error:"Неизвестное действие."},{status:400});
}

import {NextRequest,NextResponse} from "next/server";
import {createGroupAiReply,moderateGroupMessage} from "@/lib/content-moderation";
import {getSupabaseServiceClient,getUserFromAccessToken} from "@/lib/server-supabase";

function token(req:NextRequest){
  const header=req.headers.get("authorization");
  return header?.startsWith("Bearer ")?header.slice(7):null;
}

async function access(req:NextRequest,groupId:string){
  const user=await getUserFromAccessToken(token(req));
  const service=getSupabaseServiceClient();
  if(!user||!service)return null;
  const {data:member}=await service.from("study_group_members")
    .select("member_role")
    .eq("group_id",groupId)
    .eq("user_id",user.id)
    .maybeSingle();
  return member?{user,service}:null;
}

async function messages(service:any,groupId:string){
  const {data,error}=await service.from("group_messages")
    .select("id,author_id,sender_kind,content,created_at")
    .eq("group_id",groupId)
    .eq("status","published")
    .order("created_at",{ascending:false})
    .limit(80);
  if(error)throw error;
  const rows=(data||[]).reverse();
  const authorIds=Array.from(new Set(rows.map((row:any)=>row.author_id).filter(Boolean))) as string[];
  const {data:profiles}=authorIds.length
    ?await service.from("public_profiles").select("id,username,display_name").in("id",authorIds)
    :{data:[]};
  const profileMap=Object.fromEntries((profiles||[]).map((profile:any)=>[profile.id,profile]));
  return rows.map((row:any)=>({
    id:row.id,
    senderKind:row.sender_kind,
    content:row.content,
    createdAt:row.created_at,
    author:row.sender_kind==="ai"?"Помощник KIVRONIX":profileMap[row.author_id]?.display_name||"Участник",
    username:profileMap[row.author_id]?.username||null
  }));
}

export async function GET(req:NextRequest,{params}:{params:Promise<{groupId:string}>}){
  const {groupId}=await params;
  const granted=await access(req,groupId);
  if(!granted)return NextResponse.json({error:"Чат доступен только участникам группы."},{status:403});
  try{
    return NextResponse.json({messages:await messages(granted.service,groupId)});
  }catch{
    return NextResponse.json({error:"Ошибка загрузки чата."},{status:503});
  }
}

export async function POST(req:NextRequest,{params}:{params:Promise<{groupId:string}>}){
  const {groupId}=await params;
  const granted=await access(req,groupId);
  if(!granted)return NextResponse.json({error:"Чат доступен только участникам группы."},{status:403});

  const body=await req.json().catch(()=>({}));
  const content=String(body?.content||"").trim();
  if(!content)return NextResponse.json({error:"Напиши сообщение."},{status:400});
  if(content.length>1400)return NextResponse.json({error:"Сообщение должно быть короче 1400 символов."},{status:400});

  const {data:last}=await granted.service.from("group_messages")
    .select("created_at")
    .eq("group_id",groupId)
    .eq("author_id",granted.user.id)
    .order("created_at",{ascending:false})
    .limit(1)
    .maybeSingle();
  if(last&&Date.now()-new Date(last.created_at).getTime()<1200){
    return NextResponse.json({error:"Слишком быстро. Подожди секунду и отправь снова."},{status:429});
  }

  const moderation=await moderateGroupMessage(content);
  if(!moderation.allowed){
    await granted.service.from("group_messages").insert({
      group_id:groupId,
      author_id:granted.user.id,
      sender_kind:"user",
      content:"Сообщение скрыто модерацией.",
      status:"removed",
      moderation_reason:moderation.reason||"policy"
    });
    return NextResponse.json({error:moderation.message||"Система остановила сообщение."},{status:422});
  }

  const {error:insertError}=await granted.service.from("group_messages").insert({
    group_id:groupId,
    author_id:granted.user.id,
    sender_kind:"user",
    content,
    status:"published"
  });
  if(insertError)return NextResponse.json({error:"Ошибка отправки сообщения."},{status:503});

  const asksAi=/^\s*\/ai\b/i.test(content)||/@kivronix\b/i.test(content)||content.includes("?");
  if(asksAi){
    const {data:recent}=await granted.service.from("group_messages")
      .select("sender_kind,content")
      .eq("group_id",groupId)
      .eq("status","published")
      .order("created_at",{ascending:false})
      .limit(8);
    const context=(recent||[]).reverse().map((item:any)=>(item.sender_kind==="ai"?"Помощник KIVRONIX: ":"Участник: ")+item.content);
    const cleanQuestion=content.replace(/^\s*\/ai\s*/i,"").replace(/@kivronix\b/ig,"").trim();
    const reply=await createGroupAiReply(cleanQuestion||content,context);
    await granted.service.from("group_messages").insert({
      group_id:groupId,
      author_id:null,
      sender_kind:"ai",
      content:reply.slice(0,3000),
      status:"published"
    });
  }

  return NextResponse.json({ok:true,messages:await messages(granted.service,groupId)});
}

import {after,NextRequest,NextResponse} from "next/server";
import {getSupabaseServiceClient,getUserFromAccessToken} from "@/lib/server-supabase";
import {compareSocialGroupsWithGo,normalizeSocialGroups,socialGroupsShadowEnabled} from "@/lib/go-social-groups-shadow";
import {recordSocialGroupsCanaryComparison,socialGroupsCanaryEnabled,trySocialGroupsCanary} from "@/lib/go-social-groups-canary";

function token(req:NextRequest){
  const h=req.headers.get("authorization");
  return h?.startsWith("Bearer ")?h.slice(7):null;
}

async function auth(req:NextRequest){
  const accessToken=token(req);
  const user=await getUserFromAccessToken(accessToken);
  const service=getSupabaseServiceClient();
  return user&&service&&accessToken?{user,service,token:accessToken}:null;
}

function scope(profile:any){
  return profile?.onboarding?.ageGroup||"18+";
}

async function readLegacyGroups(a:NonNullable<Awaited<ReturnType<typeof auth>>>){
  const {data:memberships,error:membershipError}=await a.service.from("study_group_members")
    .select("group_id,member_role")
    .eq("user_id",a.user.id)
    .order("joined_at",{ascending:false})
    .limit(20);
  if(membershipError)return null;
  const ids=(memberships||[]).map((m:any)=>m.group_id);
  if(!ids.length)return {groups:[]};

  const {data:groups,error:groupsError}=await a.service.from("study_groups")
    .select("id,name,description,owner_id,age_scope,join_code,max_members,created_at")
    .in("id",ids)
    .limit(20);
  if(groupsError)return null;

  const result=await Promise.all((groups||[]).map(async(g:any)=>{
    const {data:members,error:membersError}=await a.service.from("study_group_members")
      .select("user_id,member_role,joined_at")
      .eq("group_id",g.id)
      .limit(100);
    if(membersError)throw new Error("members_unavailable");

    const userIds=(members||[]).map((m:any)=>m.user_id);
    const {data:profiles,error:profilesError}=userIds.length
      ? await a.service.from("public_profiles")
          .select("id,username,display_name,level,xp,rating_points,ai_score,avatar_url,school_name")
          .in("id",userIds)
      : {data:[] as any[],error:null};
    if(profilesError)throw new Error("profiles_unavailable");

    const pmap=Object.fromEntries((profiles||[]).map((p:any)=>[p.id,p]));
    return {
      ...g,
      members:(members||[])
        .map((m:any)=>({...m,profile:pmap[m.user_id]||null}))
        .sort((x:any,y:any)=>(y.profile?.rating_points||0)-(x.profile?.rating_points||0))
    };
  }));

  return normalizeSocialGroups(result,true);
}

export async function GET(req:NextRequest){
  const a=await auth(req);
  if(!a)return NextResponse.json({error:"Нужен вход."},{status:401});

  try{
    const canary=await trySocialGroupsCanary(a.token);
    if(canary.attempted&&canary.value){
      after(async()=>recordSocialGroupsCanaryComparison(canary.value!,await readLegacyGroups(a)));
      return NextResponse.json(canary.value,{headers:{"Cache-Control":"no-store"}});
    }

    const legacy=await readLegacyGroups(a);
    if(!legacy)return NextResponse.json({error:"Не удалось загрузить учебные группы."},{status:503});
    if(!socialGroupsCanaryEnabled()&&socialGroupsShadowEnabled())after(()=>compareSocialGroupsWithGo(a.token,legacy));
    return NextResponse.json(legacy,{headers:{"Cache-Control":"no-store"}});
  }catch{
    return NextResponse.json({error:"Не удалось загрузить учебные группы."},{status:503});
  }
}

export async function POST(req:NextRequest){
  const a=await auth(req);
  if(!a)return NextResponse.json({error:"Нужен вход."},{status:401});

  const body=await req.json().catch(()=>({}));
  const action=String(body?.action||"");
  const {data:profile}=await a.service.from("profiles")
    .select("onboarding")
    .eq("id",a.user.id)
    .maybeSingle();
  const myScope=scope(profile);

  if(action==="create"){
    const name=String(body?.name||"").trim().slice(0,80);
    const description=String(body?.description||"").trim().slice(0,300);
    if(name.length<2)return NextResponse.json({error:"Название группы слишком короткое."},{status:400});

    const {data,error}=await a.service.from("study_groups").insert({
      owner_id:a.user.id,
      name,
      description,
      age_scope:myScope
    }).select("id,name,description,join_code,age_scope,max_members").single();

    if(error)return NextResponse.json({error:error.message},{status:400});
    return NextResponse.json({ok:true,group:data});
  }

  if(action==="join"){
    const code=String(body?.code||"").trim().toUpperCase();
    const {data:group}=await a.service.from("study_groups")
      .select("id,name,age_scope,max_members")
      .eq("join_code",code)
      .maybeSingle();

    if(!group)return NextResponse.json({error:"Группа с таким кодом отсутствует."},{status:404});
    if(group.age_scope!==myScope){
      return NextResponse.json({error:"Эта группа относится к другой возрастной категории."},{status:403});
    }

    const {count}=await a.service.from("study_group_members")
      .select("user_id",{count:"exact",head:true})
      .eq("group_id",group.id);

    if((count||0)>=(group.max_members||10)){
      return NextResponse.json({error:"В группе уже нет свободных мест."},{status:409});
    }

    const {error}=await a.service.from("study_group_members").upsert({
      group_id:group.id,
      user_id:a.user.id,
      member_role:"member"
    },{onConflict:"group_id,user_id"});

    if(error)return NextResponse.json({error:error.message},{status:400});
    return NextResponse.json({ok:true,group});
  }

  return NextResponse.json({error:"Неизвестное действие."},{status:400});
}

import {after,NextRequest,NextResponse} from "next/server";
import {compareSocialRankingWithGo,normalizeSocialRanking,socialRankingShadowEnabled} from "@/lib/go-social-shadow";
import {recordSocialRankingCanaryComparison,socialRankingCanaryEnabled,trySocialRankingCanary} from "@/lib/go-social-canary";
import {getSocialRanking,getUserFromAccessToken} from "@/lib/server-supabase";

function bearer(req:NextRequest){
  const header=req.headers.get("authorization")||"";
  const match=/^Bearer ([^\s]+)$/i.exec(header);
  return match?.[1]||null;
}

export async function GET(req:NextRequest){
  const token=bearer(req);
  const user=await getUserFromAccessToken(token);
  if(!user||!token)return NextResponse.json({error:"Нужен вход в аккаунт."},{status:401});

  const canary=await trySocialRankingCanary(token);
  if(canary.attempted&&canary.value){
    after(async()=>{
      try{
        const {data,error}=await getSocialRanking(token);
        const legacy=!error?normalizeSocialRanking(data,user.id):null;
        recordSocialRankingCanaryComparison(canary.value!,legacy);
      }catch{
        recordSocialRankingCanaryComparison(canary.value!,null);
      }
    });
    return NextResponse.json(canary.value,{headers:{"Cache-Control":"no-store"}});
  }

  const {data,error}=await getSocialRanking(token);
  if(error)return NextResponse.json({error:"Не удалось загрузить рейтинг."},{status:503});
  const legacy=normalizeSocialRanking(data,user.id);
  if(!legacy)return NextResponse.json({error:"Данные рейтинга повреждены."},{status:500});

  if(!socialRankingCanaryEnabled()&&socialRankingShadowEnabled())after(()=>compareSocialRankingWithGo(token,legacy));
  return NextResponse.json(legacy,{headers:{"Cache-Control":"no-store"}});
}

