import Link from "next/link";
import { notFound } from "next/navigation";
import { createClient } from "@supabase/supabase-js";
import { getSupabaseServiceClient } from "@/lib/server-supabase";
import ProfileAvatar from "@/components/profile-avatar";

type PortfolioItem={id:string;title:string;video_url:string;display_url?:string;tags:string[];ai_score:number|null};

export default async function PublicPortfolio({params}:{params:Promise<{username:string}>}) {
  const {username}=await params;
  const url=process.env.NEXT_PUBLIC_SUPABASE_URL;
  const key=process.env.NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY;

  let profile:any=null;
  let items:PortfolioItem[]=[];

  if(url&&key){
    const supabase=createClient(url,key,{auth:{persistSession:false}});
    const {data}=await supabase.from("public_profiles")
      .select("id,display_name,username,level,ai_score,skills,avatar_url,school_name")
      .eq("username",username).maybeSingle();
    profile=data;
    if(profile){
      const {data:portfolio}=await supabase.from("portfolio_items")
        .select("id,title,video_url,tags,ai_score")
        .eq("editor_id",profile.id)
        .order("created_at",{ascending:false});
      items=(portfolio||[]) as PortfolioItem[];
      const service=getSupabaseServiceClient();
      if(service){
        items=await Promise.all(items.map(async item=>{
          if(/^https?:\/\//.test(item.video_url))return {...item,display_url:item.video_url};
          const {data:signed}=await service.storage.from("challenge-submissions").createSignedUrl(item.video_url,60*15);
          return {...item,display_url:signed?.signedUrl||""};
        }));
      }else{
        items=items.map(item=>({...item,display_url:/^https?:\/\//.test(item.video_url)?item.video_url:""}));
      }
    }
  }

  if(!profile&&username==="demo"){
    profile={display_name:"Учебный монтажёр KIVRONIX",username:"demo",level:5,ai_score:82,skills:["Короткие ролики","CapCut","Видео с экспертом"]};
    items=[
      {id:"1",title:"VOLT · Реклама спортзала",video_url:"",tags:["реклама","короткий ролик"],ai_score:91},
      {id:"2",title:"Финансовый эксперт",video_url:"",tags:["видео с экспертом"],ai_score:86},
      {id:"3",title:"Конкурс North Coffee",video_url:"",tags:["победитель","работа для компании"],ai_score:90},
    ];
  }

  if(!profile) notFound();

  return <main className="public-portfolio">
    <div className="portfolio-shell">
      <nav className="pricing-nav"><Link href="/" className="brand">KIVRONIX<span>.</span></Link><Link href="/signup">Создать свой профиль</Link></nav>
      <div className="portfolio-hero">
        <div className="portfolio-person"><ProfileAvatar src={profile.avatar_url} name={profile.display_name} size="lg"/><div><div className="eyebrow">ПРОФИЛЬ МОНТАЖЁРА</div><h1>{profile.display_name}</h1><p>@{profile.username}{profile.school_name?" · "+profile.school_name:""}</p></div></div>
        <div className="portfolio-score"><strong>{profile.ai_score||"—"}</strong><span>Оценка навыка</span></div>
      </div>
      <div className="portfolio-tags">{(profile.skills||[]).map((s:string)=><span className="tag" key={s}>{s}</span>)}</div>
      <section className="portfolio-work-grid">
        {items.length?items.map(item=><article className="portfolio-work" key={item.id}>
          <div className="work-preview">{item.display_url&&isDirectVideo(item.display_url)?<video controls preload="metadata" src={item.display_url}/>:<span>РАБОТА KIVRONIX</span>}</div>
          <h2>{item.title}</h2>
          <div className="work-meta"><span>{(item.tags||[]).join(" · ")}</span>{item.ai_score!=null&&<b>Оценка {item.ai_score}</b>}</div>{item.display_url&&!isDirectVideo(item.display_url)&&<a className="work-link" href={item.display_url} target="_blank" rel="noreferrer">Открыть работу ↗</a>}
        </article>):<div className="legal-card"><p>Портфолио пока пустое.</p></div>}
      </section>
    </div>
  </main>
}

function isDirectVideo(url:string){return /\\.(mp4|webm|mov)(\\?|$)/i.test(url)||url.includes("supabase")}

"use client";

import Link from "next/link";
import {useEffect,useMemo,useState} from "react";
import {academyAssessmentConfig} from "@/lib/academy-assessment";
import {extractVideoFrames} from "@/lib/video-frames";
import {getFreshAccessToken} from "@/lib/supabase-browser";
import {curriculumModules} from "@/lib/curriculum";

type Review={
  name:string;
  overall_score:number;
  hook_score:number;
  pacing_score:number;
  subtitles_score:number;
  visual_variety_score:number;
  brief_match_score:number;
  format_score:number;
  summary:string;
  strengths:string[];
  next_steps:string[];
};

export default function AcademyAssessment({moduleIndex,moduleName,final=false}:{moduleIndex:number;moduleName:string;final?:boolean}){
  const config=useMemo(()=>academyAssessmentConfig(moduleIndex),[moduleIndex]);
  const [files,setFiles]=useState<File[]>([]);
  const [answers,setAnswers]=useState<Record<number,number>>({});
  const [results,setResults]=useState<Review[]>([]);
  const [busy,setBusy]=useState(false);
  const [message,setMessage]=useState("");
  const [passed,setPassed]=useState(false);
  const [checking,setChecking]=useState(true);
  const average=results.length?Math.round(results.reduce((sum,item)=>sum+item.overall_score,0)/results.length):0;
  const nextLessonSlug=curriculumModules[moduleIndex+1]?.lessons[0]?.slug||null;

  useEffect(()=>{
    let active=true;
    async function load(){
      try{
        const token=await getFreshAccessToken();
        if(!token)return;
        const response=await fetch("/api/academy/assessments",{headers:{Authorization:"Bearer "+token},cache:"no-store"});
        const data=await response.json();
        if(active&&response.ok&&Array.isArray(data.passed))setPassed(data.passed.includes(moduleIndex));
      }catch{}finally{if(active)setChecking(false)}
    }
    void load();
    return()=>{active=false};
  },[moduleIndex]);

  function chooseFiles(list:FileList|null){
    const selected=Array.from(list||[]).filter(file=>file.type.startsWith("video/")).slice(0,config.requiredVideos);
    setFiles(selected);
    setResults([]);
    setMessage(selected.length?`${selected.length} из ${config.requiredVideos} видео готовы к проверке.`:"");
  }

  async function review(){
    if(files.length!==config.requiredVideos){setMessage(`Для этой ступени добавь ${config.requiredVideos} ${videoWord(config.requiredVideos)}.`);return}
    if(Object.keys(answers).length!==config.questions.length){setMessage("Ответь на все вопросы проверки знаний.");return}
    setBusy(true);setMessage("");setResults([]);
    try{
      const accessToken=await getFreshAccessToken();
      if(!accessToken)throw new Error("Войди в аккаунт, чтобы ИИ оценил работы.");
      const reviewed:Review[]=[];
      for(let index=0;index<files.length;index++){
        setMessage(`ИИ изучает видео ${index+1} из ${config.requiredVideos}: выбирает кадры и сверяет критерии…`);
        const extracted=await extractVideoFrames(files[index],8);
        const response=await fetch("/api/ai/video-review",{
          method:"POST",
          headers:{"Content-Type":"application/json",Authorization:"Bearer "+accessToken},
          body:JSON.stringify({
            frames:extracted.frames,
            duration:extracted.duration,
            width:extracted.width,
            height:extracted.height,
            filename:files[index].name,
            brief:`Аттестация ступени «${moduleName}». Задание: ${config.task} Критерии: ${config.criteria.join(", ")}.`,
            purpose:"academy_assessment",
            moduleIndex,
            difficulty:config.difficulty,
          })
        });
        const data=await response.json();
        if(!response.ok||!data.review)throw new Error(data?.error||"Одна из работ пока не разобрана.");
        const item:Review={name:files[index].name,...data.review};
        reviewed.push(item);
        setResults([...reviewed]);
      }
      const response=await fetch("/api/academy/assessments",{
        method:"POST",
        headers:{"Content-Type":"application/json",Authorization:"Bearer "+accessToken},
        body:JSON.stringify({
          moduleIndex,
          moduleName,
          final,
          answers:config.questions.map((_,index)=>answers[index]),
          videoCount:reviewed.length,
          reviews:reviewed.map(item=>({overall_score:item.overall_score})),
        })
      });
      const data=await response.json();
      if(!response.ok)throw new Error(data?.error||"Аттестация пока не пройдена.");
      setPassed(true);
      try{
        const saved=JSON.parse(localStorage.getItem("kivronix_academy_assessments")||"[]");
        const next=Array.isArray(saved)&&saved.includes(moduleIndex)?saved:[...(Array.isArray(saved)?saved:[]),moduleIndex];
        localStorage.setItem("kivronix_academy_assessments",JSON.stringify(next));
      }catch{}
      setMessage(final?"Финальная аттестация пройдена. Полный маршрут завершён.":"Аттестация пройдена. Следующий блок обучения открыт.");
    }catch(error){setMessage(error instanceof Error?error.message:"Не удалось провести аттестацию.")}
    finally{setBusy(false)}
  }

  if(checking)return <section className="assessment-loading"><span className="assessment-ai-orb">✦</span><b>Проверяем прогресс аттестации…</b></section>;

  if(passed)return <section className="assessment-success">
    <div className="assessment-success-mark">✓</div>
    <div><div className="eyebrow">УРОВЕНЬ ПОДТВЕРЖДЁН</div><h1>{final?"Маршрут завершён":"Следующий блок уже открыт"}</h1><p>{final?"Ты прошёл финальную проверку знаний и работ. Можно возвращаться к урокам и усиливать портфолио.":"Результат сохранён в профиле. Возвращайся в Академию — уроки следующей ступени уже доступны."}</p>{results.length?<b>Средняя ИИ‑оценка: {average}/100</b>:null}</div>
    <Link className="btn btn-lime" href={final||!nextLessonSlug?"/platform#academy":"/academy/"+nextLessonSlug}>{final?"Вернуться в Академию":"Открыть первый урок следующего блока →"}</Link>
  </section>;

  return <div className="assessment-workspace">
    <section className="assessment-hero-panel">
      <div><div className="eyebrow">{final?"ВЫПУСК · УРОВЕНЬ PRO":`АТТЕСТАЦИЯ · СТУПЕНЬ ${moduleIndex+1}`}</div><h1>{moduleName}</h1><p>{final?"Финальная проверка объединяет навыки всего маршрута. Покажи лучшие работы и подтверди готовность к самостоятельным проектам.":config.task}</p><div className="assessment-criteria">{config.criteria.map(item=><span key={item}>✓ {item}</span>)}</div></div>
      <div className="assessment-threshold-large"><strong>{config.threshold}</strong><span>проходной балл</span><small>{config.difficulty}</small></div>
    </section>

    <div className="assessment-progress-row">
      <span className={files.length===config.requiredVideos?"done":"active"}><b>1</b>Добавь видео</span>
      <span className={Object.keys(answers).length===config.questions.length?"done":files.length===config.requiredVideos?"active":""}><b>2</b>Ответь на вопросы</span>
      <span className={results.length?"active":""}><b>3</b>Получи ИИ-разбор</span>
      <span><b>4</b>{final?"Получи выпуск":"Открой блок"}</span>
    </div>

    <div className="assessment-main-grid">
      <div className="assessment-primary-column">
        <section className="assessment-panel">
          <header><div><div className="eyebrow">РАБОТЫ ДЛЯ ПРОВЕРКИ</div><h2>{config.requiredVideos} {videoWord(config.requiredVideos)} по сложности ступени</h2></div><span>{files.length}/{config.requiredVideos}</span></header>
          <p className="assessment-privacy">Полное видео остаётся на устройстве. Для ИИ-проверки браузер отправит только 8 ключевых кадров, длительность и размер.</p>
          <label className="assessment-dropzone">
            <span className="assessment-upload-icon">↥</span>
            <b>{files.length?"Заменить выбранные видео":"Выбрать видео"}</b>
            <small>MP4, MOV или WebM · одновременно до {config.requiredVideos}</small>
            <input type="file" accept="video/mp4,video/quicktime,video/webm,video/*" multiple={config.requiredVideos>1} onChange={event=>chooseFiles(event.target.files)}/>
          </label>
          {files.length?<div className="assessment-file-list">{files.map((file,index)=><article key={`${file.name}-${file.lastModified}`}><span>{index+1}</span><div><b>{file.name}</b><small>{formatBytes(file.size)}</small></div><button type="button" aria-label={`Убрать ${file.name}`} onClick={()=>{setFiles(current=>current.filter((_,itemIndex)=>itemIndex!==index));setResults([])}}>×</button></article>)}</div>:null}
        </section>

        <section className="assessment-panel assessment-quiz-light">
          <div className="eyebrow">ПРОВЕРКА ЗНАНИЙ</div><h2>Три коротких вопроса</h2><p>Нужно набрать минимум {config.quizThreshold} баллов. Ответы относятся к урокам этой ступени.</p>
          <div className="assessment-question-list">{config.questions.map((item,index)=><fieldset key={item.question}><legend><span>{index+1}</span>{item.question}</legend>{item.answers.map((answer,answerIndex)=><label className={answers[index]===answerIndex?"selected":""} key={answer}><input type="radio" name={`assessment-${moduleIndex}-${index}`} checked={answers[index]===answerIndex} onChange={()=>setAnswers(current=>({...current,[index]:answerIndex}))}/><span>{answer}</span></label>)}</fieldset>)}</div>
        </section>

        <button className="assessment-submit" type="button" disabled={busy} onClick={()=>void review()}><span>{busy?"✦":"→"}</span><div><b>{busy?"ИИ проводит проверку…":final?"Сдать выпускной экзамен":"Проверить работы и открыть следующий блок"}</b><small>{busy?"Можно оставаться на странице — результаты появятся ниже.":`Видео: ${files.length}/${config.requiredVideos} · тест: ${Object.keys(answers).length}/${config.questions.length}`}</small></div></button>
        {message?<div className="assessment-message">{message}</div>:null}
      </div>

      <aside className="assessment-ai-column">
        <section className="assessment-ai-card"><span className="assessment-ai-orb">✦</span><div><div className="eyebrow">ИИ-ЭКСПЕРТ KIVRONIX</div><h3>Проверка по твоему уровню</h3><p>ИИ сравнит каждую работу с критериями ступени, отметит сильные стороны и даст конкретные действия для роста.</p></div><dl><div><dt>Сложность</dt><dd>{config.difficulty}</dd></div><div><dt>Видео</dt><dd>{config.requiredVideos}</dd></div><div><dt>Проходной балл</dt><dd>{config.threshold}/100</dd></div><div><dt>Мини‑тест</dt><dd>{config.quizThreshold}/100</dd></div></dl></section>
        {results.length?<section className="assessment-live-score"><div><span>Средний балл</span><strong>{average}</strong></div><div className="assessment-score-bar"><i style={{width:`${average}%`}}/></div><small>{average>=config.threshold?"Баллов достаточно. Проверяем тест и сохраняем результат.":`До проходного уровня: ${Math.max(0,config.threshold-average)} баллов.`}</small></section>:null}
      </aside>
    </div>

    {results.length?<section className="assessment-review-results"><header><div className="eyebrow">РЕЗУЛЬТАТЫ ИИ-ПРОВЕРКИ</div><h2>Разбор каждой работы</h2></header><div>{results.map(result=><article key={result.name}><header><div><small>{result.name}</small><h3>{result.summary}</h3></div><strong>{result.overall_score}<span>/100</span></strong></header><div className="assessment-mini-scores"><span>Начало <b>{result.hook_score}</b></span><span>Темп <b>{result.pacing_score}</b></span><span>Субтитры <b>{result.subtitles_score}</b></span><span>Задание <b>{result.brief_match_score}</b></span></div>{result.strengths?.length?<p><b>Уже хорошо:</b> {result.strengths.slice(0,2).join(" · ")}</p>:null}{result.next_steps?.length?<ol>{result.next_steps.slice(0,3).map(step=><li key={step}>{step}</li>)}</ol>:null}</article>)}</div></section>:null}
  </div>;
}

function videoWord(value:number){return value===1?"ролик":"ролика"}
function formatBytes(value:number){return value>=1024*1024?`${(value/1024/1024).toFixed(1)} МБ`:`${Math.max(1,Math.round(value/1024))} КБ`}

"use client";

import {FormEvent,useEffect,useMemo,useRef,useState} from "react";
import {getSupabaseBrowserClient} from "@/lib/supabase-browser";
import type {AiChatMessage} from "@/lib/ai-history";
import {extractVideoFrames} from "@/lib/video-frames";

type CoachContext={
  level?:string;
  editor?:string;
  goal?:string;
  role?:string|null;
  xp?:number;
  completedLessons?:string[];
  lessonSlug?:string;
  lessonTitle?:string;
  lessonSummary?:string;
  lessonSteps?:string[];
  plan?:string;
};

type AiCoachProps={
  scopeKey:string;
  title?:string;
  welcome?:string;
  prompts?:string[];
  context?:CoachContext;
  compact?:boolean;
};

const defaultWelcome="Привет! Спроси обычными словами. Я объясню коротко, покажу шаги и скажу, как проверить результат.";

export default function AiCoach({scopeKey,title="Помощник KIVRONIX",welcome=defaultWelcome,prompts=[],context={},compact=false}:AiCoachProps){
  const localKey=useMemo(()=>"kivronix_ai_chat_v1:"+scopeKey,[scopeKey]);
  const [messages,setMessages]=useState<AiChatMessage[]>([{from:"ai",text:welcome}]);
  const [input,setInput]=useState("");
  const [loading,setLoading]=useState(false);
  const [historyLoading,setHistoryLoading]=useState(true);
  const [storageMode,setStorageMode]=useState<"account"|"browser">("browser");
  const [notice,setNotice]=useState("");
  const [file,setFile]=useState<File|null>(null);
  const [feedback,setFeedback]=useState<Record<string,"helpful"|"needs_work">>({});
  const [feedbackDraft,setFeedbackDraft]=useState<{id:string;comment:string}|null>(null);
  const feedRef=useRef<HTMLDivElement>(null);
  const textareaRef=useRef<HTMLTextAreaElement>(null);
  const fileRef=useRef<HTMLInputElement>(null);


  useEffect(()=>{
    let active=true;
    async function load(){
      try{
        const supabase=getSupabaseBrowserClient();
        const {data:{session}}=await supabase.auth.getSession();
        if(session?.access_token){
          const params=new URLSearchParams({scope:scopeKey,title});
          const response=await fetch("/api/ai/history?"+params,{headers:{Authorization:"Bearer "+session.access_token},cache:"no-store"});
          if(response.ok){
            const data=await response.json();
            if(active){
              setStorageMode("account");
              setMessages(data.messages?.length?data.messages:[{from:"ai",text:welcome}]);
            }
            return;
          }
        }
        const raw=localStorage.getItem(localKey);
        const saved=raw?JSON.parse(raw):null;
        if(active&&Array.isArray(saved)&&saved.length)setMessages(saved.slice(-80));
      }catch{}
      finally{if(active)setHistoryLoading(false)}
    }
    void load();
    return()=>{active=false};
  },[localKey,scopeKey,title,welcome]);

  useEffect(()=>{
    if(historyLoading||storageMode!=="browser")return;
    try{localStorage.setItem(localKey,JSON.stringify(messages.slice(-80)))}catch{}
  },[historyLoading,localKey,messages,storageMode]);

  useEffect(()=>{
    const feed=feedRef.current;
    if(feed)feed.scrollTo({top:feed.scrollHeight,behavior:"smooth"});
  },[messages,loading,historyLoading]);

  function resizeInput(value:string){
    setInput(value);
    const area=textareaRef.current;
    if(area){area.style.height="auto";area.style.height=Math.min(180,area.scrollHeight)+"px"}
  }

  async function send(text:string){
    const question=text.trim()||(file?"Разбери этот файл и скажи, что улучшить в моём ролике.":"");
    if(!question||loading)return;
    const shownQuestion=(file?"Файл: "+file.name+"\n":"")+question;
    const next=[...messages,{from:"user" as const,text:shownQuestion}];
    setMessages(next);setInput("");setLoading(true);setNotice("");
    if(textareaRef.current)textareaRef.current.style.height="auto";
    try{
      const attachment=file?await prepareAttachment(file):null;
      const supabase=getSupabaseBrowserClient();
      const {data:{session}}=await supabase.auth.getSession();
      const headers:Record<string,string>={"Content-Type":"application/json"};
      if(session?.access_token)headers.Authorization="Bearer "+session.access_token;
      const response=await fetch("/api/ai",{
        method:"POST",
        headers,
        body:JSON.stringify({
          message:question,
          context:{...context,scopeKey},
          history:messages.slice(-12),
          attachment
        })
      });
      const data=await response.json();
      const reply=data.reply||"Ответ пока пуст. Попробуй ещё раз чуть позже.";
      setMessages(current=>[...current,{id:data.messageId||undefined,from:"ai",text:reply}]);
      if(data.saved)setStorageMode("account");
      setFile(null);
      if(fileRef.current)fileRef.current.value="";
    }catch(error){
      const reason=error instanceof Error?error.message:"Ошибка обработки запроса или файла.";
      setMessages(current=>[...current,{from:"ai",text:reason+" Проверь файл и попробуй ещё раз."}]);
    }finally{setLoading(false)}
  }

  async function submit(event:FormEvent){event.preventDefault();await send(input)}

  async function clear(){
    setNotice("");
    try{
      if(storageMode==="account"){
        const supabase=getSupabaseBrowserClient();
        const {data:{session}}=await supabase.auth.getSession();
        if(session?.access_token){
          await fetch("/api/ai/history?scope="+encodeURIComponent(scopeKey),{method:"DELETE",headers:{Authorization:"Bearer "+session.access_token}});
        }
      }else localStorage.removeItem(localKey);
      setMessages([{from:"ai",text:welcome}]);
      setNotice("История очищена.");
    }catch{setNotice("Ошибка очистки истории.")}
  }

  async function submitFeedback(messageId:string,helpful:boolean,comment=""){
    try{
      const supabase=getSupabaseBrowserClient();
      const {data:{session}}=await supabase.auth.getSession();
      if(!session?.access_token){setNotice("Оценка ответа сохраняется после входа в аккаунт.");return;}
      const response=await fetch("/api/ai/feedback",{
        method:"POST",
        headers:{"Content-Type":"application/json",Authorization:"Bearer "+session.access_token},
        body:JSON.stringify({messageId,helpful,comment})
      });
      const data=await response.json();
      if(!response.ok)throw new Error(data?.error||"Оценка пока не сохранилась.");
      setFeedback(current=>({...current,[messageId]:helpful?"helpful":"needs_work"}));
      setFeedbackDraft(null);
      setNotice(helpful?"Спасибо — оценка сохранена.":data.queued?"Спасибо. Предложение отправлено администратору на проверку.":"Спасибо — оценка сохранена.");
    }catch(error){setNotice(error instanceof Error?error.message:"Оценка пока не сохранилась.")}
  }

  const profileCoach=scopeKey.startsWith("profile:");

  return <section className={"ai-coach "+(compact?"compact ":"")+(profileCoach?"profile-coach":"")} aria-label={title}>
    <div className="ai-coach-head">
      <div><span className="ai-orb" aria-hidden="true">✦</span><div><b>{title}</b><small>{storageMode==="account"?"Диалог сохраняется в аккаунте":"Диалог сохраняется в этом браузере"}</small></div></div>
      <button type="button" className="ai-clear" onClick={clear}>Очистить</button>
    </div>
    <div className="ai-feed" aria-live="polite" ref={feedRef}>
      {historyLoading?<div className="ai-thinking">Загружаю диалог…</div>:messages.map((message,index)=><article className={"ai-message "+message.from} key={message.id||index}>
        <span>{message.from==="ai"?"Помощник KIVRONIX":"Ты"}</span>
        <AiMessageText text={message.text}/>
        {message.from==="ai"&&message.id?<div className="ai-feedback">
          {feedback[message.id]?<small>{feedback[message.id]==="helpful"?"Отмечено как полезное":"Отправлено на улучшение"}</small>:<><span>Этот ответ помог?</span><button type="button" onClick={()=>void submitFeedback(message.id!,true)}>Да</button><button type="button" onClick={()=>setFeedbackDraft({id:message.id!,comment:""})}>Нужно улучшить</button></>}
          {feedbackDraft?.id===message.id?<div className="ai-feedback-draft"><textarea value={feedbackDraft.comment} maxLength={1000} placeholder="Что было непонятно или неверно? От 20 символов — и отзыв попадёт в очередь улучшений." onChange={event=>setFeedbackDraft({id:message.id!,comment:event.target.value})}/><div><button type="button" className="btn btn-dark" disabled={feedbackDraft.comment.trim().length<20} onClick={()=>void submitFeedback(message.id!,false,feedbackDraft.comment)}>Отправить на проверку</button><button type="button" className="btn btn-ghost" onClick={()=>setFeedbackDraft(null)}>Отмена</button></div></div>:null}
        </div>:null}
      </article>)}
      {loading?<div className="ai-thinking">Разбираю вопрос и готовлю шаги…</div>:null}
    </div>
    {prompts.length?<div className="ai-prompts">{prompts.slice(0,4).map(prompt=><button type="button" key={prompt} onClick={()=>void send(prompt)} disabled={loading}>{prompt}</button>)}</div>:null}
    <div className="ai-file-mode pro"><b>Полный разбор · бесплатно</b><span>До 7 кадров, время каждого кадра и понятный порядок правок</span></div>
    <form className="ai-form" onSubmit={submit}>
      <label className="ai-attach" title="Добавить ролик, кадр, сценарий или субтитры"><span>＋ Файл</span><input ref={fileRef} type="file" accept="video/mp4,video/quicktime,video/webm,image/jpeg,image/png,image/webp,.txt,.srt,.vtt" onChange={event=>{setFile(event.target.files?.[0]||null);setNotice("")}}/></label>
      <textarea ref={textareaRef} value={input} onChange={event=>resizeInput(event.target.value)} maxLength={4000} rows={compact?2:4} placeholder="Напиши вопрос подробно — весь текст будет хорошо виден…"/>
      <button className="btn btn-lime" disabled={loading||(!input.trim()&&!file)}>{loading?"Разбираю…":"Спросить помощника"}</button>
    </form>
    {file?<div className="ai-selected-file">{file.type.startsWith("image/")?<ImageAttachmentPreview file={file}/>:null}<span><b>{file.name}</b> · {formatBytes(file.size)}<small>{file.type.startsWith("image/")?"Помощник увидит изображение и привяжет объяснение к нему.":file.type.startsWith("video/")?"Помощник покажет правки по кадрам и таймкодам.":"Помощник прочитает файл и объяснит его по шагам."}</small></span><button type="button" onClick={()=>{setFile(null);if(fileRef.current)fileRef.current.value=""}}>Убрать</button></div>:null}
    {notice?<div className="ai-notice">{notice}</div>:null}
    <small className="ai-disclaimer">Кнопки в приложениях иногда переезжают после обновлений. Помощник уточнит устройство и версию, когда это важно.</small>
  </section>
}

type PreparedAttachment={kind:"video"|"image"|"text";name:string;mime:string;frames?:Array<{timecode:string;image:string}>;text?:string;duration?:number;width?:number;height?:number};

async function prepareAttachment(file:File):Promise<PreparedAttachment>{
  if(file.type.startsWith("video/")){
    const limit=300*1024*1024;
    if(file.size>limit)throw new Error("Видео слишком большое.");
    const extracted=await extractVideoFrames(file,7);
    return {kind:"video",name:file.name,mime:file.type,frames:extracted.frames.map(frame=>({timecode:frame.timecode,image:frame.image})),duration:extracted.duration,width:extracted.width,height:extracted.height};
  }
  if(file.type.startsWith("image/")){
    if(file.size>8*1024*1024)throw new Error("Изображение должно быть меньше 8 МБ.");
    const image=await imageToJpeg(file);
    return {kind:"image",name:file.name,mime:"image/jpeg",frames:[{timecode:"кадр",image}]};
  }
  if(/\.(txt|srt|vtt)$/i.test(file.name)||file.type.startsWith("text/")){
    if(file.size>2*1024*1024)throw new Error("Текстовый файл должен быть меньше 2 МБ.");
    return {kind:"text",name:file.name,mime:file.type||"text/plain",text:(await file.text()).slice(0,16000)};
  }
  throw new Error("Поддерживаются MP4, MOV, WebM, JPG, PNG, WebP, TXT, SRT и VTT.");
}

function imageToJpeg(file:File){
  return new Promise<string>((resolve,reject)=>{
    const url=URL.createObjectURL(file);
    const img=new Image();
    img.onload=()=>{
      const max=1400;const scale=Math.min(1,max/Math.max(img.naturalWidth,img.naturalHeight));
      const canvas=document.createElement("canvas");
      canvas.width=Math.max(1,Math.round(img.naturalWidth*scale));canvas.height=Math.max(1,Math.round(img.naturalHeight*scale));
      const ctx=canvas.getContext("2d");
      if(!ctx){URL.revokeObjectURL(url);reject(new Error("Ошибка чтения изображения."));return;}
      ctx.drawImage(img,0,0,canvas.width,canvas.height);URL.revokeObjectURL(url);resolve(canvas.toDataURL("image/jpeg",.76));
    };
    img.onerror=()=>{URL.revokeObjectURL(url);reject(new Error("Ошибка чтения изображения."))};
    img.src=url;
  });
}

function formatBytes(bytes:number){
  if(bytes<1024*1024)return Math.max(1,Math.round(bytes/1024))+" КБ";
  return (bytes/1024/1024).toFixed(1)+" МБ";
}

function ImageAttachmentPreview({file}:{file:File}){
  const [url,setUrl]=useState("");
  useEffect(()=>{const next=URL.createObjectURL(file);setUrl(next);return()=>URL.revokeObjectURL(next)},[file]);
  return url?<img className="ai-attachment-preview" src={url} alt="Изображение, добавленное к вопросу"/>:null;
}

function AiMessageText({text}:{text:string}){
  const lines=text.replace(/\r/g,"").split("\n").filter((line,index,all)=>line.trim()||all[index-1]?.trim());
  return <div className="ai-message-text">{lines.map((raw,index)=>{
    const line=raw.trim().replace(/^#{1,4}\s*/,"").replace(/^\*\*(.*?)\*\*:?$/,"$1");
    if(!line)return <span className="ai-space" key={index}/>;
    if(/^\d+[.)]\s/.test(line))return <div className="ai-numbered" key={index}><b>{line.match(/^\d+/)?.[0]}</b><p>{line.replace(/^\d+[.)]\s*/,"")}</p></div>;
    if(/^[-•]\s/.test(line))return <div className="ai-bullet" key={index}><b>•</b><p>{line.replace(/^[-•]\s*/,"")}</p></div>;
    if(/^(Что это|Что сделать|Как проверить|Полезный совет|Лайфхак|Куда нажать|Следующий шаг)[:：]?$/.test(line)){
      const heading=line.replace(/[:：]$/,"");
      return <h4 key={index}>{heading==="Лайфхак"?"Полезный совет":heading}</h4>;
    }
    return <p key={index}>{line.replace(/\*\*/g,"")}</p>;
  })}</div>
}

"use client";

import {useEffect,useState} from "react";
import {usePathname,useRouter} from "next/navigation";
import {getSupabaseBrowserClient} from "@/lib/supabase-browser";

export default function AuthGate({children}:{children:React.ReactNode}){
  const router=useRouter();
  const pathname=usePathname();
  const [allowed,setAllowed]=useState(false);

  useEffect(()=>{
    let active=true;
    const supabase=getSupabaseBrowserClient();
    supabase.auth.getUser().then(({data})=>{
      if(!active)return;
      if(data.user){setAllowed(true);return;}
      const destination=pathname+(window.location.hash||"");
      router.replace("/login?from="+encodeURIComponent(destination));
    }).catch(()=>{
      if(active)router.replace("/login?from="+encodeURIComponent(pathname));
    });
    return()=>{active=false};
  },[pathname,router]);

  if(!allowed)return <main className="auth-wrap"><section className="auth-card auth-check"><div className="auth-spinner"/><h1>Проверяем вход</h1><p>Академия и остальные разделы KIVRONIX доступны после регистрации.</p></section></main>;
  return <>{children}</>;
}

"use client";

import {useEffect,useState} from "react";

export default function BackToTop(){
  const [visible,setVisible]=useState(false);

  useEffect(()=>{
    const update=()=>setVisible(window.scrollY>520);
    update();
    window.addEventListener("scroll",update,{passive:true});
    return()=>window.removeEventListener("scroll",update);
  },[]);

  return <button
    type="button"
    className={"back-to-top "+(visible?"visible":"")}
    aria-label="Вернуться в начало страницы"
    title="Наверх"
    onClick={()=>window.scrollTo({top:0,behavior:"smooth"})}
  >↑<span>Наверх</span></button>;
}

"use client";

import {FormEvent,useEffect,useState} from "react";
import {getSupabaseBrowserClient} from "@/lib/supabase-browser";

type BrandContext={
  audience:string;
  tone:string;
  colors:string;
  references:string;
  editingRules:string;
};

const empty:BrandContext={audience:"",tone:"",colors:"",references:"",editingRules:""};

export default function BrandBrain({viewerName="Компания"}:{viewerName?:string}){
  const [form,setForm]=useState<BrandContext>(empty);
  const [businessId,setBusinessId]=useState<string|null>(null);
  const [message,setMessage]=useState("");

  useEffect(()=>{void load()},[]);

  async function load(){
    const supabase=getSupabaseBrowserClient();
    if(!supabase){
      try{
        const raw=localStorage.getItem("kivronix_brand_brain");
        if(raw)setForm(JSON.parse(raw));
      }catch{}
      return;
    }
    const {data:{user}}=await supabase.auth.getUser();
    if(!user)return;
    let {data}=await supabase.from("businesses").select("id,brand_context").eq("owner_id",user.id).maybeSingle();
    if(!data){
      const {data:created}=await supabase.from("businesses")
        .upsert({owner_id:user.id,name:viewerName+" Studio"},{onConflict:"owner_id"})
        .select("id,brand_context")
        .single();
      data=created;
    }
    if(data){
      setBusinessId(data.id);
      setForm({...empty,...(data.brand_context||{})});
    }
  }

  async function save(e:FormEvent){
    e.preventDefault();
    const supabase=getSupabaseBrowserClient();
    if(!supabase||!businessId){
      localStorage.setItem("kivronix_brand_brain",JSON.stringify(form));
      setMessage("Пример профиля бренда сохранён в этом браузере.");
      return;
    }
    const {error}=await supabase.from("businesses").update({brand_context:form}).eq("id",businessId);
    setMessage(error?error.message:"Профиль бренда сохранён. Помощник сможет учитывать его в новых заданиях и проверках.");
  }

  return <section className="card brand-brain">
    <div className="eyebrow">ПРОФИЛЬ БРЕНДА</div>
    <h3>Правила бренда для всех монтажёров</h3>
