"use client";

import {FormEvent,useEffect,useState} from "react";
import {getSupabaseBrowserClient} from "@/lib/supabase-browser";

type Verification={
  business?:{
    id:string;
    name:string;
    verified:boolean;
    verification_status:string;
    verification_level:string;
    verification_note?:string|null;
  };
  request?:{
    id:string;
    requested_level:string;
    status:string;
    review_note?:string|null;
    created_at:string;
  }|null;
};

export default function BusinessVerification(){
  const [data,setData]=useState<Verification|null>(null);
  const [files,setFiles]=useState<File[]>([]);
  const [loading,setLoading]=useState(false);
  const [message,setMessage]=useState("");
  const [form,setForm]=useState({
    requestedLevel:"verified_company",
    legalName:"",
    inn:"",
    registrationNumber:"",
    websiteUrl:"",
    socialUrl:"",
    reportedAudience:""
  });

  useEffect(()=>{
    try{
      const raw=localStorage.getItem("kivronix_business_verification_prefill");
      if(raw){
        const saved=JSON.parse(raw);
        setForm(v=>({...v,...saved}));
      }
    }catch{}
    void load();
  },[]);

  async function authHeaders():Promise<Record<string,string>>{
    const supabase=getSupabaseBrowserClient();
    const {data:{session}}=await supabase.auth.getSession();
    return session?.access_token?{Authorization:"Bearer "+session.access_token}:{};
  }

  async function load(){
    try{
      const headers=await authHeaders();
      const r=await fetch("/api/business/verification",{headers,cache:"no-store"});
      const json=await r.json();
      if(r.ok)setData(json);
    }catch{}
  }

  async function submit(e:FormEvent){
    e.preventDefault();
    setMessage("");
    if(files.length===0){setMessage("Добавь документ: PDF, JPG или PNG.");return;}
    if(files.length>3){setMessage("Можно добавить до 3 файлов.");return;}
    if(files.some(f=>f.size>15*1024*1024)){setMessage("Размер каждого файла — до 15 МБ.");return;}

    setLoading(true);
    try{
      const supabase=getSupabaseBrowserClient();
      const {data:{user}}=await supabase.auth.getUser();
      const {data:{session}}=await supabase.auth.getSession();
      if(!user||!session?.access_token)throw new Error("Сначала войди в бизнес-аккаунт.");

      const paths:string[]=[];
      for(const file of files){
        const safe=file.name.replace(/[^a-zA-Z0-9._-]/g,"_");
        const path=user.id+"/"+Date.now()+"-"+Math.random().toString(36).slice(2,8)+"-"+safe;
        const up=await supabase.storage.from("business-verification")
          .upload(path,file,{upsert:false,contentType:file.type||"application/octet-stream"});
        if(up.error)throw new Error("Ошибка загрузки документа: "+up.error.message);
        paths.push(path);
      }

      const r=await fetch("/api/business/verification",{
        method:"POST",
        headers:{"Content-Type":"application/json",Authorization:"Bearer "+session.access_token},
        body:JSON.stringify({
          ...form,
          reportedAudience:form.reportedAudience?Number(form.reportedAudience):null,
          documentPaths:paths
        })
      });
      const json=await r.json();
      if(!r.ok)throw new Error(json?.error||"Ошибка отправки заявки.");

      setFiles([]);
      localStorage.removeItem("kivronix_business_verification_prefill");
      setMessage("Заявка отправлена. Проверка проходит вручную: документы и публичные ссылки сверяются человеком.");
      await load();
    }catch(e){
      setMessage(e instanceof Error?e.message:"Ошибка отправки заявки.");
    }finally{setLoading(false)}
  }

  const business=data?.business;
  const request=data?.request;
  const status=business?.verified
    ? badgeName(business.verification_level)
    : request?.status==="pending"||business?.verification_status==="pending"
      ?"На проверке"
      :"Ждёт проверки";

  return <section className="card verification-card">
    <div className="verification-head">
      <div>
        <div className="eyebrow">ПРОВЕРКА БИЗНЕСА</div>
        <h3>Подтверди, кто стоит за заданиями</h3>
      </div>
      <span className={"verification-badge "+(business?.verified?"ok":request?.status==="pending"?"pending":"")}>{status}</span>
    </div>

    <p className="muted">Проверенная компания вызывает больше доверия. Для коммерческих конкурсов и вакансий KIVRONIX сначала проверяет компанию.</p>

    {business?.verified?<div className="verification-success">
      <b>Готово: {badgeName(business.verification_level)}</b>
      <span>Монтажёры будут видеть отметку рядом с названием компании.</span>
    </div>:request?.status==="pending"?<div className="auth-msg">
      Заявка уже отправлена и ждёт ручной проверки. Отметка выдаётся после отдельной сверки публичных страниц и документов.
    </div>:<form className="business-form" onSubmit={submit}>
      <label className="field-label">Какую отметку хочешь получить?</label>
      <select value={form.requestedLevel} onChange={e=>setForm({...form,requestedLevel:e.target.value})}>
        <option value="verified_company">Проверенная компания — по документам</option>
        <option value="popular_brand">Известный бренд — документы + публичные страницы</option>
      </select>

      <input required placeholder="Официальное название компании или ИП" value={form.legalName} onChange={e=>setForm({...form,legalName:e.target.value})}/>
      <div className="split-fields">
        <input inputMode="numeric" placeholder="ИНН: 10 или 12 цифр" value={form.inn} onChange={e=>setForm({...form,inn:e.target.value})}/>
        <input inputMode="numeric" placeholder="ОГРН / ОГРНИП" value={form.registrationNumber} onChange={e=>setForm({...form,registrationNumber:e.target.value})}/>
      </div>
      <input type="url" placeholder="Сайт компании (если есть)" value={form.websiteUrl} onChange={e=>setForm({...form,websiteUrl:e.target.value})}/>
      <input type="url" placeholder="Ссылка на публичную соцсеть бренда" value={form.socialUrl} onChange={e=>setForm({...form,socialUrl:e.target.value})}/>
      <input min="0" type="number" placeholder="Примерный размер аудитории (необязательно)" value={form.reportedAudience} onChange={e=>setForm({...form,reportedAudience:e.target.value})}/>

      <label className="verification-upload">
        <b>Документы</b>
        <span>PDF, JPG или PNG. До 3 файлов, каждый до 15 МБ. Файлы закрыты от других пользователей.</span>
        <input type="file" accept=".pdf,image/jpeg,image/png" multiple onChange={e=>setFiles(Array.from(e.target.files||[]).slice(0,3))}/>
      </label>
      {files.length>0&&<div className="muted">{files.map(f=>f.name).join(" · ")}</div>}

      <button className="btn btn-dark" disabled={loading}>{loading?"Отправляем…":"Отправить на проверку"}</button>
    </form>}

    {request?.status==="rejected"&&<div className="auth-msg">Нужно исправить заявку: {request.review_note||"проверь документы и ссылки и отправь новую заявку."}</div>}
    {message&&<div className="auth-msg">{message}</div>}
    <p className="muted">Отметка «Известный бренд» выдаётся после ручной проверки открытых страниц и документов.</p>
  </section>
}

function badgeName(level?:string){
  if(level==="popular_brand")return "Известный бренд";
  if(level==="partner")return "Партнёр KIVRONIX";
  if(level==="verified_company")return "Проверенная компания";
  return "Проверенный бизнес";
}

"use client";

import {FormEvent,useEffect,useState} from "react";
import {getSupabaseBrowserClient} from "@/lib/supabase-browser";

type League={id:string;name:string;verification_level:string;score:number;campaigns:number;applications:number};
type EditorCampaign={id:string;title:string;goal:string;content_types:string[];budget_text:string;creator_slots:number;requirements:string;ends_at?:string|null;myStatus?:string|null;business?:{name:string;verification_level:string}};
type BusinessApplication={id:string;editor_id:string;portfolio_url?:string|null;note?:string|null;status:string;editor?:{display_name?:string;username?:string}|null};
type BusinessCampaign=EditorCampaign&{applications:BusinessApplication[]};

export default function CampaignHub({mode}:{mode:"editor"|"business"}){
  const [campaigns,setCampaigns]=useState<(EditorCampaign|BusinessCampaign)[]>([]);
  const [league,setLeague]=useState<League[]>([]);
  const [business,setBusiness]=useState<any>(null);
  const [message,setMessage]=useState("");
  const [busy,setBusy]=useState(false);
  const [apply,setApply]=useState<Record<string,{portfolioUrl:string;note:string}>>({});
  const [form,setForm]=useState({
    title:"",
    goal:"",
    budgetText:"",
    creatorSlots:"3",
    requirements:"",
    contentTypes:"Короткие ролики, отзывы"
  });

  useEffect(()=>{void load()},[]);

  async function headers():Promise<Record<string,string>>{
    const supabase=getSupabaseBrowserClient();
    const {data:{session}}=await supabase.auth.getSession();
    return session?.access_token?{Authorization:"Bearer "+session.access_token}:{};
  }

  async function call(body?:any){
    const h=await headers();
    const r=await fetch("/api/campaigns",{
      method:body?"POST":"GET",
      headers:body?{...h,"Content-Type":"application/json"}:h,
      body:body?JSON.stringify(body):undefined,
      cache:"no-store"
    });
    const data=await r.json();
    if(!r.ok)throw new Error(data?.error||"Возникла ошибка. Попробуйте ещё раз.");
    return data;
  }

  async function load(){
    try{
      const d=await call();
      setCampaigns(d.campaigns||[]);
      setLeague(d.league||[]);
      setBusiness(d.business||null);
    }catch(e){setMessage(e instanceof Error?e.message:"Ошибка загрузки проектов.")}
  }

  async function create(e:FormEvent){
    e.preventDefault();setBusy(true);setMessage("");
    try{
      await call({
        action:"create",
        title:form.title,
        goal:form.goal,
        budgetText:form.budgetText,
        creatorSlots:Number(form.creatorSlots)||1,
        requirements:form.requirements,
        contentTypes:form.contentTypes.split(",").map(v=>v.trim()).filter(Boolean)
      });
      setForm({title:"",goal:"",budgetText:"",creatorSlots:"3",requirements:"",contentTypes:"Короткие ролики, отзывы"});
      setMessage("Проект опубликован. Теперь монтажёры могут откликаться внутри KIVRONIX.");
      await load();
    }catch(e){setMessage(e instanceof Error?e.message:"Ошибка.");}
    finally{setBusy(false)}
  }

  async function applyTo(id:string){
    setBusy(true);setMessage("");
    const item=apply[id]||{portfolioUrl:"",note:""};
    try{
      await call({action:"apply",campaignId:id,...item});
      setMessage("Отклик отправлен. Статус заявки теперь виден в карточке проекта; после принятия здесь появится кнопка перехода в рабочий чат.");
      await load();
    }catch(e){setMessage(e instanceof Error?e.message:"Ошибка.");}
    finally{setBusy(false)}
  }

  async function setApplication(id:string,status:string){
    setBusy(true);setMessage("");
    try{
      const result=await call({action:"application_status",applicationId:id,status});
      if(result.conversationId)try{sessionStorage.setItem("kivronix_open_conversation",result.conversationId)}catch{}
      setMessage(status==="accepted"?"Монтажёр принят. Закрытый чат уже открыт.":"Статус обновлён.");
      await load();
    }catch(e){setMessage(e instanceof Error?e.message:"Ошибка.");}
    finally{setBusy(false)}
  }

  return <div className="campaign-hub">
    {message&&<div className="auth-msg">{message}</div>}

    {mode==="business"&&<section className="card">
      <div className="eyebrow">НАБОР МОНТАЖЁРОВ</div>
      <h3>Создать проект для команды</h3>
      <p className="muted">Здесь компания или блогер может собрать несколько монтажёров. Участники получают задачи внутри единого проекта, а после выбора открываются постоянные рабочие чаты с общим контекстом ТЗ.</p>
      {!business?.verified&&<div className="auth-msg">Публиковать кампании может только проверенная компания. Сначала закончи проверку бизнеса выше.</div>}
      <form className="business-form" onSubmit={create}>
        <input required placeholder="Название проекта" value={form.title} onChange={e=>setForm({...form,title:e.target.value})}/>
        <textarea required placeholder="Какой результат нужен компании?" value={form.goal} onChange={e=>setForm({...form,goal:e.target.value})}/>
        <input required placeholder="Условия безопасной сделки внутри KIVRONIX" value={form.budgetText} onChange={e=>setForm({...form,budgetText:e.target.value})}/>
        <div className="split-fields">
          <input min="1" max="100" type="number" placeholder="Сколько монтажёров" value={form.creatorSlots} onChange={e=>setForm({...form,creatorSlots:e.target.value})}/>
          <input placeholder="Форматы через запятую" value={form.contentTypes} onChange={e=>setForm({...form,contentTypes:e.target.value})}/>
        </div>
        <textarea placeholder="Что обязательно должно быть в роликах" value={form.requirements} onChange={e=>setForm({...form,requirements:e.target.value})}/>
        <button className="btn btn-dark" disabled={busy||!business?.verified}>{busy?"Публикуем…":business?.verified?"Опубликовать проект":"Сначала пройти проверку"}</button>
      </form>
    </section>}

    <section className="card">
      <div className="eyebrow">{mode==="business"?"МОИ ПРОЕКТЫ":"ПРОЕКТЫ ПРОВЕРЕННЫХ КОМПАНИЙ"}</div>
      <h3>{mode==="business"?"Монтажёры и отклики":"Отклик отправляется прямо из KIVRONIX"}</h3>
      <div className="business-stack">
        {campaigns.length===0&&<p className="muted">Открытые проекты появятся здесь.</p>}
        {campaigns.map((raw:any)=><article className="campaign-card" key={raw.id}>
          <div className="verification-head">
            <div>
              <div className="eyebrow">{mode==="editor"?(raw.business?.name||"Проверенная компания"):"ПРОЕКТ"}</div>
              <h3>{raw.title}</h3>
            </div>
            {mode==="editor"&&<span className="verification-badge ok">✓ Проверенная компания</span>}
          </div>
          <p>{raw.goal}</p>
          <div className="chip-row">{(raw.content_types||[]).map((x:string)=><span className="tag" key={x}>{x}</span>)}</div>
          <div className="campaign-meta"><span><b>Безопасная сделка:</b> {raw.budget_text}</span><span><b>Нужно монтажёров:</b> {raw.creator_slots}</span></div>
          {raw.requirements&&<div className="lesson-example"><b>Что важно</b><span>{raw.requirements}</span></div>}

          {mode==="editor"&&(raw.myStatus?<div className="auth-msg">Твой отклик: <b>{statusRu(raw.myStatus)}</b>{raw.myStatus==="accepted"&&<><br/><a className="btn btn-dark" href="#messages" onClick={()=>rememberChat("campaign",raw.id)}>Открыть закрытый чат</a></>}</div>:<div className="business-form campaign-apply">
            <input type="url" placeholder="Ссылка на свои работы" value={apply[raw.id]?.portfolioUrl||""} onChange={e=>setApply({...apply,[raw.id]:{...(apply[raw.id]||{portfolioUrl:"",note:""}),portfolioUrl:e.target.value}})}/>
            <textarea placeholder="Коротко: почему ты подходишь" value={apply[raw.id]?.note||""} onChange={e=>setApply({...apply,[raw.id]:{...(apply[raw.id]||{portfolioUrl:"",note:""}),note:e.target.value}})}/>
            <button className="btn btn-dark" disabled={busy} onClick={()=>applyTo(raw.id)}>Откликнуться</button>
          </div>)}

          {mode==="business"&&<div className="campaign-applications">
            <b>Отклики · {(raw.applications||[]).length}</b>
            {(raw.applications||[]).length===0?<p className="muted">Откликов пока нет.</p>:(raw.applications||[]).map((a:BusinessApplication)=><div className="talent-row" key={a.id}>
              <div>
                <b>@{a.editor?.username||"editor"}</b>
                <span>{a.note||"Без комментария"}</span>
                {a.portfolio_url&&<a href={a.portfolio_url} target="_blank" rel="noreferrer">Открыть работы ↗</a>}
              </div>
              <div className="chip-row">
                <button className="mini-btn" onClick={()=>setApplication(a.id,"shortlisted")}>В избранное</button>
                <button className="mini-btn" onClick={()=>setApplication(a.id,"accepted")}>Принять</button>
                <button className="mini-btn" onClick={()=>setApplication(a.id,"declined")}>Пропустить</button>
                {a.status==="accepted"&&<a className="mini-btn" href="#messages" onClick={()=>rememberChat("campaign",raw.id)}>Открыть чат</a>}
              </div>
            </div>)}
          </div>}
        </article>)}
      </div>
    </section>

    <section className="card">
      <div className="eyebrow">АКТИВНЫЕ КОМПАНИИ</div>
      <h3>Компании, которые работают с монтажёрами</h3>
      <p className="muted">Рейтинг показывает число открытых проектов и откликов. Качество работы позже оценят сами участники.</p>
      <div className="business-league-list">
        {league.length===0?<p className="muted">Лига заполнится после первых кампаний.</p>:league.map((b,i)=><div className="business-league-row" key={b.id}><b>#{i+1}</b><span>{b.name}</span><strong>{b.score}</strong></div>)}
      </div>
    </section>
  </div>
}

function statusRu(status?:string){
  if(status==="shortlisted")return "в избранном";
  if(status==="accepted")return "принят";
  if(status==="declined")return "отклонён";
  return "отправлен";
}

function rememberChat(kind:string,id:string){
  try{sessionStorage.setItem("kivronix_open_chat_source",kind+":"+id)}catch{}
}

"use client";

import {FormEvent,useEffect,useMemo,useState} from "react";
import {getSupabaseBrowserClient} from "@/lib/supabase-browser";
import {extractVideoFrames} from "@/lib/video-frames";

type Role="editor"|"business"|null;
type Challenge={
  id:string;
  business_id?:string|null;
  brand:string;
  title:string;
  brief:string;
  prize_cents:number;
  prize_points:number;
  custom_prize:string|null;
  ends_at:string|null;
  status:string;
  source_assets:string[];
  brand_verified?:boolean;
  verification_level?:string;
};
type Submission={
  id:string;
  challenge_id:string;
  editor_id:string;
  editor_name:string;
  storage_path:string;
  video_url:string;
  ai_score:number|null;
  status:string;
};

const demoChallenges:Challenge[]=[
  {id:"demo-coffee",brand:"ПРИМЕР · NORTH COFFEE",title:"Утренний ролик о кофе",brief:"Собери вертикальный ролик длиной 20–30 секунд. Покажи атмосферу утра, продукт крупно и закончи понятным предложением для зрителя. Голос и звуки должны быть громче музыки.",prize_cents:150000,prize_points:250,custom_prize:"Набор кофе и встреча с командой",ends_at:new Date(Date.now()+3*86400000).toISOString(),status:"open",source_assets:[]},
  {id:"demo-fitness",brand:"ПРИМЕР · VOLT FITNESS",title:"Реклама нового зала",brief:"Собери ролик длиной 30 секунд. Начни с яркого кадра, покажи три главных преимущества и добавь подходящие звуки. Используй переходы только там, где они помогают истории.",prize_cents:0,prize_points:400,custom_prize:null,ends_at:new Date(Date.now()+5*86400000).toISOString(),status:"open",source_assets:[]},
  {id:"demo-motion",brand:"ПРИМЕР · MOTION LAB",title:"Короткий ролик с экспертом",brief:"Сделай вертикальный ролик длиной до 35 секунд: чистая речь, крупные субтитры и дополнительные кадры по смыслу.",prize_cents:0,prize_points:0,custom_prize:"Годовая лицензия на набор шаблонов",ends_at:new Date(Date.now()+2*86400000).toISOString(),status:"open",source_assets:[]},
];

export default function ChallengeCenter({role,viewerName,ageGroup,guardianVerified,editorEligible=true,mode}:{role:Role;viewerName:string;ageGroup?:string;guardianVerified?:boolean;editorEligible?:boolean;mode:"arena"|"business"}){
  const [challenges,setChallenges]=useState<Challenge[]>(demoChallenges);
  const [selectedId,setSelectedId]=useState(demoChallenges[0].id);
  const [submissions,setSubmissions]=useState<Submission[]>([]);
  const [file,setFile]=useState<File|null>(null);
  const [message,setMessage]=useState("");
  const [loading,setLoading]=useState(false);
  const [loadingBrief,setLoadingBrief]=useState(false);
  const [brandContext,setBrandContext]=useState<Record<string,string>>({});
  const [businessId,setBusinessId]=useState<string|null>(null);
  const [businessVerified,setBusinessVerified]=useState(false);
  const [form,setForm]=useState({brand:"",title:"",brief:"",sourceUrl:"",prize:"",prizePoints:"",customPrize:"",deadline:""});

  const selected=useMemo(()=>challenges.find(c=>c.id===selectedId)||challenges[0],[challenges,selectedId]);

  useEffect(()=>{void load()},[role]);

  async function load(){
    const supabase=getSupabaseBrowserClient();
    if(!supabase)return;
    const {data:{user}}=await supabase.auth.getUser();
    if(!user)return;

    let ownedBusinessId:string|null=null;
    if(role==="business"){
      const {data:business}=await supabase.from("businesses").select("id,name,brand_context,verified,verification_level").eq("owner_id",user.id).maybeSingle();
      if(business){
        ownedBusinessId=business.id;
        setBrandContext((business.brand_context||{}) as Record<string,string>);
        setBusinessVerified(Boolean(business.verified));
      }else{
        const {data:created}=await supabase.from("businesses")
          .upsert({owner_id:user.id,name:viewerName+" Studio"},{onConflict:"owner_id"})
          .select("id,brand_context,verified,verification_level")
          .single();
        ownedBusinessId=created?.id||null;
        if(created?.brand_context)setBrandContext((created.brand_context||{}) as Record<string,string>);
        setBusinessVerified(Boolean(created?.verified));
      }
      setBusinessId(ownedBusinessId);
    }

    const {data,error}=await supabase.from("challenges")
      .select("id,business_id,title,brief,prize_cents,prize_points,custom_prize,ends_at,status,source_assets")
      .eq("status","open").order("created_at",{ascending:false});

    if(!error&&data?.length){
      const businessIds=[...new Set(data.map((row:any)=>row.business_id).filter(Boolean))];
      const {data:publicBusinesses}=businessIds.length
        ? await supabase.from("public_businesses").select("id,name,verified,verification_level").in("id",businessIds)
        : {data:[] as any[]};
      const businessMap=Object.fromEntries((publicBusinesses||[]).map((b:any)=>[b.id,b]));
      const mapped:Challenge[]=data.map((row:any)=>({
        id:row.id,
        business_id:row.business_id,
        brand:businessMap[row.business_id]?.name||"KIVRONIX BUSINESS",
        brand_verified:Boolean(businessMap[row.business_id]?.verified),
        verification_level:businessMap[row.business_id]?.verification_level||"basic",
        title:row.title,
        brief:row.brief,
        prize_cents:Number(row.prize_cents||0),
        prize_points:Number(row.prize_points||0),
        custom_prize:row.custom_prize||null,
        ends_at:row.ends_at,
        status:row.status,
        source_assets:Array.isArray(row.source_assets)?row.source_assets.filter((v:any)=>typeof v==="string"):[],
      }));
      setChallenges(mapped);
      setSelectedId(mapped[0].id);
    } else if(!error) {
      setChallenges([]);
      setSelectedId("");
    }

    if(mode==="business"&&ownedBusinessId)await loadBusinessSubmissions(ownedBusinessId);
  }

  async function loadBusinessSubmissions(ownedBusinessId:string){
    const supabase=getSupabaseBrowserClient();
    if(!supabase)return;
    const {data:owned}=await supabase.from("challenges").select("id").eq("business_id",ownedBusinessId);
    const ids=(owned||[]).map((c:any)=>c.id);
    if(!ids.length){setSubmissions([]);return;}

    const {data}=await supabase.from("challenge_submissions")
      .select("id,challenge_id,video_url,ai_score,status,editor_id")
      .in("challenge_id",ids).order("created_at",{ascending:false});
    const rows=data||[];
    const editorIds=[...new Set(rows.map((r:any)=>r.editor_id))];
    let names:Record<string,string>={};

    if(editorIds.length){
      const {data:profiles}=await supabase.from("public_profiles").select("id,display_name").in("id",editorIds);
      names=Object.fromEntries((profiles||[]).map((p:any)=>[p.id,p.display_name||"Editor"]));
    }

    const mapped=await Promise.all(rows.map(async(r:any)=>{
      const {data:signed}=await supabase.storage.from("challenge-submissions").createSignedUrl(r.video_url,60*60);
      return {
        id:r.id,
        challenge_id:r.challenge_id,
        editor_id:r.editor_id,
        storage_path:r.video_url,
        video_url:signed?.signedUrl||"",
        ai_score:r.ai_score,
        status:r.status,
        editor_name:names[r.editor_id]||"Editor"
      } as Submission;
    }));
    setSubmissions(mapped);
  }

  async function submitWork(e:FormEvent){
    e.preventDefault();
    if(!selected||!file){setMessage("Сначала выбери видеофайл.");return;}
    if(role==="editor"&&!editorEligible){setMessage("Конкурсы откроются на уровне 2 после 300 XP. Сначала заверши первые уроки.");return;}
    if(role==="editor"&&ageGroup&&ageGroup!=="18+"&&!guardianVerified){
      setMessage("Для отправки коммерческой работы пользователю младше 18 лет нужно подтверждение взрослого. Обучение, практика и помощник уже доступны.");
      return;
    }

    setLoading(true);
    setMessage("Готовлю работу к отправке…");
    const currentFile=file;
    const supabase=getSupabaseBrowserClient();

    if(!supabase){
      try{
        setMessage("Видео принято в примере. Помощник смотрит главные кадры…");
        const review=await runAutoReview(currentFile,selected.brief,selected.id);
        setMessage("Готово. Оценка ролика: "+review.overall_score+" из 100.");
      }catch{
        setMessage("Работа принята. Разбор остановился раньше результата.");
      }finally{
        setFile(null);setLoading(false);
      }
      return;
    }

    const {data:{user}}=await supabase.auth.getUser();
    if(!user){setMessage("Войди в аккаунт монтажёра, чтобы отправить работу.");setLoading(false);return;}

    const safe=currentFile.name.replace(/[^a-zA-Z0-9._-]/g,"_");
    const path=user.id+"/"+selected.id+"/"+Date.now()+"-"+safe;

    setMessage("Загружаю видео в защищённое хранилище…");
    const upload=await supabase.storage.from("challenge-submissions")
      .upload(path,currentFile,{upsert:false,contentType:currentFile.type||"video/mp4"});
    if(upload.error){setMessage("Ошибка загрузки видео: "+upload.error.message);setLoading(false);return;}

    const {data:submission,error:insertError}=await supabase.from("challenge_submissions")
      .upsert({challenge_id:selected.id,editor_id:user.id,video_url:path,status:"submitted"},{onConflict:"challenge_id,editor_id"})
      .select("id").single();

    if(insertError||!submission){
      setMessage("Видео загружено. Запись об отправке содержит ошибку: "+(insertError?.message||"причина пока отсутствует"));
      setLoading(false);return;
    }

    try{
      setMessage("Работа отправлена. Помощник KIVRONIX делает первый разбор…");
      const review=await runAutoReview(currentFile,selected.brief,selected.id);
      const {error:reviewError}=await supabase.from("challenge_submissions")
        .update({ai_score:review.overall_score,ai_feedback:review}).eq("id",submission.id);
      setMessage(reviewError
        ?"Работа отправлена. Оценка "+review.overall_score+" из 100. Сохранение совета завершилось с ошибкой: "+reviewError.message
        :"Готово. Работа отправлена, оценка: "+review.overall_score+" из 100. Компания уже увидит результат.");
    }catch{
      setMessage("Работа отправлена и сохранена. Автоматический разбор остановился раньше результата.");
    }

    setFile(null);setLoading(false);
  }

  async function runAutoReview(videoFile:File,brief:string,challengeId:string){
    const extracted=await extractVideoFrames(videoFile,6);
    const supabase=getSupabaseBrowserClient();
    const {data:{session}}=await supabase.auth.getSession();
    const token=session?.access_token;
    if(!token)throw new Error("Нужна авторизация.");
    const response=await fetch("/api/ai/video-review",{method:"POST",headers:{"Content-Type":"application/json",Authorization:"Bearer "+token},body:JSON.stringify({frames:extracted.frames,duration:extracted.duration,width:extracted.width,height:extracted.height,brief,filename:videoFile.name,purpose:"arena",challengeId})});
    const data=await response.json();
    if(!response.ok||!data.review)throw new Error(data?.error||"Разбор ролика задерживается.");
    return data.review;
  }

  async function improveBrief(){
    if(!form.brief.trim()){setMessage("Сначала напишите несколько строк о задании.");return;}
    setLoadingBrief(true);setMessage("");
    try{
      const supabase=getSupabaseBrowserClient();
      const {data:{session}}=await supabase.auth.getSession();
      const headers:Record<string,string>={"Content-Type":"application/json"};
      if(session?.access_token)headers.Authorization="Bearer "+session.access_token;
      const r=await fetch("/api/ai/brief",{method:"POST",headers,body:JSON.stringify({brief:form.brief,brandContext})});
      const data=await r.json();
      if(!r.ok||!data.result)throw new Error(data?.error||"Разбор задания задерживается.");
      const b=data.result;
      const formatted=[
        "Цель: "+b.goal,
        "Длительность: "+b.duration,
        "Формат: "+b.format,
        "",
        "Обязательно:",
        ...b.must_haves.map((v:string)=>"• "+v),
        "",
        "Избегать:",
        ...b.avoid.map((v:string)=>"• "+v),
        "",
        "Критерии приёмки:",
        ...b.checklist.map((v:string)=>"• "+v)
      ].join("\n");
      setForm(current=>({...current,title:current.title||b.title,brief:formatted}));
      setMessage("Помощник превратил черновик в понятное задание. Проверьте детали перед публикацией.");
    }catch(e){
      setMessage(e instanceof Error?e.message:"Ошибка улучшения задания.");
    }finally{setLoadingBrief(false)}
  }

  async function createChallenge(e:FormEvent){
    e.preventDefault();
    if(!businessVerified){
      setMessage("Сначала пройдите проверку компании выше. Публикация откроется после подтверждения.");
      return;
    }
    const cashRub=Math.max(0,Math.floor(Number(form.prize||0)));
    const points=Math.max(0,Math.floor(Number(form.prizePoints||0)));
    const customPrize=form.customPrize.trim();
    if(!cashRub&&!points&&!customPrize){
      setMessage("Добавьте хотя бы одну награду: деньги, KIVRONIX Points или свой приз.");
      return;
    }
    setLoading(true);setMessage("");
    const sourceAssets=form.sourceUrl.trim()?[form.sourceUrl.trim()]:[];
    const supabase=getSupabaseBrowserClient();

    if(!supabase||!businessId){
      const demo:Challenge={id:"local-"+Date.now(),business_id:"demo",brand:form.brand||viewerName,title:form.title,brief:form.brief,prize_cents:cashRub*100,prize_points:points,custom_prize:customPrize||null,ends_at:form.deadline?new Date(form.deadline).toISOString():null,status:"open",source_assets:sourceAssets};
      setChallenges(c=>[demo,...c]);setSelectedId(demo.id);setMessage("Пример задания создан только в браузере.");
      setLoading(false);return;
    }

    if(form.brand)await supabase.from("businesses").update({name:form.brand}).eq("id",businessId);

    const {data,error}=await supabase.from("challenges").insert({
      business_id:businessId,title:form.title,brief:form.brief,status:"open",
      prize_cents:cashRub*100,
      prize_points:points,
      custom_prize:customPrize||null,
      ends_at:form.deadline?new Date(form.deadline).toISOString():null,
      source_assets:sourceAssets
    }).select("id,business_id,title,brief,prize_cents,prize_points,custom_prize,ends_at,status,source_assets").single();

    if(error){setMessage(error.message);setLoading(false);return;}
    const item:Challenge={...(data as any),brand:form.brand||viewerName,source_assets:(data as any).source_assets||[]};
    setChallenges(c=>[item,...c]);setSelectedId(item.id);setMessage("Конкурс опубликован.");
    setForm({brand:form.brand,title:"",brief:"",sourceUrl:"",prize:"",prizePoints:"",customPrize:"",deadline:""});setLoading(false);
  }

  async function setSubmissionStatus(id:string,status:"shortlisted"|"winner"){
    const supabase=getSupabaseBrowserClient();
    if(supabase){
      const {error}=await supabase.from("challenge_submissions").update({status}).eq("id",id);
      if(error){setMessage(error.message);return;}

      if(status==="winner"){
        const submission=submissions.find(s=>s.id===id);
        const challenge=challenges.find(ch=>ch.id===submission?.challenge_id);
        if(submission&&challenge){
          const {error:portfolioError}=await supabase.from("portfolio_items").insert({
            editor_id:submission.editor_id,
            title:challenge.brand+" — "+challenge.title,
            video_url:submission.storage_path,
            tags:["challenge-winner","commercial"],
            ai_score:submission.ai_score
          });
          if(portfolioError&&!portfolioError.message.includes("duplicate"))setMessage(portfolioError.message);
          const {data:{session}}=await supabase.auth.getSession();
          const response=await fetch("/api/private-chats",{
            method:"POST",
            headers:{"Content-Type":"application/json",Authorization:"Bearer "+(session?.access_token||"")},
            body:JSON.stringify({action:"open_challenge_winner",submissionId:id})
          });
          const chatResult=await response.json().catch(()=>({}));
          if(response.ok&&chatResult?.conversationId)try{sessionStorage.setItem("kivronix_open_conversation",chatResult.conversationId)}catch{}
          setMessage(response.ok
            ?"Победитель выбран. Работа добавлена в его профиль, закрытый чат открыт."
            :"Победитель выбран. Ошибка открытия чата: "+(chatResult?.error||"попробуйте ещё раз"));
        }
      }
    }
    setSubmissions(s=>s.map(x=>x.id===id?{...x,status}:x));
  }

  if(mode==="business"){
    return <div className="challenge-layout">
      <section className="card">
        <div className="eyebrow">НОВОЕ ЗАДАНИЕ</div>
        <h3>Создать настоящее задание</h3>
        {!businessVerified&&<div className="auth-msg">Публикация закрыта до проверки компании. Заполни блок «Проверка бизнеса» выше.</div>}
        <form className="business-form" onSubmit={createChallenge}>
          <input required placeholder="Название компании" value={form.brand} onChange={e=>setForm({...form,brand:e.target.value})}/>
          <input required placeholder="Название конкурса" value={form.title} onChange={e=>setForm({...form,title:e.target.value})}/>
          <textarea required placeholder="Опишите длительность, формат, обязательные детали и ограничения" value={form.brief} onChange={e=>setForm({...form,brief:e.target.value})}/><button type="button" className="btn btn-ghost" onClick={improveBrief} disabled={loadingBrief}>{loadingBrief?"Помощник улучшает…":"✨ Сделать задание понятнее"}</button>
          <input type="url" placeholder="Ссылка на исходные файлы и примеры" value={form.sourceUrl} onChange={e=>setForm({...form,sourceUrl:e.target.value})}/>
          <div className="challenge-reward-builder">
            <b>Награда победителю</b>
            <p className="muted">Можно выбрать один вариант или совместить несколько.</p>
            <div className="split-fields"><input min="0" max="100000000" type="number" placeholder="Денежный приз, ₽" value={form.prize} onChange={e=>setForm({...form,prize:e.target.value})}/><input min="0" max="5000" type="number" placeholder="KIVRONIX Points · до 5 000" value={form.prizePoints} onChange={e=>setForm({...form,prizePoints:e.target.value})}/></div>
            <input maxLength={500} placeholder="Свой приз: техника, лицензия, встреча…" value={form.customPrize} onChange={e=>setForm({...form,customPrize:e.target.value})}/>
          </div>
          <label className="field-label">Срок приёма работ<input type="datetime-local" value={form.deadline} onChange={e=>setForm({...form,deadline:e.target.value})}/></label>
          <p className="field-hint">Денежный и собственный приз предоставляет компания. KIVRONIX Points начисляются победителю автоматически. Условия должны быть конкретными и выполнимыми.</p>
          <button className="btn btn-lime" disabled={loading||!businessVerified}>{loading?"Публикуем...":businessVerified?"Опубликовать конкурс":"Сначала пройти проверку"}</button>
        </form>
        {message&&<div className="auth-msg">{message}</div>}
      </section>

      <section className="card">
        <div className="eyebrow">РАБОТЫ УЧАСТНИКОВ</div>
        <h3>Работы участников</h3>
        {submissions.length===0?<p className="muted">Когда монтажёры отправят работы, они появятся здесь.</p>:<div className="submission-list">
          {submissions.map(s=><article className="submission submission-video" key={s.id}>
            <div className="submission-preview">{s.video_url?<video controls preload="metadata" src={s.video_url}/>:<div className="work-preview">VIDEO</div>}</div>
            <div className="submission-info"><b>{s.editor_name}</b><div><span className="tag">{s.status}</span>{s.ai_score!=null&&<span className="tag">Оценка {s.ai_score}</span>}</div></div>
            <div className="submission-actions"><button className="btn" onClick={()=>setSubmissionStatus(s.id,"shortlisted")}>В избранное</button><button className="btn btn-dark" onClick={()=>setSubmissionStatus(s.id,"winner")}>Выбрать победителем</button>{s.status==="winner"&&<a className="btn btn-ghost" href="#messages" onClick={()=>rememberChat("challenge",s.challenge_id)}>Открыть чат</a>}</div>
          </article>)}
        </div>}
      </section>
    </div>
  }

  if(role&&challenges.length===0){
    return <div className="card"><div className="eyebrow">КОНКУРСЫ КОМПАНИЙ</div><h3>Открытые задания появятся здесь</h3><p className="muted">Компания публикует конкурс, а система сразу добавляет его в этот раздел. Примеры со знаком «ПРИМЕР» видят только гости.</p></div>
  }

  return <div className="challenge-layout">
    <section className="challenge-list">
      {challenges.map(c=><button key={c.id} className={"challenge-row "+(selected?.id===c.id?"active":"")} onClick={()=>{setSelectedId(c.id);setMessage("")}}>
        <div><span className="eyebrow">{c.brand}</span>{c.brand_verified&&<span className="tag verification-mini">{badgeName(c.verification_level)}</span>}<h3>{c.title}</h3></div>
        <div><b>{rewardSummary(c)}</b><span className="muted">{deadline(c.ends_at)}</span></div>
      </button>)}
    </section>

    {selected&&<section className="card challenge-detail">
      <div className="eyebrow">ЗАДАНИЕ ОТ КОМПАНИИ</div>
      <h2>{selected.title}</h2>
      <div className="challenge-meta"><span>{selected.brand}</span>{selected.brand_verified&&<span className="tag verification-mini">{badgeName(selected.verification_level)}</span>}<b>{rewardSummary(selected)}</b><span>{deadline(selected.ends_at)}</span></div>
      <div className="challenge-rewards">
        {selected.prize_cents>0?<span><b>{money(selected.prize_cents)}</b> денежный приз</span>:null}
        {selected.prize_points>0?<span><b>{selected.prize_points.toLocaleString("ru-RU")}</b> KIVRONIX Points</span>:null}
        {selected.custom_prize?<span><b>Приз компании</b> {selected.custom_prize}</span>:null}
      </div>
      <p>{selected.brief}</p>
      {selected.source_assets.length>0&&<div className="source-assets"><b>Исходники:</b>{selected.source_assets.map((url,i)=><a key={i} href={url} target="_blank" rel="noreferrer">Открыть материалы ↗</a>)}</div>}
      {role==="editor"&&ageGroup&&ageGroup!=="18+"&&!guardianVerified&&<div className="minor-safety-note"><b>Безопасный режим</b><span>Подтверждение взрослого откроет отправку коммерческой работы.</span></div>}<div className="brief-checklist"><b>Перед отправкой проверь:</b><span>✓ формат 9:16</span><span>✓ понятное начало</span><span>✓ голос слышно поверх музыки</span><span>✓ работа соответствует заданию</span></div>
      <form className="upload-box" onSubmit={submitWork}>
        <label><b>Загрузить готовую работу</b><span>MP4, MOV или WebM. Файл хранится закрыто, компания получает временную защищённую ссылку.</span><input type="file" accept="video/*" onChange={e=>setFile(e.target.files?.[0]||null)}/></label>
        <button className="btn btn-dark" disabled={loading}>{loading?"Отправляем...":"Отправить на конкурс"}</button>
      </form>
      {message&&<div className="auth-msg">{message}</div>}
    </section>}
  </div>
}

function money(cents:number){return new Intl.NumberFormat("ru-RU").format(Math.round(cents/100))+" ₽"}
function rewardSummary(challenge:Challenge){
  const rewards=[];
  if(challenge.prize_cents>0)rewards.push(money(challenge.prize_cents));
  if(challenge.prize_points>0)rewards.push(challenge.prize_points.toLocaleString("ru-RU")+" KP");
  if(challenge.custom_prize)rewards.push("приз компании");
  return rewards.join(" + ")||"Награда";
}
function deadline(value:string|null){if(!value)return"Срок открыт";const ms=new Date(value).getTime()-Date.now();const days=Math.max(0,Math.ceil(ms/86400000));return days===0?"Сегодня":days+" дн."}

function rememberChat(kind:string,id:string){
  try{sessionStorage.setItem("kivronix_open_chat_source",kind+":"+id)}catch{}
}


function badgeName(level?:string){
  if(level==="popular_brand")return "★ Известный бренд";
  if(level==="partner")return "★ Партнёр KIVRONIX";
  return "✓ Проверенная компания";
}

"use client";

import {FormEvent,useEffect,useRef,useState} from "react";
import {getSupabaseBrowserClient} from "@/lib/supabase-browser";

type Msg={from:"client"|"user";text:string};
type Scenario={
  id:string;
  client_name:string;
  client_role:string;
  personality:string;
  project:string;
  budget:string;
  deadline:string;
  hidden_concern:string;
  difficulty:"Базовая"|"Средняя"|"Сложная";
  opening_message:string;
};
type Result={
  client_reply:string;
  score:number;
  feedback:string;
  coach_hint:string;
  deal_status:"ongoing"|"won"|"lost";
  deal_reason:string;
  scenario_meta?:Scenario;
};

const initialScenario:Scenario={
  id:"starter-budget",
  client_name:"Анна",
  client_role:"владелица небольшого магазина",
  personality:"дружелюбная, но внимательно относится к бюджету",
  project:"вертикальный ролик о новом товаре",
  budget:"3 000 ₽",
  deadline:"через три дня",
  hidden_concern:"Хочет понять, за что платит и сколько правок входит.",
  difficulty:"Базовая",
  opening_message:"Привет! Нужен короткий ролик о новом товаре. Бюджет 3 000 ₽ — можешь объяснить, что войдёт в эту сумму?"
};

export default function ClientSimulator(){
  const [scenario,setScenario]=useState<Scenario>(initialScenario);
  const [messages,setMessages]=useState<Msg[]>([{from:"client",text:initialScenario.opening_message}]);
  const [input,setInput]=useState("");
  const [result,setResult]=useState<Result|null>(null);
  const [loading,setLoading]=useState(false);
  const [loadingScenario,setLoadingScenario]=useState(false);
  const [ready,setReady]=useState(false);
  const [storageMode,setStorageMode]=useState<"account"|"browser">("browser");
  const [round,setRound]=useState(1);
  const [recentScenarios,setRecentScenarios]=useState<string[]>([]);
  const [lastSuccess,setLastSuccess]=useState<{name:string;score:number}|null>(null);
  const [scenarioError,setScenarioError]=useState("");
  const chatRef=useRef<HTMLDivElement>(null);
  const inputRef=useRef<HTMLTextAreaElement>(null);
  const resetTimerRef=useRef<number|null>(null);

  useEffect(()=>{
    let active=true;
    async function load(){
      try{
        const supabase=getSupabaseBrowserClient();
        const {data:{session}}=await supabase.auth.getSession();
        if(session?.access_token){
          const response=await fetch("/api/practice/session",{headers:{Authorization:"Bearer "+session.access_token},cache:"no-store"});
          const data=await response.json();
          if(response.ok&&active){
            setStorageMode("account");
            if(data.session){
              const restored=parseScenario(data.session.scenario,data.session.result?.scenario_meta);
              if(restored)setScenario(restored);
              if(Array.isArray(data.session.messages)&&data.session.messages.length)setMessages(data.session.messages);
              if(data.session.result)setResult(normalizeResult(data.session.result));
            }
            setReady(true);
            return;
          }
        }
        const saved=JSON.parse(localStorage.getItem("kivronix_practice_simulator_v2")||"null");
        if(active&&saved){
          const restored=parseScenario(saved.scenario,saved.result?.scenario_meta);
          if(restored)setScenario(restored);
          if(Array.isArray(saved.messages)&&saved.messages.length)setMessages(saved.messages);
          if(saved.result&&typeof saved.result==="object")setResult(normalizeResult(saved.result));
          if(Number.isInteger(saved.round))setRound(saved.round);
          if(Array.isArray(saved.recentScenarios))setRecentScenarios(saved.recentScenarios.slice(-8));
        }
      }catch{}finally{if(active)setReady(true)}
    }
    void load();
    return()=>{active=false;if(resetTimerRef.current)window.clearTimeout(resetTimerRef.current)};
  },[]);

  useEffect(()=>{
    if(!ready)return;
    const persistedResult=result?{...result,scenario_meta:scenario}:null;
    const snapshot={scenario:JSON.stringify(scenario),messages:messages.slice(-50),result:persistedResult,round,recentScenarios:recentScenarios.slice(-8)};
    try{localStorage.setItem("kivronix_practice_simulator_v2",JSON.stringify(snapshot))}catch{}
    if(storageMode!=="account")return;
    const timer=window.setTimeout(async()=>{
      try{
        const supabase=getSupabaseBrowserClient();
        const {data:{session}}=await supabase.auth.getSession();
        if(session?.access_token)await fetch("/api/practice/session",{method:"POST",headers:{Authorization:"Bearer "+session.access_token,"Content-Type":"application/json"},body:JSON.stringify(snapshot)});
      }catch{}
    },650);
    return()=>window.clearTimeout(timer);
  },[messages,ready,recentScenarios,result,round,scenario,storageMode]);

  useEffect(()=>{
    const chat=chatRef.current;
    if(chat)chat.scrollTo({top:chat.scrollHeight,behavior:"smooth"});
  },[messages,loading]);

  async function createScenario(successScore?:number){
    if(loadingScenario)return;
    if(resetTimerRef.current){window.clearTimeout(resetTimerRef.current);resetTimerRef.current=null}
    setLoadingScenario(true);
    setScenarioError("");
    try{
      const supabase=getSupabaseBrowserClient();
      const {data:{session}}=await supabase.auth.getSession();
      const headers:Record<string,string>={"Content-Type":"application/json"};
      if(session?.access_token)headers.Authorization="Bearer "+session.access_token;
      const nextRecent=[...recentScenarios,`${scenario.client_role}: ${scenario.project}, ${scenario.budget}`].slice(-8);
      const response=await fetch("/api/ai/simulator",{method:"POST",headers,body:JSON.stringify({mode:"new_scenario",round:round+1,recentScenarios:nextRecent})});
      const data=await response.json();
      if(!response.ok||!data.scenario)throw new Error("Новый клиент пока не появился.");
      if(successScore!=null)setLastSuccess({name:scenario.client_name,score:successScore});
      setRecentScenarios(nextRecent);
      setRound(value=>value+1);
      setScenario(data.scenario);
      setMessages([{from:"client",text:data.scenario.opening_message}]);
      setResult(null);
      setInput("");
      inputRef.current?.focus();
    }catch(error){
      setScenarioError(error instanceof Error?error.message:"Нового клиента пока не удалось создать. Попробуй ещё раз.");
    }finally{setLoadingScenario(false)}
  }

  async function send(event:FormEvent){
    event.preventDefault();
    if(!input.trim()||loading||loadingScenario)return;
    const text=input.trim();
    const history=[...messages,{from:"user" as const,text}];
    setMessages(history);
    setInput("");setLoading(true);
    if(inputRef.current)inputRef.current.style.height="auto";
    try{
      const supabase=getSupabaseBrowserClient();
      const {data:{session}}=await supabase.auth.getSession();
      const headers:Record<string,string>={"Content-Type":"application/json"};
      if(session?.access_token)headers.Authorization="Bearer "+session.access_token;
      const response=await fetch("/api/ai/simulator",{method:"POST",headers,body:JSON.stringify({message:text,history:messages,scenario})});
      const data=await response.json();
      if(!response.ok||!data.result)throw new Error(data?.error||"Тренировка временно остановилась.");
      const nextResult=normalizeResult(data.result);
      setResult(nextResult);
      setMessages(current=>[...current,{from:"client",text:nextResult.client_reply}]);
      if(nextResult.deal_status==="won"&&nextResult.score>=65){
        resetTimerRef.current=window.setTimeout(()=>void createScenario(nextResult.score),2200);
      }
    }catch{
      setResult({client_reply:"",score:0,feedback:"Ответ клиента задерживается. Попробуй отправить сообщение ещё раз.",coach_hint:"Какая одна деталь поможет клиенту лучше понять условия?",deal_status:"ongoing",deal_reason:"Связь с помощником временно прервалась."});
    }finally{setLoading(false)}
  }

  return <div className="practice-simulator">
    {lastSuccess?<div className="practice-success-banner"><span>✓</span><div><b>Сделка с {lastSuccess.name} завершена · {lastSuccess.score}/100</b><small>ИИ уже создал нового персонажа с другой задачей.</small></div><button type="button" aria-label="Закрыть сообщение" onClick={()=>setLastSuccess(null)}>×</button></div>:null}
    {scenarioError?<div className="practice-error-banner" role="alert"><span>!</span><p>{scenarioError}</p><button type="button" onClick={()=>void createScenario()}>Повторить</button></div>:null}
    <div className="practice-round-head"><div><div className="eyebrow">ПРАКТИКА #{round}</div><h2>Реальный разговор с новым заказчиком</h2><p>Договорись о результате своими словами. ИИ играет клиента и подсказывает направление, но не пишет ответ за тебя.</p></div><button className="btn btn-ghost" type="button" disabled={loadingScenario||loading} onClick={()=>void createScenario()}>{loadingScenario?"Создаём клиента…":"Другой заказчик ↻"}</button></div>

    <div className="simulator-layout humanized">
      <section className="card simulator-conversation">
        <header className="practice-client-card"><span className="practice-avatar">{scenario.client_name.slice(0,1)}</span><div><b>{scenario.client_name}</b><small>{scenario.client_role}</small></div><em>{scenario.difficulty}</em></header>
        <div className="practice-brief-grid"><span><small>Задача</small><b>{scenario.project}</b></span><span><small>Бюджет</small><b>{scenario.budget}</b></span><span><small>Срок</small><b>{scenario.deadline}</b></span><span><small>Характер</small><b>{scenario.personality}</b></span></div>
        <small className="practice-storage">{storageMode==="account"?"Диалог сохраняется в аккаунте":"Диалог сохраняется в этом браузере"}</small>
        <div className="simulator-chat" ref={chatRef}>{messages.map((message,index)=><div key={`${index}-${message.text.slice(0,16)}`} className={message.from==="user"?"practice-message user":"practice-message client"}>{message.from==="client"?<span>{scenario.client_name.slice(0,1)}</span>:null}<div><small>{message.from==="client"?scenario.client_name:"Ты"}</small><p>{message.text}</p></div></div>)}{loading?<div className="practice-typing"><i/><i/><i/><span>{scenario.client_name} печатает</span></div>:null}</div>
        <form className="simulator-form platform-composer" onSubmit={send}>
          <span className="composer-icon" aria-hidden="true">✎</span>
          <textarea ref={inputRef} rows={2} maxLength={2000} value={input} onChange={event=>{setInput(event.target.value);const area=inputRef.current;if(area){area.style.height="auto";area.style.height=Math.min(160,area.scrollHeight)+"px"}}} placeholder="Напиши свой ответ заказчику…" aria-label="Ответ заказчику"/>
          <button className="composer-send" aria-label="Отправить ответ" title="Отправить" disabled={loading||loadingScenario||!input.trim()}>↑</button>
        </form>
      </section>

      <aside className="card simulator-score human-coach">
        <div className="eyebrow">ТРЕНЕР ПЕРЕГОВОРОВ</div>
        {!result?<><span className="coach-orb">✦</span><h3>Сначала пойми клиента</h3><p className="muted">Уточни результат, объясни состав цены и постепенно зафиксируй срок и правки. Формулировку выбираешь ты.</p><div className="coach-start-list"><span>1. Что клиент хочет получить?</span><span>2. За что он платит?</span><span>3. Что нужно согласовать дальше?</span></div></>:<>
          <div className={`deal-state ${result.deal_status}`}><span>{result.deal_status==="won"?"✓":result.deal_status==="lost"?"×":"↗"}</span><div><b>{result.deal_status==="won"?"Сделка заключена":result.deal_status==="lost"?"Клиент отказался":"Переговоры продолжаются"}</b><small>{result.deal_reason}</small></div></div>
          <div className="big-score">{result.score}<span>/100</span></div><h3>{result.score>=80?"Сильный ход":result.score>=65?"Хороший рабочий ответ":result.score>=45?"Есть основа":"Нужно точнее понять задачу"}</h3>
          <p>{result.feedback}</p>
          <div className="coach-hint"><span>?</span><div><b>Подсказка без готового ответа</b><p>{result.coach_hint}</p></div></div>
          {result.deal_status==="won"&&result.score>=65?<div className="new-client-loading"><i/>Создаём нового клиента и новую ситуацию…</div>:null}
          {result.deal_status==="lost"?<button className="btn btn-dark" type="button" onClick={()=>void createScenario()}>Разобрать новую ситуацию</button>:null}
        </>}
      </aside>
    </div>
  </div>;
}

function parseScenario(value:unknown,fallback:unknown):Scenario|null{
  if(fallback&&typeof fallback==="object"&&"opening_message" in fallback)return fallback as Scenario;
  if(typeof value!=="string"||!value.trim())return null;
  try{const parsed=JSON.parse(value);return parsed&&typeof parsed==="object"&&typeof parsed.opening_message==="string"?parsed as Scenario:null}catch{return null}
}

function normalizeResult(value:any):Result{
  return {
    client_reply:String(value?.client_reply||""),
    score:Math.max(0,Math.min(100,Number(value?.score)||0)),
    feedback:String(value?.feedback||"Продолжай уточнять условия."),
    coach_hint:String(value?.coach_hint||"Какую одну важную деталь стоит уточнить следующим сообщением?"),
    deal_status:value?.deal_status==="won"||value?.deal_status==="lost"?value.deal_status:"ongoing",
    deal_reason:String(value?.deal_reason||"Переговоры продолжаются."),
    scenario_meta:value?.scenario_meta,
  };
}

