"use client";

import {FormEvent,useEffect,useState} from "react";
import {getSupabaseBrowserClient} from "@/lib/supabase-browser";

type State={
  emailVerified:boolean;
  ageGroup:string;
  guardianVerified:boolean;
  level:string;
  request?:{status:string;review_note?:string|null}|null;
};

export default function EditorVerification(){
  const [state,setState]=useState<State|null>(null);
  const [form,setForm]=useState({portfolioUrl:"",sampleUrl:"",note:""});
  const [message,setMessage]=useState("");
  const [loading,setLoading]=useState(false);

  async function headers():Promise<Record<string,string>>{
    const supabase=getSupabaseBrowserClient();
    const {data:{session}}=await supabase.auth.getSession();
    return session?.access_token?{Authorization:"Bearer "+session.access_token}:{};
  }

  async function load(){
    const h=await headers();
    const r=await fetch("/api/editor/verification",{headers:h,cache:"no-store"});
    const data=await r.json();
    if(r.ok)setState(data);
  }

  useEffect(()=>{void load()},[]);

  async function submit(e:FormEvent){
    e.preventDefault();setLoading(true);setMessage("");
    const h=await headers();
    const r=await fetch("/api/editor/verification",{
      method:"POST",
      headers:{...h,"Content-Type":"application/json"},
      body:JSON.stringify(form)
    });
    const data=await r.json();
    setLoading(false);
    if(!r.ok){setMessage(data?.error||"Ошибка отправки работы.");return;}
    setMessage("Работа отправлена на проверку. Здесь оценивается только навык монтажа, поэтому паспорт остаётся за пределами этой формы.");
    await load();
  }

  if(!state)return null;
  const minor=state.ageGroup!=="18+";

  return <section className="card">
    <div className="eyebrow">ПРОВЕРКА МОНТАЖЁРА</div>
    <h3>Проверка по твоей работе</h3>
    <p className="muted">Компания подтверждает документы. Монтажёр подтверждает электронную почту, возрастной доступ и свой навык готовой работой.</p>

    <div className="verification-checks">
      <div className={state.emailVerified?"check-ok":"check-wait"}><b>{state.emailVerified?"✓":"○"} Электронная почта</b><span>{state.emailVerified?"Подтверждена":"Нужно подтвердить письмо"}</span></div>
      <div className={!minor||state.guardianVerified?"check-ok":"check-wait"}><b>{!minor||state.guardianVerified?"✓":"○"} Возрастной доступ</b><span>{!minor?"18+ указано при регистрации":state.guardianVerified?"Родитель подтверждён":"Ждём подтверждение родителя"}</span></div>
      <div className={state.level==="skills_verified"?"check-ok":"check-wait"}><b>{state.level==="skills_verified"?"✓":"○"} Навык монтажа</b><span>{state.level==="skills_verified"?"Работа проверена KIVRONIX":state.request?.status==="pending"?"Работа на проверке":"Можно отправить ссылку на свои работы"}</span></div>
    </div>

    {state.level!=="skills_verified"&&state.request?.status!=="pending"&&<form className="business-form" onSubmit={submit}>
      <input type="url" placeholder="Ссылка на свои работы" value={form.portfolioUrl} onChange={e=>setForm({...form,portfolioUrl:e.target.value})}/>
      <input type="url" placeholder="Или ссылка на одну работу" value={form.sampleUrl} onChange={e=>setForm({...form,sampleUrl:e.target.value})}/>
      <textarea placeholder="Что ты делал в этой работе? Например: нарезка, субтитры, звук." value={form.note} onChange={e=>setForm({...form,note:e.target.value})}/>
      <button className="btn btn-dark" disabled={loading}>{loading?"Отправляем…":"Отправить навык на проверку"}</button>
    </form>}

    {state.request?.status==="rejected"&&<div className="auth-msg">Нужно исправить: {state.request.review_note||"добавь более понятную работу и отправь новую заявку."}</div>}
    {message&&<div className="auth-msg">{message}</div>}
  </section>
}

"use client";

import {FormEvent,useCallback,useEffect,useRef,useState} from "react";
import {getSupabaseBrowserClient} from "@/lib/supabase-browser";

type GroupMessage={
  id:string;
  senderKind:"user"|"ai"|"moderator";
  content:string;
  createdAt:string;
  author:string;
  username:string|null;
};

export default function GroupChat({groupId,groupName}:{groupId:string;groupName:string}){
  const [messages,setMessages]=useState<GroupMessage[]>([]);
  const [input,setInput]=useState("");
  const [loading,setLoading]=useState(true);
  const [sending,setSending]=useState(false);
  const [notice,setNotice]=useState("");
  const feedRef=useRef<HTMLDivElement>(null);
  const inputRef=useRef<HTMLTextAreaElement>(null);

  const accessToken=useCallback(async()=>{
    const supabase=getSupabaseBrowserClient();
    const {data:{session}}=await supabase.auth.getSession();
    return session?.access_token||"";
  },[]);

  const load=useCallback(async(silent=false)=>{
    try{
      const access=await accessToken();
      if(!access){setNotice("Войди в аккаунт, чтобы открыть групповой чат.");return}
      const response=await fetch(`/api/social/groups/${groupId}/messages`,{headers:{Authorization:"Bearer "+access},cache:"no-store"});
      const data=await response.json();
      if(!response.ok)throw new Error(data?.error||"Ошибка загрузки чата.");
      setMessages(data.messages||[]);
      if(!silent)setNotice("");
    }catch(reason){
      if(!silent)setNotice(reason instanceof Error?reason.message:"Ошибка загрузки чата.");
    }finally{if(!silent)setLoading(false)}
  },[accessToken,groupId]);

  useEffect(()=>{
    void load();
    const timer=window.setInterval(()=>void load(true),12000);
    return()=>window.clearInterval(timer);
  },[load]);

  useEffect(()=>{
    feedRef.current?.scrollTo({top:feedRef.current.scrollHeight,behavior:"smooth"});
  },[messages.length]);

  async function submit(event:FormEvent){
    event.preventDefault();
    const content=input.trim();
    if(!content||sending)return;
    setSending(true);setNotice("");
    try{
      const access=await accessToken();
      if(!access)throw new Error("Войди в аккаунт, чтобы отправлять сообщения.");
      const response=await fetch(`/api/social/groups/${groupId}/messages`,{
        method:"POST",
        headers:{Authorization:"Bearer "+access,"Content-Type":"application/json"},
        body:JSON.stringify({content})
      });
      const data=await response.json();
      if(!response.ok)throw new Error(data?.error||"Ошибка отправки сообщения.");
      setMessages(data.messages||[]);
      setInput("");
      if(inputRef.current)inputRef.current.style.height="auto";
    }catch(reason){
      setNotice(reason instanceof Error?reason.message:"Ошибка отправки сообщения.");
    }finally{setSending(false)}
  }

  return <section className="group-chat card" aria-label={`Чат группы ${groupName}`}>
    <header className="group-chat-head">
      <div><div className="eyebrow">БЕЗОПАСНЫЙ УЧЕБНЫЙ ЧАТ</div><h3>{groupName}</h3></div>
      <span>Защита сообщений</span>
    </header>
    <p className="muted">Обсуждайте монтаж и общий проект вежливо. В чате остаются сообщения по теме и без личных контактов. Напиши <b>@kivronix</b>, <b>/ai</b> или поставь «?», чтобы позвать помощника.</p>
    <div className="group-chat-feed" ref={feedRef} aria-live="polite">
      {loading?<div className="ai-thinking">Загружаю сообщения…</div>:null}
      {!loading&&!messages.length?<div className="group-chat-empty"><b>Начните с простого вопроса</b><span>Например: «@kivronix, как всей группе снять один ролик?»</span></div>:null}
      {messages.map(message=><article className={`group-message ${message.senderKind}`} key={message.id}>
        <div><b>{message.author}</b><time>{new Date(message.createdAt).toLocaleTimeString("ru-RU",{hour:"2-digit",minute:"2-digit"})}</time></div>
        <p>{message.content}</p>
      </article>)}
    </div>
    {notice?<div className="auth-msg">{notice}</div>:null}
    <form className="group-chat-form" onSubmit={submit}>
      <textarea ref={inputRef} rows={2} maxLength={1400} value={input} onChange={event=>{setInput(event.target.value);const area=inputRef.current;if(area){area.style.height="auto";area.style.height=Math.min(160,area.scrollHeight)+"px"}}} placeholder="Сообщение по теме монтажа…"/>
      <button className="btn btn-lime" disabled={sending||!input.trim()}>{sending?"Проверяем…":"Отправить"}</button>
    </form>
  </section>;
}

"use client";

import {FormEvent,useEffect,useState} from "react";
import {getSupabaseBrowserClient} from "@/lib/supabase-browser";

type Data={
  needed:boolean;
  verified:boolean;
  request?:{status:string;review_note?:string|null;guardian_email?:string|null}|null;
};

export default function GuardianVerification(){
  const [data,setData]=useState<Data|null>(null);
  const [form,setForm]=useState({guardianName:"",guardianEmail:"",relationship:"Родитель"});
  const [message,setMessage]=useState("");
  const [loading,setLoading]=useState(false);

  async function headers():Promise<Record<string,string>>{
    const supabase=getSupabaseBrowserClient();
    const {data:{session}}=await supabase.auth.getSession();
    return session?.access_token?{Authorization:"Bearer "+session.access_token}:{};
  }

  async function load(){
    const h=await headers();
    const r=await fetch("/api/guardian/verification",{headers:h,cache:"no-store"});
    const json=await r.json();
    if(r.ok)setData(json);
  }

  useEffect(()=>{void load()},[]);

  async function submit(e:FormEvent){
    e.preventDefault();setLoading(true);setMessage("");
    try{
      const h=await headers();
      const r=await fetch("/api/guardian/verification",{
        method:"POST",
        headers:{...h,"Content-Type":"application/json"},
        body:JSON.stringify(form)
      });
      const json=await r.json();
      if(!r.ok)throw new Error(json?.error||"Ошибка отправки заявки.");
      setMessage("Заявка отправлена. Учёба уже открыта, а подтверждение взрослого откроет коммерческие функции.");
      await load();
    }catch(e){
      setMessage(e instanceof Error?e.message:"Ошибка.");
    }finally{setLoading(false)}
  }

  if(!data?.needed)return null;
  if(data.verified)return <section className="card"><div className="eyebrow">БЕЗОПАСНОСТЬ</div><h3>Родитель подтверждён ✓</h3><p className="muted">Коммерческие функции доступны с учётом остальных правил KIVRONIX.</p></section>;

  if(data.request?.status==="pending")return <section className="card"><div className="eyebrow">БЕЗОПАСНОСТЬ</div><h3>Ждём подтверждение родителя</h3><p className="muted">Заявка уже отправлена. Уроки и помощник доступны. Вакансии, оплачиваемая работа и конкурсы компаний откроются после подтверждения.</p></section>;

  return <section className="card">
    <div className="eyebrow">БЕЗОПАСНОСТЬ ДЛЯ ПОЛЬЗОВАТЕЛЕЙ ДО 18 ЛЕТ</div>
    <h3>Подтверждение родителя</h3>
    <p className="muted">Паспорт ребёнка остаётся за пределами этой формы. Заявка проверяется вручную, а KIVRONIX хранит только итог проверки взрослого.</p>
    <form className="business-form" onSubmit={submit}>
      <input required placeholder="Имя и фамилия родителя" value={form.guardianName} onChange={e=>setForm({...form,guardianName:e.target.value})}/>
      <input required type="email" placeholder="Электронная почта родителя" value={form.guardianEmail} onChange={e=>setForm({...form,guardianEmail:e.target.value})}/>
      <select value={form.relationship} onChange={e=>setForm({...form,relationship:e.target.value})}>
        <option>Родитель</option>
        <option>Опекун</option>
        <option>Попечитель</option>
        <option>Другой законный представитель</option>
      </select>
      <button className="btn btn-dark" disabled={loading}>{loading?"Отправляем…":"Отправить заявку"}</button>
    </form>
    {message&&<div className="auth-msg">{message}</div>}
  </section>
}

"use client";

import {FormEvent,useEffect,useState} from "react";
import {getSupabaseBrowserClient} from "@/lib/supabase-browser";

type JobApplication={job_id:string;editor_id:string;status:string;created_at?:string;editor?:{display_name?:string|null;username?:string|null}|null};
type Job={id:string;title:string;description:string;status?:string;budget_min_cents:number|null;budget_max_cents:number|null;payment_points?:number;businesses?:{name?:string;verified?:boolean;verification_level?:string}|null;applications?:JobApplication[];my_status?:string|null};
const demoJobs:Job[]=[
  {id:"d1",title:"Монтажёр коротких роликов",description:"5–7 вертикальных роликов в неделю.",budget_min_cents:null,budget_max_cents:null,businesses:{name:"Пример компании"}},
  {id:"d2",title:"Монтажёр для YouTube",description:"Видео с экспертом и дополнительными кадрами.",budget_min_cents:null,budget_max_cents:null,businesses:{name:"Студия авторов"}},
  {id:"d3",title:"Монтажёр рекламы",description:"Короткие ролики о товарах и услугах.",budget_min_cents:null,budget_max_cents:null,businesses:{name:"Команда роста"}},
];

export default function JobBoard({mode,viewerName="Компания",ageGroup,guardianVerified}:{mode:"editor"|"business";viewerName?:string;ageGroup?:string;guardianVerified?:boolean}){
  const [jobs,setJobs]=useState<Job[]>([]);
  const [businessId,setBusinessId]=useState<string|null>(null);
  const [businessVerified,setBusinessVerified]=useState(false);
  const [editorEligible,setEditorEligible]=useState(true);
  const [message,setMessage]=useState("");
  const [busyKey,setBusyKey]=useState("");
  const [form,setForm]=useState({title:"",description:"",points:""});
  const [editingId,setEditingId]=useState<string|null>(null);

  useEffect(()=>{void load()},[mode]);

  async function load(){
    const supabase=getSupabaseBrowserClient();
    if(!supabase){setJobs(demoJobs);return;}
    const {data:{user}}=await supabase.auth.getUser();
    if(!user){setJobs(demoJobs);return;}

    if(mode==="business"){
      let {data:business}=await supabase.from("businesses").select("id,verified,verification_level").eq("owner_id",user.id).maybeSingle();
      if(!business){
        const {data:created}=await supabase.from("businesses")
          .upsert({owner_id:user.id,name:viewerName+" Studio"},{onConflict:"owner_id"})
          .select("id,verified,verification_level")
          .single();
        business=created;
      }
      if(!business){setJobs([]);setMessage("Ошибка создания кабинета компании.");return;}
      setBusinessId(business.id);
      setBusinessVerified(Boolean((business as any).verified));
      const {data,error}=await supabase.from("jobs").select("id,title,description,status,budget_min_cents,budget_max_cents,payment_points").eq("business_id",business.id).order("created_at",{ascending:false});
      if(error){setMessage(error.message);return;}
      const rows=(data||[]) as Job[];
      const jobIds=rows.map(job=>job.id);
      const {data:applications}=jobIds.length?await supabase.from("job_applications")
        .select("job_id,editor_id,status,created_at")
        .in("job_id",jobIds)
        .order("created_at",{ascending:false}):{data:[] as JobApplication[]};
      const editorIds=[...new Set((applications||[]).map(item=>item.editor_id))];
      const {data:editors}=editorIds.length?await supabase.from("public_profiles")
        .select("id,display_name,username")
        .in("id",editorIds):{data:[] as Array<{id:string;display_name?:string|null;username?:string|null}>};
      const editorMap=Object.fromEntries((editors||[]).map(editor=>[editor.id,editor]));
      setJobs(rows.map(job=>({...job,applications:(applications||[]).filter(item=>item.job_id===job.id).map(item=>({...item,editor:editorMap[item.editor_id]||null}))})));
    }else{
      const {data:editorProfile}=await supabase.from("profiles").select("level,xp").eq("id",user.id).maybeSingle();
      setEditorEligible(Number(editorProfile?.level||1)>=2&&Number(editorProfile?.xp||0)>=300);
      const {data,error}=await supabase.from("jobs").select("id,business_id,title,description,budget_min_cents,budget_max_cents,payment_points").eq("status","open").order("created_at",{ascending:false});
      if(error){setMessage(error.message);setJobs(demoJobs);return;}
      const rows=(data||[]) as any[];
      const businessIds=[...new Set(rows.map(j=>j.business_id).filter(Boolean))];
      const {data:brands}=businessIds.length?await supabase.from("public_businesses").select("id,name,verified,verification_level").in("id",businessIds):{data:[] as any[]};
      const brandMap=Object.fromEntries((brands||[]).map((b:any)=>[b.id,b]));
      const {data:ownApplications}=await supabase.from("job_applications").select("job_id,status").eq("editor_id",user.id);
      const ownMap=Object.fromEntries((ownApplications||[]).map(item=>[item.job_id,item.status]));
      setJobs(rows.map(j=>({...j,my_status:ownMap[j.id]||null,businesses:{
        name:brandMap[j.business_id]?.name||"Компания",
        verified:Boolean(brandMap[j.business_id]?.verified),
        verification_level:brandMap[j.business_id]?.verification_level||"basic"
      }})) as Job[]);
    }
  }

  async function apply(jobId:string){
    if(!editorEligible){setMessage("Заказы откроются на уровне 2 после 300 XP. Сначала заверши первые уроки — так заказчик получит подготовленного монтажёра.");return;}
    if(mode==="editor"&&ageGroup&&ageGroup!=="18+"&&!guardianVerified){setMessage("Сначала нужно подтверждение родителя или законного представителя. Учиться можно без него.");return;}
    const supabase=getSupabaseBrowserClient();
    if(!supabase){setMessage("Пример: заявка сохранена только в браузере.");return;}
    const {data:{user}}=await supabase.auth.getUser();
    if(!user){setMessage("Войди, чтобы податься.");return;}
    const {error}=await supabase.from("job_applications").upsert({job_id:jobId,editor_id:user.id,status:"applied"},{onConflict:"job_id,editor_id"});
    setMessage(error?error.message:"Заявка отправлена бизнесу.");
    if(!error)await load();
  }

  async function acceptApplication(jobId:string,editorId:string){
    const key=jobId+":"+editorId;
    setBusyKey(key);setMessage("");
    const supabase=getSupabaseBrowserClient();
    const {data:{session}}=await supabase.auth.getSession();
    if(!session){setMessage("Войдите в аккаунт компании.");setBusyKey("");return;}
    const response=await fetch("/api/private-chats",{
      method:"POST",
      headers:{"Content-Type":"application/json",Authorization:"Bearer "+session.access_token},
      body:JSON.stringify({action:"accept_job_application",jobId,editorId})
    });
    const data=await response.json().catch(()=>({}));
    if(response.ok&&data?.conversationId)try{sessionStorage.setItem("kivronix_open_conversation",data.conversationId)}catch{}
    setMessage(response.ok?"Монтажёр выбран. Закрытый чат уже открыт.":data?.error||"Ошибка выбора монтажёра.");
    if(response.ok)await load();
    setBusyKey("");
  }

  async function create(e:FormEvent){
    e.preventDefault();
    const supabase=getSupabaseBrowserClient();
    if(!supabase||!businessId){setMessage("Войдите в аккаунт компании для публикации вакансии.");return;}
    if(!businessVerified){setMessage("Сначала пройди проверку компании. После этого можно публиковать реальные вакансии.");return;}
    const {error}=await supabase.from("jobs").insert({
      business_id:businessId,title:form.title,description:form.description,status:"open",
      payment_points:0,budget_min_cents:null,budget_max_cents:null
    });
    if(error){setMessage(error.message);return;}
    setForm({title:"",description:"",points:""});setMessage("Задание опубликовано. Условия безопасной сделки фиксируются после выбора монтажёра внутри KIVRONIX.");
    await load();
  }

  function startEdit(job:Job){setEditingId(job.id);setForm({title:job.title,description:job.description,points:""});setMessage("Меняйте формулировку и описание. Уже полученные отклики сохранятся.")}
  async function saveEdit(e:FormEvent){e.preventDefault();if(!editingId)return;const supabase=getSupabaseBrowserClient();const {error}=await supabase.from("jobs").update({title:form.title,description:form.description}).eq("id",editingId).eq("status","open");if(error){setMessage(error.message);return}setEditingId(null);setForm({title:"",description:"",points:""});setMessage("Изменения сохранены. Отклики остались на месте.");await load()}
  async function removeJob(jobId:string){if(!window.confirm("Удалить задание и закрыть приём откликов?"))return;const supabase=getSupabaseBrowserClient();const {error}=await supabase.from("jobs").delete().eq("id",jobId);setMessage(error?error.message:"Задание удалено.");if(!error)await load()}

  return <div className="job-board">
    {mode==="editor"&&!editorEligible&&<div className="auth-msg"><b>Работа откроется на уровне 2 · 300 XP.</b><br/>Пройди первые уроки и выполни учебные шаги. Смотреть задания можно уже сейчас, откликнуться — после достижения уровня.</div>}
    {mode==="business"&&<section className="card"><div className="eyebrow">{editingId?"ПОВЕРХНОСТНОЕ РЕДАКТИРОВАНИЕ":"НОВОЕ ЗАДАНИЕ"}</div><h3>{editingId?"Уточнить опубликованное задание":"Опубликовать работу"}</h3>{!businessVerified&&<div className="auth-msg">Сначала нужна проверка аккаунта. Это защищает монтажёров от вымышленных заказчиков.</div>}<form className="business-form" onSubmit={editingId?saveEdit:create}>
      <input required placeholder="Что нужно смонтировать" value={form.title} onChange={e=>setForm({...form,title:e.target.value})}/>
      <textarea required placeholder="Задачи, объём, формат работы" value={form.description} onChange={e=>setForm({...form,description:e.target.value})}/>
      <p className="safe-deal-note"><b>Оплата — только через безопасную сделку KIVRONIX.</b><span>Публично указывать рубли, телефон, почту или мессенджер нельзя. Условия фиксируются внутри заказа после выбора исполнителя; платёжный запуск появится после проверки банка и юриста.</span></p>
      <div className="lesson-actions"><button className="btn btn-dark" disabled={!businessVerified}>{businessVerified?(editingId?"Сохранить изменения":"Опубликовать"):"Сначала пройти проверку"}</button>{editingId?<button type="button" className="btn btn-ghost" onClick={()=>{setEditingId(null);setForm({title:"",description:"",points:""})}}>Отмена</button>:null}</div>
    </form></section>}

    <section className="grid job-grid">{jobs.map(job=><article className="card job" key={job.id}>
      <small>{mode==="editor"?(job.businesses?.name||"Компания"):"ВАША ВАКАНСИЯ"}</small>
      {mode==="business"?<span className={"tag "+(job.status==="open"?"verification-mini":"")}>{job.status==="open"?"Принимает отклики":"Исполнитель выбран"}</span>:null}
      {mode==="editor"&&job.businesses?.verified&&<span className="tag verification-mini">{badgeName(job.businesses.verification_level)}</span>}
      <h3>{job.title}</h3><p className="muted">{job.description}</p>
      <b>{budget(job)}</b>
      {mode==="editor"&&(job.my_status?<div className="auth-msg">Статус отклика: <b>{applicationStatus(job.my_status)}</b>{job.my_status==="accepted"?<><br/><a className="btn btn-dark" href="#messages" onClick={()=>rememberChat("job",job.id)}>Открыть закрытый чат</a></>:null}</div>:<button className="btn btn-dark" onClick={()=>apply(job.id)}>Податься</button>)}
      {mode==="business"?<><div className="job-owner-actions">{job.status==="open"?<button className="mini-btn" type="button" onClick={()=>startEdit(job)}>Изменить описание</button>:null}<button className="mini-btn danger" type="button" onClick={()=>void removeJob(job.id)}>Удалить задание</button></div><div className="job-applications"><b>Отклики · {job.applications?.length||0}</b>{job.applications?.length?job.applications.map(application=><div className="talent-row" key={application.editor_id}><div><b>{application.editor?.display_name||"Монтажёр"}</b><span>@{application.editor?.username||"editor"} · {applicationStatus(application.status)}</span></div><div className="chip-row">{application.status==="accepted"?<a className="mini-btn" href="#messages" onClick={()=>rememberChat("job",job.id)}>Открыть чат</a>:job.status==="open"?<button className="mini-btn" disabled={busyKey===job.id+":"+application.editor_id} onClick={()=>acceptApplication(job.id,application.editor_id)}>{busyKey===job.id+":"+application.editor_id?"Открываем…":"Выбрать по тесту"}</button>:null}</div></div>):<p className="muted">Отклики появятся здесь. Задание останется активным до вашего выбора или удаления.</p>}</div></>:null}
    </article>)}</section>
    {message&&<div className="auth-msg">{message}</div>}
  </div>
}

function budget(_job:Job){return "Безопасная сделка внутри KIVRONIX"}


function badgeName(level?:string){
  if(level==="popular_brand")return "★ Известный бренд";
  if(level==="partner")return "★ Партнёр KIVRONIX";
  return "✓ Проверенная компания";
}

function applicationStatus(status:string){
  if(status==="accepted")return "выбран";
  if(status==="declined")return "отклонён";
  if(status==="shortlisted")return "в избранном";
  return "отправлен";
}

function rememberChat(kind:string,id:string){
  try{sessionStorage.setItem("kivronix_open_chat_source",kind+":"+id)}catch{}
}

"use client";

import Link from "next/link";
import {useEffect,useState} from "react";
import ProfileAvatar from "@/components/profile-avatar";
import {getSupabaseBrowserClient} from "@/lib/supabase-browser";

type PublicProfile={display_name?:string|null;username?:string|null;avatar_url?:string|null};
type Leader={user_id:string;verified_views?:number;place?:number|null;profile?:PublicProfile|null};
type Competition={
  id:string;slug:string;title:string;description:string;task:string;ends_at?:string|null;competition_kind?:string;
  prize_pool_cents?:number;prize_split_cents?:number[];max_entries?:number;entry_count?:number;social_tag?:string;
  recurs_every_months?:number;age_eligible?:boolean;guardian_required?:boolean;leaders?:Leader[];
  entry?:{status:string;work_url:string;verified_views?:number;place?:number|null;prize_cents?:number}|null;
};

const fallback:Competition={
  id:"",slug:"kivronix-reels-season-1",title:"Сними ролик про KIVRONIX · Сезон 1",
  description:"Покажи, как KIVRONIX помогает новичку разобраться в монтаже, и расскажи о платформе своим языком.",
  task:"Создай оригинальный вертикальный ролик на 20–60 секунд, опубликуй его в открытой социальной сети и отметь @KIVRONIX.",
  ends_at:"2026-11-12T20:59:59.000Z",competition_kind:"prize",prize_pool_cents:1000000,
  prize_split_cents:[500000,300000,200000],max_entries:100,entry_count:0,social_tag:"@KIVRONIX",recurs_every_months:2,leaders:[]
};

export default function KivronixChallenges(){
  const [competition,setCompetition]=useState<Competition>(fallback);
  const [signedIn,setSignedIn]=useState(false);
  const [loading,setLoading]=useState(true);
  const [workUrl,setWorkUrl]=useState("");
  const [message,setMessage]=useState("");
  const [sending,setSending]=useState(false);
  const [levelEligible,setLevelEligible]=useState(false);

  async function load(){
    try{
      const supabase=getSupabaseBrowserClient();
      const {data:{session}}=await supabase.auth.getSession();
      setSignedIn(Boolean(session));
      if(!session)return;
      const {data:profile}=await supabase.from("profiles").select("level,xp").eq("id",session.user.id).maybeSingle();
      setLevelEligible(Number(profile?.level||1)>=2&&Number(profile?.xp||0)>=300);
      const response=await fetch("/api/social/competitions",{headers:{Authorization:"Bearer "+session.access_token},cache:"no-store"});
      const data=await response.json().catch(()=>({}));
      if(response.ok){
        const official=(data.competitions||[]).find((item:Competition)=>item.competition_kind==="prize"||item.slug?.startsWith("kivronix-reels-"));
        if(official){setCompetition(official);setWorkUrl(official.entry?.work_url||"");}
      }else setMessage(data?.error||"Ошибка загрузки конкурса.");
    }catch{setMessage("Ошибка загрузки конкурса. Проверь соединение и попробуй ещё раз.");}
    finally{setLoading(false)}
  }

  useEffect(()=>{void load()},[]);

  async function submit(){
    if(!competition.id||sending)return;
    setSending(true);setMessage("");
    const supabase=getSupabaseBrowserClient();
    const {data:{session}}=await supabase.auth.getSession();
    if(!session){setSignedIn(false);setSending(false);return;}
    const response=await fetch("/api/social/competitions",{
      method:"POST",headers:{"Content-Type":"application/json",Authorization:"Bearer "+session.access_token},
      body:JSON.stringify({competitionId:competition.id,workUrl})
    });
    const data=await response.json().catch(()=>({}));
    setMessage(response.ok?"Работа отправлена. После проверки просмотры появятся в рейтинге.":data?.error||"Ошибка отправки работы.");
    if(response.ok)await load();
    setSending(false);
  }

  const prizes=competition.prize_split_cents?.length?competition.prize_split_cents:fallback.prize_split_cents!;
  const count=Number(competition.entry_count||0);
  const limit=Number(competition.max_entries||100);
  const launchMinimum=50;
  const launched=count>=launchMinimum;
  const blocked=!levelEligible||competition.age_eligible===false||competition.guardian_required||count>=limit;

  return <div className="kivronix-challenges">
    <section className="kivronix-challenge-hero">
      <div>
        <div className="eyebrow">ОФИЦИАЛЬНЫЙ КОНКУРС ПЛАТФОРМЫ</div>
        <h2>{competition.title}</h2>
        <p>{competition.description}</p>
        <div className="challenge-launch-state"><b>{launched?"Сезон стартовал":"До старта осталось "+Math.max(0,launchMinimum-count)+" участников"}</b><span>{launched?"Конкурсный этап идёт по опубликованным правилам.":"Срок конкурса начнётся только после 50 регистраций."}</span></div><div className="kivronix-challenge-actions"><a className="btn btn-lime" href="#send-kivronix-work">{launched?"Отправить ролик":"Зарегистрироваться и отправить ролик"}</a><Link className="btn btn-light" href="/challenge-rules">Полные правила</Link></div>
      </div>
      <div className="kivronix-prize-picture" aria-label="Призовой фонд 10 000 KIVRONIX Points">
        <span>ПРИЗОВОЙ ФОНД</span><strong>{points(competition.prize_pool_cents||1000000)}</strong><small>1 Point = 1 ₽ внутри платформы</small>
      </div>
    </section>

    <section className="kivronix-prize-grid">
      <div><span>🥇</span><b>1 место</b><strong>{points(prizes[0]||0)}</strong></div>
      <div><span>🥈</span><b>2 место</b><strong>{points(prizes[1]||0)}</strong></div>
      <div><span>🥉</span><b>3 место</b><strong>{points(prizes[2]||0)}</strong></div>
      <div><span>👥</span><b>Участники</b><strong>{count} / {limit}</strong></div>
    </section>

    <div className="kivronix-challenge-layout">
      <section className="card kivronix-challenge-brief">
        <div className="eyebrow">ЧТО НУЖНО СДЕЛАТЬ</div><h3>{launched?"Один ролик — четыре понятных шага":"Предрегистрация до набора 50 участников"}</h3>
        <ol>
          <li><b>Придумай историю.</b><span>Покажи проблему новичка, один полезный момент KIVRONIX и честный результат.</span></li>
          <li><b>Собери ролик.</b><span>Вертикальное видео 20–60 секунд. Используй только свои или разрешённые материалы.</span></li>
          <li><b>Опубликуй открыто.</b><span>Размести ролик в открытой социальной сети и отметь {competition.social_tag||"@KIVRONIX"}.</span></li>
          <li><b>Отправь ссылку.</b><span>Вставь прямую HTTPS-ссылку ниже до окончания приёма.</span></li>
        </ol>
        <div className="lesson-example"><b>Задание сезона</b><span>{competition.task}</span></div>
      </section>

      <section className="card kivronix-challenge-facts">
        <div className="eyebrow">КАК ВЫБЕРЕМ ПОБЕДИТЕЛЕЙ</div><h3>По подтверждённым просмотрам</h3>
        <p>Побеждают три допустимые работы с самым большим подтверждённым числом просмотров. Команда KIVRONIX проверяет ссылку, открытость публикации, отметку и отсутствие накрутки.</p>
        <dl>
          <div><dt>Возраст</dt><dd>от 14 лет</dd></div>
          <div><dt>До 18 лет</dt><dd>нужно подтверждение законного представителя</dd></div>
          <div><dt>Приём до</dt><dd>{date(competition.ends_at)}</dd></div>
          <div><dt>Новый сезон</dt><dd>каждые {competition.recurs_every_months||2} месяца</dd></div>
        </dl>
        <p className="minor-safety-note"><b>Важно</b><span>10 000 KIVRONIX Points — фонд конкурса. 1 Point = 1 ₽ при использовании внутри платформы. Участие открыто без покупки.</span></p>
      </section>
    </div>

    <section className="card kivronix-work-submit" id="send-kivronix-work">
      <div><div className="eyebrow">ТВОЯ РАБОТА</div><h3>{competition.entry?"Работа уже участвует":"Отправь опубликованный ролик"}</h3></div>
      {signedIn&&!levelEligible&&<div className="auth-msg"><b>Конкурсы откроются на уровне 2 · 300 XP.</b><br/>Сначала заверши первые уроки. Задание и правила уже можно посмотреть.</div>}
      {loading?<div className="auth-msg">Загружаем конкурс…</div>:competition.entry?<div className="kivronix-entry-status"><b>{competition.entry.place?competition.entry.place+" место":"Ссылка принята"}</b><span>{Number(competition.entry.verified_views||0).toLocaleString("ru-RU")} подтверждённых просмотров</span><a href={competition.entry.work_url} target="_blank" rel="noreferrer">Открыть публикацию ↗</a>{competition.entry.place&&<a href="#messages" onClick={()=>rememberChat("kivronix_contest",competition.id)}>Открыть закрытый чат ↗</a>}</div>:!signedIn?<div className="kivronix-signin-box"><p>Для отправки ссылки нужен аккаунт KIVRONIX. Сам конкурс можно посмотреть без входа.</p><Link className="btn btn-dark" href="/login?from=/platform%23kivronix-challenges">Войти и участвовать</Link></div>:<div className="business-form"><label className="field-label" htmlFor="kivronix-work-url">Прямая ссылка на открытую публикацию</label><input id="kivronix-work-url" type="url" inputMode="url" placeholder="https://…" value={workUrl} onChange={event=>setWorkUrl(event.target.value)}/><button className="btn btn-dark" onClick={submit} disabled={!competition.id||blocked||sending||!workUrl.trim()}>{sending?"Отправляем…":count>=limit?"Лимит участников достигнут":competition.age_eligible===false?"Доступно с 14 лет":competition.guardian_required?"Нужно подтверждение взрослого":"Отправить работу"}</button></div>}
      {message?<div className="auth-msg">{message}</div>:null}
    </section>

    <section className="card kivronix-leaderboard">
      <div className="verification-head"><div><div className="eyebrow">РЕЙТИНГ СЕЗОНА</div><h3>Лидеры по просмотрам</h3></div><span className="verification-badge ok">обновляется после проверки</span></div>
      {competition.leaders?.length?<div className="competition-live-leaders">{competition.leaders.slice(0,10).map((leader,index)=><div key={leader.user_id}><span>{leader.place||index+1}</span><ProfileAvatar src={leader.profile?.avatar_url} name={leader.profile?.display_name} size="sm"/><p><strong>{leader.profile?.display_name||"Монтажёр"}</strong><small>@{leader.profile?.username||"editor"}</small></p><em>{Number(leader.verified_views||0).toLocaleString("ru-RU")}</em></div>)}</div>:<div className="kivronix-empty-leaders"><b>Первые места пока свободны</b><span>После проверки первых публикаций здесь появятся участники и подтверждённые просмотры.</span></div>}
    </section>
  </div>;
}

function points(cents:number){return new Intl.NumberFormat("ru-RU").format(Math.round(cents/100))+" KP"}
function date(value?:string|null){return value?new Date(value).toLocaleDateString("ru-RU",{day:"numeric",month:"long",year:"numeric"}):"указано в правилах"}

function rememberChat(kind:string,id:string){
  try{sessionStorage.setItem("kivronix_open_chat_source",kind+":"+id)}catch{}
}

"use client";

import {FormEvent,useCallback,useEffect,useMemo,useState} from "react";
import {getFreshAccessToken,getSupabaseBrowserClient} from "@/lib/supabase-browser";
import {uploadPortfolioVideo} from "@/lib/portfolio-video-upload";

type Author={display_name:string;username?:string;avatar_url?:string;kind:"editor"|"creator"|"business";verified:boolean};
type Comment={id:string;body:string;created_at:string;author:Author};
type Clip={id:string;title:string;display_url?:string;tags:string[];ai_score:number|null;storage_backed:boolean;created_at:string;author:Author;likes:number;comments_count:number;shares:number;liked:boolean;following:boolean;own:boolean;cta?:string;comments:Comment[]};
type Competition={id:string;title:string;brief:string;prize_text:string;ends_at:string;host_name:string;entries:number;owned:boolean;entered:boolean;can_enter:boolean;can_create:boolean;winning_title?:string};

export default function KivronixVideo({isCreator=false}:{isCreator?:boolean}){
  const [section,setSection]=useState<"feed"|"competitions">("feed");
  const [clips,setClips]=useState<Clip[]>([]);
  const [competitions,setCompetitions]=useState<Competition[]>([]);
  const [message,setMessage]=useState("");
  const [busy,setBusy]=useState("");
  const [publish,setPublish]=useState({title:"",videoUrl:"",tags:""});
  const [videoFile,setVideoFile]=useState<File|null>(null);
  const [comment,setComment]=useState<Record<string,string>>({});
  const [contest,setContest]=useState({title:"",brief:"",prizeText:"",endsAt:""});

  const token=useCallback(async()=>{
    return getFreshAccessToken();
  },[]);
  const call=useCallback(async(path:string,init?:RequestInit)=>{
    const access=await token();if(!access)throw new Error("Войдите в аккаунт, чтобы открыть KIVRONIX Video.");
    const response=await fetch(path,{...init,headers:{Authorization:"Bearer "+access,...(init?.body?{"Content-Type":"application/json"}:{}),...(init?.headers||{})},cache:"no-store"});
    const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data?.error?.message||data?.error||"Действие не выполнено.");return data;
  },[token]);
  const load=useCallback(async()=>{try{const [feed,contests]=await Promise.all([call("/api/video"),call("/api/video/competitions")]);setClips(feed.clips||[]);setCompetitions(contests.competitions||[]);setMessage("");}catch(error){setMessage(error instanceof Error?error.message:"Не удалось загрузить ленту.");}},[call]);
  useEffect(()=>{void load()},[load]);

  async function act(clip:Clip,action:string,body=""){
    setBusy(action+clip.id);setMessage("");
    try{
      const data=await call("/api/video",{method:"POST",body:JSON.stringify({action,videoId:clip.id,...(["share","comment"].includes(action)?{id:crypto.randomUUID()}:{}),...(body?{body}:{})})});
      if(action==="open_chat"&&data.conversation_id){window.location.hash="messages";window.location.reload();return;}
      if(action==="share"){await navigator.clipboard?.writeText(`${location.origin}/platform#portfolio`);setMessage("Ссылка на KIVRONIX Video скопирована.");}
      await load();
    }catch(error){setMessage(error instanceof Error?error.message:"Действие не выполнено.");}finally{setBusy("");}
  }
  async function publishVideo(event:FormEvent){event.preventDefault();setBusy("publish");try{
    let videoUrl=publish.videoUrl.trim();
    if(videoFile){const {data:{user}}=await getSupabaseBrowserClient().auth.getUser();if(!user)throw new Error("Войди в аккаунт, чтобы загрузить файл.");videoUrl=await uploadPortfolioVideo(videoFile,user.id)}
    if(!videoUrl)throw new Error("Добавь видеофайл или HTTPS-ссылку.");
    await call("/api/portfolio",{method:"POST",body:JSON.stringify({title:publish.title,videoUrl,tags:publish.tags.split(",").map(x=>x.trim()).filter(Boolean),publicationConsent:true,sourceLabel:videoFile?"Загрузка из файлов":"Внешняя ссылка"})});
    setPublish({title:"",videoUrl:"",tags:""});setVideoFile(null);setMessage("Ролик опубликован с хештегом #KIVRONIX.");await load();
  }catch(error){setMessage(error instanceof Error?error.message:"Не удалось опубликовать ролик.");}finally{setBusy("");}}
  async function createCompetition(event:FormEvent){event.preventDefault();setBusy("contest");try{await call("/api/video/competitions",{method:"POST",body:JSON.stringify({action:"create",...contest,endsAt:new Date(contest.endsAt).toISOString()})});setContest({title:"",brief:"",prizeText:"",endsAt:""});setMessage("Соревнование опубликовано.");await load();}catch(error){setMessage(error instanceof Error?error.message:"Не удалось создать соревнование.");}finally{setBusy("");}}
  async function enterCompetition(item:Competition,videoId:string){setBusy(item.id);try{await call("/api/video/competitions",{method:"POST",body:JSON.stringify({action:"enter",competitionId:item.id,videoId})});setMessage("Работа отправлена на соревнование.");await load();}catch(error){setMessage(error instanceof Error?error.message:"Не удалось отправить работу.");}finally{setBusy("");}}

  const ownClips=useMemo(()=>clips.filter(item=>item.own),[clips]);
  return <div className="kv-video">
    <header className="kv-video-intro"><div><div className="eyebrow">KIVRONIX VIDEO</div><h2>Работы, которые хочется досмотреть</h2><p>Общая вертикальная лента монтажёров, блогеров и компаний. Смотри, подписывайся и начинай совместную работу внутри платформы.</p></div><nav><button className={section==="feed"?"active":""} onClick={()=>setSection("feed")}>Лента</button><button className={section==="competitions"?"active":""} onClick={()=>setSection("competitions")}>Соревнования блогеров</button></nav></header>
    {message&&<div className="auth-msg kv-video-message">{message}</div>}
    {section==="feed"&&<>
      <details className="kv-publish"><summary>＋ Опубликовать свой ролик</summary><form className="business-form" onSubmit={publishVideo}><input required minLength={2} maxLength={160} placeholder="Название ролика" value={publish.title} onChange={e=>setPublish({...publish,title:e.target.value})}/><label className="styled-file-control"><span>Загрузить видео из файлов</span><small>{videoFile?videoFile.name:"MP4, MOV или WebM · до 200 МБ"}</small><input type="file" accept="video/mp4,video/quicktime,video/webm,video/*" onChange={e=>setVideoFile(e.target.files?.[0]||null)}/></label><div className="form-divider">или вставь ссылку</div><input type="url" placeholder="Прямая HTTPS-ссылка на видео" value={publish.videoUrl} onChange={e=>setPublish({...publish,videoUrl:e.target.value})}/><input placeholder="Темы через запятую" value={publish.tags} onChange={e=>setPublish({...publish,tags:e.target.value})}/><p className="publish-consent">Нажимая «Опубликовать», ты разрешаешь показать этот ролик в общей ленте KIVRONIX Video. Разрешение можно отозвать, удалив работу из профиля.</p><button className="btn btn-lime" disabled={busy==="publish"}>{busy==="publish"?"Загружаем…":"Опубликовать · #KIVRONIX"}</button></form></details>
      <section className="kv-reel-feed">{clips.length?clips.map(clip=><article className="kv-reel" key={clip.id}>
        <div className="kv-reel-stage">{clip.display_url&&isDirectVideo(clip.display_url)?<video src={clip.display_url} controls playsInline preload="metadata"/>:clip.display_url?<a href={clip.display_url} target="_blank" rel="noreferrer" className="kv-video-placeholder"><b>Открыть работу ↗</b><span>Видео размещено на внешней защищённой странице</span></a>:<div className="kv-video-placeholder"><b>KIVRONIX ORIGINAL</b><span>{clip.storage_backed?"Защищённый файл автора":"Превью готовится"}</span></div>}
          <div className="kv-reel-copy"><div className="kv-author"><Avatar author={clip.author}/><div><b>{clip.author.display_name}</b><span>{kindLabel(clip.author.kind)}{clip.author.verified?" · подтверждён":""}</span></div>{!clip.own&&<button onClick={()=>void act(clip,"follow")}>{clip.following?"Вы подписаны":"Подписаться"}</button>}</div><h3>{clip.title}</h3><p>{["#KIVRONIX",...(clip.tags||[]).filter(tag=>tag.toLowerCase()!=="#kivronix"&&tag.toLowerCase()!=="kivronix")].join("  ")}</p>{clip.ai_score!=null&&<small>Оценка KIVRONIX AI · {clip.ai_score}/100</small>}</div>
        </div>
        <aside className="kv-reel-actions"><button className={clip.liked?"active":""} onClick={()=>void act(clip,"like")} aria-label="Поставить лайк"><span>♥</span><b>{clip.likes}</b></button><button onClick={()=>document.getElementById("comments-"+clip.id)?.focus()} aria-label="Комментировать"><span>●</span><b>{clip.comments_count}</b></button><button onClick={()=>void act(clip,"share")} aria-label="Поделиться"><span>↗</span><b>{clip.shares}</b></button></aside>
        <div className="kv-reel-bottom">{clip.cta&&<button className="btn btn-lime" disabled={busy==="open_chat"+clip.id} onClick={()=>void act(clip,"open_chat")}>{clip.cta} →</button>}<div className="kv-comments">{clip.comments.map(item=><p key={item.id}><b>{item.author.display_name}</b> {item.body}</p>)}<form onSubmit={event=>{event.preventDefault();const value=comment[clip.id]?.trim();if(value){void act(clip,"comment",value);setComment(current=>({...current,[clip.id]:""}))}}}><input id={"comments-"+clip.id} maxLength={500} placeholder="Комментарий без контактов и ссылок" value={comment[clip.id]||""} onChange={e=>setComment(current=>({...current,[clip.id]:e.target.value}))}/><button aria-label="Отправить комментарий">↑</button></form></div></div>
      </article>):<div className="kv-empty"><b>Лента ждёт первые работы</b><span>Опубликуй ролик — он будет доступен всем участникам KIVRONIX.</span></div>}</section>
    </>}
    {section==="competitions"&&<section className="kv-competitions">
      {isCreator&&<details className="kv-publish" open><summary>Создать соревнование для авторов</summary><form className="business-form" onSubmit={createCompetition}><input required minLength={3} maxLength={120} placeholder="Название соревнования" value={contest.title} onChange={e=>setContest({...contest,title:e.target.value})}/><textarea required minLength={10} maxLength={3000} placeholder="Задание и критерии" value={contest.brief} onChange={e=>setContest({...contest,brief:e.target.value})}/><input required maxLength={300} placeholder="Приз или награда" value={contest.prizeText} onChange={e=>setContest({...contest,prizeText:e.target.value})}/><label>Приём работ до<input required type="datetime-local" value={contest.endsAt} onChange={e=>setContest({...contest,endsAt:e.target.value})}/></label><button className="btn btn-lime" disabled={busy==="contest"}>{busy==="contest"?"Публикуем…":"Запустить соревнование"}</button></form></details>}
      <div className="kv-competition-grid">{competitions.map(item=><article key={item.id}><span>СОРЕВНОВАНИЕ БЛОГЕРА</span><h3>{item.title}</h3><p>{item.brief}</p><div><b>{item.prize_text}</b><small>до {new Date(item.ends_at).toLocaleDateString("ru-RU")} · {item.entries} работ</small></div>{item.can_enter&&!item.entered&&ownClips.length>0&&<select defaultValue="" onChange={e=>e.target.value&&void enterCompetition(item,e.target.value)}><option value="" disabled>Выбрать свою работу для участия</option>{ownClips.map(clip=><option value={clip.id} key={clip.id}>{clip.title}</option>)}</select>}{item.entered&&<strong>✓ Ты участвуешь</strong>}</article>)}</div>
    </section>}
  </div>
}

function Avatar({author}:{author:Author}){return author.avatar_url?<img src={author.avatar_url} alt=""/>:<span className="kv-avatar">{author.display_name.slice(0,1).toUpperCase()}</span>}
function kindLabel(kind:Author["kind"]){return kind==="editor"?"Монтажёр":kind==="creator"?"Блогер":"Компания"}
function isDirectVideo(url:string){return /\.(mp4|webm|mov)(\?|$)/i.test(url)}

"use client";

import Link from "next/link";
import {useEffect,useState} from "react";
import {getFreshAccessToken} from "@/lib/supabase-browser";
import {getSupabaseBrowserClient} from "@/lib/supabase-browser";
import {extractVideoFrames} from "@/lib/video-frames";
import {uploadPortfolioVideo} from "@/lib/portfolio-video-upload";
import {assessmentRequiredLessons,curriculumModules,lessonBySlug,normalizeExperienceLevel} from "@/lib/curriculum";

export default function LessonProgressButton({slug,xp,nextSlug,theoryOnly=false}:{slug:string;xp:number;nextSlug?:string|null;theoryOnly?:boolean}){
  const [done,setDone]=useState(false);
  const [confirmed,setConfirmed]=useState(false);
  const [note,setNote]=useState("");
  const [saving,setSaving]=useState(false);
  const [notice,setNotice]=useState("");
  const [video,setVideo]=useState<File|null>(null);
  const [reviewScore,setReviewScore]=useState<number|null>(null);
  const [reviewSummary,setReviewSummary]=useState("");
  const [shareApproved,setShareApproved]=useState(false);
  const [reviewing,setReviewing]=useState(false);
  const [isPro,setIsPro]=useState(false);
  const [experienceLevel,setExperienceLevel]=useState<unknown>("new");
  const [completedSlugs,setCompletedSlugs]=useState<string[]>([]);
  const currentLesson=lessonBySlug(slug);
  const currentModuleIndex=curriculumModules.findIndex(group=>group.module===currentLesson?.module);
  const requiredLessons=currentModuleIndex>=0?assessmentRequiredLessons(currentModuleIndex,experienceLevel):[];
  const assessmentReady=currentModuleIndex>=0&&!isPro&&requiredLessons.length>0&&requiredLessons.every(item=>item.slug===slug||completedSlugs.includes(item.slug));
  const assessmentIndex=assessmentReady?currentModuleIndex:null;

  useEffect(()=>{
    let active=true;
    async function load(){
      try{
        const saved=JSON.parse(localStorage.getItem("kivronix_lesson_done")||"[]");
        if(Array.isArray(saved)&&active){
          const values=saved.filter((item):item is string=>typeof item==="string");
          setCompletedSlugs(values);
          if(values.includes(slug))setDone(true);
        }
        const onboarding=JSON.parse(localStorage.getItem("kivronix_onboarding")||"{}");
        if(active){setExperienceLevel(onboarding?.level);setIsPro(normalizeExperienceLevel(onboarding?.level)==="pro")}
      }catch{}
      const accessToken=await getFreshAccessToken();
      if(!accessToken)return;
      try{
        const headers={Authorization:"Bearer "+accessToken};
        const [response,profileResponse]=await Promise.all([
          fetch("/api/lessons/progress",{headers,cache:"no-store"}),
          fetch("/api/profile/learning-preferences",{headers,cache:"no-store"}),
        ]);
        if(profileResponse.ok){
          const profile=await profileResponse.json();
          if(active){setExperienceLevel(profile?.preferences?.level);setIsPro(normalizeExperienceLevel(profile?.preferences?.level)==="pro")}
        }
        if(!response.ok)return;
        const data=await response.json();
        if(active&&Array.isArray(data?.completedSlugs)){
          const values=data.completedSlugs.filter((item:unknown):item is string=>typeof item==="string");
          setCompletedSlugs(values);
          setDone(values.includes(slug));
        }
      }catch{}
    }
    void load();
    return()=>{active=false};
  },[slug]);

  async function reviewVideo(){
    if(!video)return;
    setReviewing(true);setNotice("");setReviewScore(null);setShareApproved(false);
    try{
      const accessToken=await getFreshAccessToken();
      if(!accessToken)throw new Error("Войди в аккаунт, чтобы ИИ проверил работу.");
      const extracted=await extractVideoFrames(video,7);
      const response=await fetch("/api/ai/video-review",{method:"POST",headers:{"Content-Type":"application/json",Authorization:"Bearer "+accessToken},body:JSON.stringify({frames:extracted.frames,duration:extracted.duration,width:extracted.width,height:extracted.height,filename:video.name,brief:`Практическое задание урока ${slug}`,purpose:"standalone"})});
      const data=await response.json();
      if(!response.ok)throw new Error(data?.error||"ИИ не смог проверить видео.");
      const score=Number(data.review?.overall_score||0);setReviewScore(score);setReviewSummary(String(data.review?.summary||"Разбор готов."));
    }catch(error){setNotice(error instanceof Error?error.message:"Не удалось проверить видео.")}finally{setReviewing(false)}
  }

  async function complete(){
    if(saving||done||!confirmed)return;
    setSaving(true);setNotice("");
    try{
      const accessToken=await getFreshAccessToken();
      if(!accessToken)throw new Error("Сессия устарела. Обнови страницу и войди снова.");
      {
        const response=await fetch("/api/lessons/progress",{
          method:"POST",
          headers:{"Content-Type":"application/json",Authorization:"Bearer "+accessToken},
          body:JSON.stringify({slug,completed:true,taskConfirmed:true,submissionNote:note})
        });
        const data=await response.json();
        if(!response.ok)throw new Error(data?.error||"Ошибка сохранения прогресса.");
        void fetch("/api/referral/qualify",{method:"POST",headers:{Authorization:"Bearer "+accessToken}}).catch(()=>{});
      }

      if(video&&reviewScore!=null&&reviewScore>=75&&shareApproved){
        const {data:{user}}=await getSupabaseBrowserClient().auth.getUser();
        if(!user)throw new Error("Не удалось подтвердить аккаунт для публикации.");
        const videoUrl=await uploadPortfolioVideo(video,user.id);
        const publication=await fetch("/api/portfolio",{method:"POST",headers:{"Content-Type":"application/json",Authorization:"Bearer "+accessToken},body:JSON.stringify({title:`Учебная работа · ${slug}`,videoUrl,tags:["обучение","задание"],aiScore:reviewScore,publicationConsent:true,sourceLabel:"Учебное задание"})});
        if(!publication.ok){const data=await publication.json().catch(()=>({}));throw new Error(data?.error?.message||data?.error||"Задание сохранено, но видео не опубликовано.")}
      }

      const saved=JSON.parse(localStorage.getItem("kivronix_lesson_done")||"[]");
      const values=Array.isArray(saved)?saved.filter((item):item is string=>typeof item==="string"):[];
      const nextCompleted=Array.from(new Set([...values,...completedSlugs,slug]));
      localStorage.setItem("kivronix_lesson_done",JSON.stringify(nextCompleted));
      setCompletedSlugs(nextCompleted);
      setDone(true);
      const readyForAssessment=currentModuleIndex>=0&&!isPro&&assessmentRequiredLessons(currentModuleIndex,experienceLevel).every(item=>nextCompleted.includes(item.slug));
      setNotice(readyForAssessment?"Ступень завершена. Открываем аттестацию…":theoryOnly?"Урок завершён. Следующий урок открыт.":"Задание принято. Следующий урок открыт.");
      window.dispatchEvent(new CustomEvent("kivronix:lesson-completed",{detail:{slug}}));
      if(readyForAssessment)window.setTimeout(()=>window.location.assign(`/academy/assessment/${currentModuleIndex}`),650);
    }catch(error){
      setNotice(error instanceof Error?error.message:"Ошибка сохранения задания.");
    }finally{setSaving(false)}
  }

  return <div className="lesson-progress-action">
    {!done?<>
      <label className="task-confirm-row"><input type="checkbox" checked={confirmed} onChange={event=>setConfirmed(event.target.checked)}/><span>{theoryOnly?"Я прочитал урок и могу объяснить его главную мысль своими словами.":"Я выполнил задание и проверил результат по чек-листу."}</span></label>
      {!theoryOnly?<><textarea value={note} onChange={event=>setNote(event.target.value)} maxLength={1000} rows={2} placeholder="Можно написать, что получилось или где было сложно"/><div className="lesson-video-review"><label className="styled-file-control"><span>Добавить видео задания для проверки</span><small>{video?video.name:"Необязательно · MP4, MOV или WebM"}</small><input type="file" accept="video/*" onChange={event=>{setVideo(event.target.files?.[0]||null);setReviewScore(null);setShareApproved(false)}}/></label>{video?<button className="btn btn-ghost" type="button" onClick={()=>void reviewVideo()} disabled={reviewing}>{reviewing?"ИИ проверяет…":"Проверить видео с ИИ"}</button>:null}{reviewScore!=null?<div className={reviewScore>=75?"ai-publish-offer good":"ai-publish-offer"}><b>ИИ‑оценка: {reviewScore}/100</b><p>{reviewSummary}</p>{reviewScore>=75?<label><input type="checkbox" checked={shareApproved} onChange={event=>setShareApproved(event.target.checked)}/><span>Разрешаю опубликовать это видео в общей ленте KIVRONIX Video</span></label>:<span>Сначала улучши ролик по подсказкам. Публикация пока не предлагается.</span>}</div>:null}</div></>:null}
      <button className="btn btn-lime" type="button" onClick={complete} disabled={saving||!confirmed}>{saving?"Сохраняю…":theoryOnly?"Всё понятно · +"+xp+" опыта":"Сдать задание · +"+xp+" опыта"}</button>
    </>:<div className="lesson-complete-box"><b>{theoryOnly?"Теория пройдена":"Задание выполнено"}</b><span>{assessmentIndex!=null?"Ступень завершена — пора подтвердить навыки.":"Прогресс сохранён, следующий урок открыт."}</span>{assessmentIndex!=null?<Link className="btn btn-dark" href={`/academy/assessment/${assessmentIndex}`}>Перейти к аттестации →</Link>:nextSlug?<Link className="btn btn-dark" href={"/academy/"+nextSlug}>Перейти к следующему уроку →</Link>:<Link className="btn btn-dark" href="/platform#academy">Вернуться в Академию</Link>}</div>}
    {notice?<small>{notice}</small>:null}
  </div>;
}

"use client";

import Link from "next/link";
import {usePathname,useRouter} from "next/navigation";
import {useEffect,useState} from "react";
import {getFreshAccessToken} from "@/lib/supabase-browser";
import {lessonAccess,nextAvailableLesson} from "@/lib/curriculum";

export default function LessonRouteGate({children}:{requiredSlugs:string[];previousSlug?:string|null;children:React.ReactNode}){
  const router=useRouter();
  const pathname=usePathname();
  const [checking,setChecking]=useState(true);
  const [unlocked,setUnlocked]=useState(false);
  const [returnSlug,setReturnSlug]=useState<string|null>(null);
  const [lockedByAssessment,setLockedByAssessment]=useState(false);

  useEffect(()=>{
    let active=true;
    async function check(){
      let completed:string[]=[];
      let passed:number[]=[];
      let level:unknown="new";
      try{
        const saved=JSON.parse(localStorage.getItem("kivronix_lesson_done")||"[]");
        if(Array.isArray(saved))completed=saved.filter((item):item is string=>typeof item==="string");
        const savedAssessments=JSON.parse(localStorage.getItem("kivronix_academy_assessments")||"[]");
        if(Array.isArray(savedAssessments))passed=savedAssessments.filter((item):item is number=>Number.isInteger(item));
        const savedOnboarding=JSON.parse(localStorage.getItem("kivronix_onboarding")||"{}");
        if(savedOnboarding&&typeof savedOnboarding==="object")level=savedOnboarding.level;
      }catch{}

      const applyAccess=()=>{
        const slug=pathname.split("/").pop()||"";
        const access=lessonAccess(slug,completed,passed,level);
        const available=nextAvailableLesson(completed,passed,level);
        if(active){
          setUnlocked(access.unlocked);
          setLockedByAssessment(access.reason==="assessment");
          setReturnSlug(available?.slug||null);
          setChecking(false);
        }
      };

      const accessToken=await getFreshAccessToken();
      if(!accessToken){
        router.replace("/login?from="+encodeURIComponent(pathname));
        return;
      }
      {
        const headers={Authorization:"Bearer "+accessToken};
        const responses=await Promise.all([
          fetch("/api/profile/learning-preferences",{headers,cache:"no-store"}),
          fetch("/api/lessons/progress",{headers,cache:"no-store"}),
          fetch("/api/academy/assessments",{headers,cache:"no-store"}),
        ]).catch(()=>null);
        if(!responses){
          applyAccess();
          return;
        }
        const [profileResponse,progressResponse,assessmentResponse]=responses;
        if(!profileResponse.ok||!progressResponse.ok||!assessmentResponse.ok){
          applyAccess();
          return;
        }
        const [profile,progress,assessments]=await Promise.all([profileResponse.json(),progressResponse.json(),assessmentResponse.json()]);
        const fromAccount=Array.isArray(progress?.completedSlugs)?progress.completedSlugs.filter((slug:unknown):slug is string=>typeof slug==="string"):[];
        completed=fromAccount;
        passed=Array.isArray(assessments.passed)?assessments.passed:[];
        level=profile?.preferences?.level||level;
        applyAccess();
        try{localStorage.setItem("kivronix_lesson_done",JSON.stringify(completed))}catch{}
        return;
      }
    }
    void check();
    return()=>{active=false};
  },[pathname,router]);

  if(checking)return <div className="lesson-gate-card"><b>Проверяем вход и прогресс…</b></div>;
  if(!unlocked)return <div className="lesson-gate-card locked"><div className="eyebrow">СЛЕДУЮЩАЯ СТУПЕНЬ ПОКА ЗАКРЫТА</div><h2>{lockedByAssessment?"Сначала пройди аттестацию текущей ступени":"Этот урок пока недоступен"}</h2><p>{lockedByAssessment?"Все уроки текущей ступени можно открывать в любом порядке. После аттестации откроется следующий блок.":"Вернись в учебный план и выбери открытый урок."}</p><div>{returnSlug?<Link className="btn btn-dark" href={"/academy/"+returnSlug}>Открыть доступный урок</Link>:null}<Link className="btn btn-ghost" href="/platform#academy">Перейти к учебному плану</Link></div></div>;
  return <>{children}</>;
}

