         <Card title="О себе"><div className="editor-profile-description"><b>Монтажёр Reels для экспертов и авторов</b><p>Субтитры, динамичный монтаж, музыка и оформление</p><p>Работаю в Adobe Premiere Pro</p><p>Портфолио — по ссылке</p><p>Заказ и вопросы — в Direct</p></div></Card>
         <Card title="Навыки"><Skill label="Основа монтажа" value={Math.min(100,done.filter(s=>["what-is-editing","hook-basics","story-basics","retention-basics","editor-words","clean-cut"].includes(s)).length*16)}/><Skill label="Удержание зрителя" value={Math.min(100,done.filter(s=>["hook-basics","retention-basics","hook-2-seconds","subtitles","b-roll","sound"].includes(s)).length*16)}/><Skill label="Работа с клиентом" value={Math.min(100,done.filter(s=>["client-brief","pricing","portfolio"].includes(s)).length*33)}/></Card>
         <Card title="Настройки обучения"><p className="muted">Уровень: {viewer.onboarding?.level||"пока пусто"}<br/>Программа: {viewer.onboarding?.software||"пока пусто"}<br/>Цель: {viewer.onboarding?.goal||"пока пусто"}</p><Link className="btn btn-ghost" href="/onboarding">Изменить настройки</Link></Card><EditorVerification/>{viewer.onboarding?.ageGroup&&viewer.onboarding.ageGroup!=="18+"&&<GuardianVerification/>}
         <AiCoach compact scopeKey="profile:editor" title="Помощник по профилю" welcome="Помогу описать навыки, выбрать сильные работы и оформить профиль без громких обещаний." prompts={["Помоги написать описание профиля","Какие работы добавить первыми?","Как описать мой уровень?"]} context={{role:"editor",editor:viewer.onboarding?.software,goal:viewer.onboarding?.goal}}/>
       </div>
     </Page>}

     {tab==="profile"&&viewer.role==="business"&&!isCreator&&<Page title="Профиль компании" sub="Единая карточка бренда, которую видят помощник и приглашённые монтажёры."><div className="business-stack"><BrandBrain viewerName={viewer.name}/><BusinessVerification/><AiCoach compact scopeKey="profile:business" title="Помощник по профилю бренда" welcome="Расскажи, чем занимается компания. Я помогу понятно описать бренд, аудиторию, стиль и ожидания от видео." prompts={["Помоги описать бренд","Сформулируй нашу аудиторию","Как объяснить визуальный стиль?"]} context={{role:"business",goal:"Оформить профиль "+viewer.name}}/><Card title="Что увидят монтажёры"><p className="muted">Название и подтверждение компании, понятные задания, сроки, награды, история выбора победителей и оценка взаимодействия. Учебные данные монтажёра здесь не используются.</p></Card></div></Page>}

     {tab==="profile"&&isCreator&&<Page title="Профиль блогера" sub="Подтверди публичную страницу и объясни монтажёрам стиль своего контента."><div className="business-stack"><CreatorVerification/><BrandBrain viewerName={viewer.name}/><AiCoach compact scopeKey="profile:creator" title="Помощник по профилю блогера" welcome="Помогу оформить тематику блога, аудиторию, тон и требования к монтажу." prompts={["Опиши мой блог","Собери требования к монтажу","Помоги объяснить мой стиль"]} context={{role:"creator",goal:"Оформить профиль "+viewer.name}}/><Card title="Что увидят монтажёры"><p className="muted">Твоё имя, отметку «Проверенный блогер», описание контента, задачи и сроки. Пароль, электронная почта и личные данные не публикуются.</p></Card></div></Page>}

     {tab==="jobs"&&isCreator&&<Page title="Мои задания и проекты" sub="Опубликуй задачу одному монтажёру или собери команду. После выбора откроются постоянные рабочие чаты."><div className="business-stack"><CampaignHub mode="business"/><JobBoard mode="business" viewerName={viewer.name}/></div></Page>}
     {tab==="jobs"&&!isCreator&&<Page title="Работа" sub="Задания и вакансии проверенных компаний собраны в одном месте."><div className="business-stack"><CampaignHub mode="editor"/><JobBoard mode="editor" ageGroup={viewer.onboarding?.ageGroup} guardianVerified={viewer.guardianVerified}/></div></Page>}
     {tab==="messages"&&<Page title="Закрытые чаты" sub="Личный диалог блогера или компании с монтажёром. Его видят только два участника, а контакты и внешние ссылки блокируются."><PrivateChats/></Page>}
     {tab==="community"&&<Page title="Сообщество" sub="Рейтинг, друзья, учебные группы, соревнования и приглашения с защитой личных данных."><SocialHub ageGroup={viewer.onboarding?.ageGroup}/></Page>}
     {tab==="business"&&<Page title="Кабинет компании" sub="Сначала подтвердите компанию. После проверки можно публиковать настоящие задания и вакансии."><div className="business-grid"><Stat n={String(businessStats.challenges)} t="активных конкурсов"/><Stat n={String(businessStats.submissions)} t="получено работ"/><Stat n={String(businessStats.jobs)} t="открытых вакансий"/><Stat n={accessLabel} t="режим доступа"/></div><div className="business-stack"><BusinessVerification/><BusinessGrowth/><CampaignHub mode="business"/><BrandBrain viewerName={viewer.name}/><ChallengeCenter role={viewer.role} viewerName={viewer.name} ageGroup={viewer.onboarding?.ageGroup} guardianVerified={viewer.guardianVerified} mode="business"/><JobBoard mode="business" viewerName={viewer.name}/><Card title="Будущий план Studio+"><p className="muted">Командный кабинет и расширенные инструменты готовятся отдельно от тарифа монтажёра. Оплата выключена.</p><Link className="btn btn-ghost" href="/pricing">Посмотреть план</Link></Card></div></Page>}
     {viewer.role?<div className="page review-page-slot"><PlatformReviewForm/></div>:null}
   </section>

   <footer className="app-footer"><div><Link className="brand" href="/platform#home">KIVRONIX<span>.</span></Link><p>{isCreator?"Ставь понятные задачи и работай с монтажёром внутри платформы.":viewer.role==="business"?"Находите монтажёров, проверяйте идеи и растите сильную видео-команду.":"Учись, создавай сильные работы и находи реальные проекты."}</p></div><nav><button onClick={()=>goTab("home")}>Главная</button>{isCreator?<button onClick={()=>goTab("jobs")}>Задания</button>:viewer.role!=="business"?<button onClick={()=>goTab("academy")}>Обучение</button>:<button onClick={()=>goTab("arena")}>Лига компаний</button>}{!isCreator&&<button onClick={()=>goTab("insights")}>Лайфхаки</button>}<Link href="/status">Статус сервисов</Link></nav><span>© 2026 KIVRONIX · бесплатно</span></footer>

   <SiteTour role={viewer.role} onGo={(value)=>goTab(value as Tab)}/>
   <nav className="mobile-nav">{tabs.map(([id,l])=><button key={id} className={tab===id?"active":""} onClick={()=>goTab(id)}>{l}</button>)}</nav>
 </main>
}

function Page({title,sub,children}:{title:string;sub:string;children:React.ReactNode}){return <div className="page"><h1>{title}</h1><p className="sub">{sub}</p>{children}</div>}
function Card({title,children}:{title:string;children:React.ReactNode}){return <div className="card"><h3>{title}</h3>{children}</div>}
function Stat({n,t}:{n:string;t:string}){return <div className="stat"><strong>{n}</strong><span className="muted">{t}</span></div>}
function Job({title,pay}:{title:string;pay:string}){return <div className="card job"><small>УДАЛЁННО</small><h3>{title}</h3><p className="muted">Проверенный бизнес · подбор по портфолио и навыкам</p><b>{pay}</b><button className="btn btn-dark">Податься</button></div>}

function Skill({label,value}:{label:string;value:number}){return <div className="skill-row"><div><span>{label}</span><b>{value}</b></div><div className="score-track"><span style={{width:value+"%"}}/></div></div>}
function money(cents:number){return new Intl.NumberFormat("ru-RU",{style:"currency",currency:"RUB",maximumFractionDigits:0}).format(cents/100)}

"use client";
import {useEffect,useState} from "react";
import {getFreshAccessToken} from "@/lib/supabase-browser";

export default function PlatformReviewForm(){
  const [existing,setExisting]=useState<any>(undefined),[text,setText]=useState(""),[rating,setRating]=useState(5),[message,setMessage]=useState(""),[busy,setBusy]=useState(false);
  useEffect(()=>{void(async()=>{const token=await getFreshAccessToken();if(!token)return;const response=await fetch("/api/platform-reviews",{headers:{Authorization:"Bearer "+token},cache:"no-store"});if(response.ok)setExisting((await response.json()).review)})()},[]);
  async function submit(){setBusy(true);setMessage("");try{const token=await getFreshAccessToken();const response=await fetch("/api/platform-reviews",{method:"POST",headers:{"Content-Type":"application/json",Authorization:"Bearer "+token},body:JSON.stringify({text,rating})});const data=await response.json();if(!response.ok)throw new Error(data.error);setExisting({status:"pending"});setMessage("Спасибо! Отзыв отправлен на модерацию. После публикации начислим 10 бонусных Points.")}catch(error){setMessage(error instanceof Error?error.message:"Не удалось отправить отзыв.")}finally{setBusy(false)}}
  return <section className="platform-review-card"><div><div className="eyebrow">ПОМОГИ УЛУЧШИТЬ KIVRONIX</div><h3>Расскажи о своём опыте</h3><p>Один честный отзыв можно отправить один раз. После модерации он появится на главной, а в профиль начислятся 10 бонусных Points.</p></div>{existing!==undefined?(existing?<div className="review-status"><b>{existing.status==="approved"?"Отзыв опубликован":"Отзыв на модерации"}</b><span>{existing.reward_awarded?"10 бонусных Points начислены":"Мы сообщим результат в кабинете"}</span></div>:<div className="review-compose"><select value={rating} onChange={event=>setRating(Number(event.target.value))}>{[5,4,3,2,1].map(value=><option value={value} key={value}>{value} из 5</option>)}</select><textarea minLength={40} maxLength={1400} value={text} onChange={event=>setText(event.target.value)} placeholder="Что было полезно? Что стоит улучшить?"/><button className="btn btn-lime" disabled={busy||text.trim().length<40} onClick={()=>void submit()}>{busy?"Отправляем…":"Отправить на модерацию"}</button></div>):<span>Проверяем статус…</span>}{message?<div className="auth-msg">{message}</div>:null}</section>
}

"use client";

import Link from "next/link";
import {FormEvent,useEffect,useRef,useState} from "react";
import ProfileAvatar from "@/components/profile-avatar";
import {getSupabaseBrowserClient} from "@/lib/supabase-browser";
import {findPrivateChatBlockReason,privateChatBlockMessage} from "@/lib/private-chat-moderation";
import AiCoach from "@/components/ai-coach";

type Conversation={
  id:string;
  side:"editor"|"company";
  source_kind:"campaign"|"challenge"|"job"|"kivronix_contest";
  source_id:string;
  otherName:string;
  otherUsername?:string|null;
  otherAvatar?:string|null;
  company_name:string;
  title:string;
  status:"active"|"closed";
  last_message_at:string;
  workOrder?:{
    id:string;
    gross_points:number;
    editor_points:number;
    platform_fee_points:number;
    status:"funded"|"submitted"|"completed"|"disputed"|"cancelled";
    work_order_deliverables?:{preview_name:string;original_name:string;submitted_at:string}|Array<{preview_name:string;original_name:string;submitted_at:string}>|null;
  }|null;
};

type Message={id:string;conversation_id:string;sender_id:string;body:string;created_at:string};

export default function PrivateChats(){
  const [signedIn,setSignedIn]=useState<boolean|null>(null);
  const [viewerId,setViewerId]=useState("");
  const [conversations,setConversations]=useState<Conversation[]>([]);
  const [selectedId,setSelectedId]=useState("");
  const [messages,setMessages]=useState<Message[]>([]);
  const [draft,setDraft]=useState("");
  const [notice,setNotice]=useState("");
  const [sending,setSending]=useState(false);
  const [uploading,setUploading]=useState(false);
  const [submittingWork,setSubmittingWork]=useState(false);
  const [previewFile,setPreviewFile]=useState<File|null>(null);
  const [originalFile,setOriginalFile]=useState<File|null>(null);
  const endRef=useRef<HTMLDivElement|null>(null);

  async function token(){
    const supabase=getSupabaseBrowserClient();
    const {data:{session}}=await supabase.auth.getSession();
    return session?.access_token||"";
  }

  async function loadConversations(){
    const access=await token();
    if(!access){setSignedIn(false);return;}
    setSignedIn(true);
    const response=await fetch("/api/private-chats",{headers:{Authorization:"Bearer "+access},cache:"no-store"});
    const data=await response.json().catch(()=>({}));
    if(!response.ok){setNotice(data?.error||"Ошибка загрузки чатов.");return;}
    const next=(data.conversations||[]) as Conversation[];
    let preferred="";
    let preferredSource="";
    try{
      preferred=sessionStorage.getItem("kivronix_open_conversation")||"";
      preferredSource=sessionStorage.getItem("kivronix_open_chat_source")||"";
      sessionStorage.removeItem("kivronix_open_conversation");
      sessionStorage.removeItem("kivronix_open_chat_source");
    }catch{}
    const sourceMatch=preferredSource?next.find(item=>item.source_kind+":"+item.source_id===preferredSource)?.id||"":"";
    setViewerId(data.viewerId||"");
    setConversations(next);
    setSelectedId(current=>{
      if(preferred&&next.some(item=>item.id===preferred))return preferred;
      if(sourceMatch)return sourceMatch;
      if(current&&next.some(item=>item.id===current))return current;
      return next[0]?.id||"";
    });
  }

  async function loadMessages(id:string,silent=false){
    if(!id)return;
    const access=await token();
    if(!access){setSignedIn(false);return;}
    const response=await fetch("/api/private-chats?conversationId="+encodeURIComponent(id),{headers:{Authorization:"Bearer "+access},cache:"no-store"});
    const data=await response.json().catch(()=>({}));
    if(!response.ok){if(!silent)setNotice(data?.error||"Ошибка загрузки сообщений.");return;}
    setViewerId(data.viewerId||"");
    setMessages(data.messages||[]);
  }

  useEffect(()=>{void loadConversations()},[]);

  useEffect(()=>{
    if(!selectedId){setMessages([]);return;}
    void loadMessages(selectedId);
    const supabase=getSupabaseBrowserClient();
    const channel=supabase.channel("private-chat-"+selectedId)
      .on("postgres_changes",{event:"INSERT",schema:"public",table:"private_messages",filter:"conversation_id=eq."+selectedId},()=>void loadMessages(selectedId,true))
      .subscribe();
    const timer=window.setInterval(()=>void loadMessages(selectedId,true),5000);
    return()=>{window.clearInterval(timer);void supabase.removeChannel(channel)};
  },[selectedId]);

  useEffect(()=>{endRef.current?.scrollIntoView({behavior:"smooth",block:"nearest"})},[messages]);

  async function send(event:FormEvent){
    event.preventDefault();
    const message=draft.trim();
    if(!message||!selectedId||sending)return;
    if(findPrivateChatBlockReason(message)){setNotice(privateChatBlockMessage());return;}
    setSending(true);setNotice("");
    const access=await token();
    if(!access){setSignedIn(false);setSending(false);return;}
    const response=await fetch("/api/private-chats",{
      method:"POST",
      headers:{"Content-Type":"application/json",Authorization:"Bearer "+access},
      body:JSON.stringify({action:"send",conversationId:selectedId,message})
    });
    const data=await response.json().catch(()=>({}));
    if(response.ok){setDraft("");await loadMessages(selectedId,true);await loadConversations()}
    else setNotice(data?.error||"Ошибка отправки сообщения.");
    setSending(false);
  }

  async function uploadWorkFile(file:File){
    if(!selectedId||!viewerId||uploading)return;
    setUploading(true);setNotice("");
    const safe=file.name.replace(/[^a-zA-Z0-9а-яА-Я._-]/g,"_").slice(-120);
    const path=selectedId+"/attachments/"+viewerId+"/"+crypto.randomUUID()+"-"+safe;
    const supabase=getSupabaseBrowserClient();
    const {error}=await supabase.storage.from("work-files").upload(path,file,{upsert:false,contentType:file.type||"application/octet-stream"});
    if(error){setNotice("Не удалось загрузить файл: "+error.message);setUploading(false);return;}
    const access=await token();
    const response=await fetch("/api/private-chats",{method:"POST",headers:{"Content-Type":"application/json",Authorization:"Bearer "+access},body:JSON.stringify({action:"send",conversationId:selectedId,message:"KIVRONIX_FILE:"+path+"|"+safe})});
    setNotice(response.ok?"Файл передан внутри защищённого чата.":"Файл загружен, но сообщение не отправилось.");
    await loadMessages(selectedId,true);setUploading(false);
  }

  async function openWorkFile(body:string){
    const [path]=body.replace("KIVRONIX_FILE:","").split("|");
    const {data,error}=await getSupabaseBrowserClient().storage.from("work-files").createSignedUrl(path,60);
    if(error||!data?.signedUrl){setNotice("Не удалось открыть файл.");return;}
    window.open(data.signedUrl,"_blank","noopener,noreferrer");
  }

  async function completeWork(){
    if(!current?.workOrder||current.workOrder.status!=="submitted"||!window.confirm("Работа вас устраивает? После подтверждения Points сразу перейдут монтажёру, а вам откроется оригинал для скачивания."))return;
    const access=await token();const r=await fetch("/api/private-chats",{method:"POST",headers:{"Content-Type":"application/json",Authorization:"Bearer "+access},body:JSON.stringify({action:"complete_work",workOrderId:current.workOrder.id})});
    const data=await r.json().catch(()=>({}));setNotice(r.ok?"Работа принята. Оплата отправлена монтажёру, оригинал открыт для скачивания.":data.error||"Не удалось завершить работу.");if(r.ok)await loadConversations();
  }

  async function refundWork(){
    if(!current?.workOrder||!["funded","submitted"].includes(current.workOrder.status)||!window.confirm("Отменить заказ и вернуть все зарезервированные Points на ваш баланс? Доступ к оригиналу останется закрыт."))return;
    const access=await token();
    const r=await fetch("/api/private-chats",{method:"POST",headers:{"Content-Type":"application/json",Authorization:"Bearer "+access},body:JSON.stringify({action:"refund_work",workOrderId:current.workOrder.id})});
    const data=await r.json().catch(()=>({}));
    setNotice(r.ok?"Заказ отменён. Все зарезервированные Points возвращены на баланс.":data.error||"Не удалось оформить возврат.");
    if(r.ok)await loadConversations();
  }

  async function openDelivery(kind:"preview"|"original"){
    if(!current?.workOrder)return;
    const access=await token();
    const r=await fetch("/api/private-chats",{method:"POST",headers:{"Content-Type":"application/json",Authorization:"Bearer "+access},body:JSON.stringify({action:"open_delivery",workOrderId:current.workOrder.id,kind})});
    const data=await r.json().catch(()=>({}));
    if(!r.ok||!data.url){setNotice(data.error||"Не удалось открыть файл.");return;}
    window.open(data.url,"_blank","noopener,noreferrer");
  }

  async function submitWork(){
    if(!current?.workOrder||!previewFile||!originalFile||submittingWork)return;
    setSubmittingWork(true);setNotice("");
    const supabase=getSupabaseBrowserClient();
    const base=`${current.id}/delivery/${current.workOrder.id}`;
    const previewSafe=previewFile.name.replace(/[^a-zA-Z0-9а-яА-Я._-]/g,"_").slice(-120);
    const originalSafe=originalFile.name.replace(/[^a-zA-Z0-9а-яА-Я._-]/g,"_").slice(-120);
    const previewPath=`${base}/preview/${viewerId}/${crypto.randomUUID()}-${previewSafe}`;
    const originalPath=`${base}/original/${viewerId}/${crypto.randomUUID()}-${originalSafe}`;
    const previewUpload=await supabase.storage.from("work-files").upload(previewPath,previewFile,{upsert:false,contentType:previewFile.type});
    if(previewUpload.error){setNotice("Не удалось загрузить превью: "+previewUpload.error.message);setSubmittingWork(false);return;}
    const originalUpload=await supabase.storage.from("work-files").upload(originalPath,originalFile,{upsert:false,contentType:originalFile.type||"application/octet-stream"});
    if(originalUpload.error){setNotice("Превью загружено, но оригинал не загрузился: "+originalUpload.error.message);setSubmittingWork(false);return;}
    const access=await token();
    const r=await fetch("/api/private-chats",{method:"POST",headers:{"Content-Type":"application/json",Authorization:"Bearer "+access},body:JSON.stringify({action:"submit_work",workOrderId:current.workOrder.id,previewPath,originalPath,previewName:previewFile.name,originalName:originalFile.name})});
    const data=await r.json().catch(()=>({}));
    setSubmittingWork(false);
    if(!r.ok){setNotice(data.error||"Не удалось передать работу.");return;}
    setPreviewFile(null);setOriginalFile(null);setNotice("Работа передана на просмотр. Оригинал защищён до подтверждения оплаты.");
    await loadConversations();
  }

  if(signedIn===null)return <div className="card"><p className="muted">Открываем закрытые чаты…</p></div>;
  if(signedIn===false)return <div className="card private-chat-empty"><div className="private-chat-lock">🔒</div><h3>Войдите в аккаунт</h3><p>Закрытые чаты доступны участникам работы и конкурса.</p><Link className="btn btn-dark" href="/login?from=/platform%23messages">Войти</Link></div>;

  const current=conversations.find(item=>item.id===selectedId)||null;

  return <div className="private-chat-shell">
    <aside className="private-chat-list">
      <div className="private-chat-list-head"><b>Закрытые чаты</b><span>{conversations.length}</span></div>
      {conversations.length===0?<div className="private-chat-zero"><span>💬</span><b>Чаты появятся здесь</b><p>Компания принимает монтажёра или выбирает победителя конкурса. После этого система открывает общий чат.</p></div>:conversations.map(item=><button type="button" className={item.id===selectedId?"active":""} key={item.id} onClick={()=>{setSelectedId(item.id);setNotice("")}}>
        <ProfileAvatar src={item.otherAvatar} name={item.otherName} size="sm"/>
        <span><b>{item.otherName}</b><small>{sourceLabel(item.source_kind)}</small></span>
        <time>{shortDate(item.last_message_at)}</time>
      </button>)}
    </aside>

    <section className="private-chat-thread">
      {current?<>
        <header><div><div className="private-chat-title"><span className="private-chat-shield">◆</span><div><h3>{current.otherName}</h3><p>{current.title}</p></div></div></div><span className="private-chat-badge">Закрытый чат</span></header>
        <div className="private-chat-safety"><b>Сообщения видят только компания и монтажёр.</b><span>Телефоны, электронная почта, ссылки, адреса страниц и названия мессенджеров остаются за пределами чата. Общайтесь внутри KIVRONIX.</span></div>
        <details className="chat-ai-brief" open><summary>ИИ‑разбор задания · виден обеим сторонам</summary><div><p><b>Задача:</b> {current.title}</p><p>Помощник учитывает название задания и контекст этого рабочего чата. Он поможет уточнить результат, формат, сроки, критерии готовности и собрать правки без личных контактов.</p><AiCoach compact scopeKey={`work-brief:${current.id}`} title="Помощник по ТЗ" welcome={`Я знаю задачу «${current.title}». Помогу превратить её в точное ТЗ и проверить, одинаково ли обе стороны понимают результат.`} prompts={["Разбери ТЗ по пунктам","Каких данных не хватает?","Собери чек-лист приёмки"]} context={{role:current.side,goal:current.title}}/></div></details>
        {current.workOrder?<WorkOrderPanel
          order={current.workOrder}
          side={current.side}
          previewFile={previewFile}
          originalFile={originalFile}
          submitting={submittingWork}
          onPreviewFile={setPreviewFile}
          onOriginalFile={setOriginalFile}
          onSubmit={submitWork}
          onOpenPreview={()=>openDelivery("preview")}
          onOpenOriginal={()=>openDelivery("original")}
          onComplete={completeWork}
          onRefund={refundWork}
        />:null}
        <div className="private-chat-messages" aria-live="polite">
          {messages.length===0?<div className="private-chat-start"><span>👋</span><b>Можно начинать</b><p>Обсудите задачу, срок, готовый результат и правки простыми словами.</p></div>:messages.map(item=><article className={item.sender_id===viewerId?"mine":"theirs"} key={item.id}>{item.body.startsWith("KIVRONIX_FILE:")?<button className="mini-btn" type="button" onClick={()=>openWorkFile(item.body)}>📎 {item.body.split("|").pop()||"Файл работы"}</button>:<p>{item.body}</p>}<time>{messageTime(item.created_at)}</time></article>)}
          <div ref={endRef}/>
        </div>
        <form className="private-chat-form" onSubmit={send}>
          <textarea value={draft} onChange={event=>setDraft(event.target.value)} maxLength={1500} rows={3} placeholder="Напишите сообщение о работе…" disabled={current.status!=="active"}/>
          <div><label className="mini-btn">{uploading?"Загружаем…":"📎 Передать файл"}<input hidden type="file" accept="video/mp4,video/quicktime,video/webm,application/zip,image/jpeg,image/png" disabled={uploading} onChange={e=>{const file=e.target.files?.[0];if(file)void uploadWorkFile(file);e.target.value=""}}/></label><small>{draft.length} / 1500</small><button className="btn btn-dark" disabled={sending||!draft.trim()||current.status!=="active"}>{sending?"Отправляем…":"Отправить"}</button></div>
        </form>
        {notice?<div className="auth-msg">{notice}</div>:null}
      </>:<div className="private-chat-zero large"><span>🔒</span><b>Выберите чат</b><p>Здесь будет ваш разговор о работе.</p></div>}
    </section>
  </div>;
}

function WorkOrderPanel(props:{
  order:NonNullable<Conversation["workOrder"]>;
  side:"editor"|"company";
  previewFile:File|null;
  originalFile:File|null;
  submitting:boolean;
  onPreviewFile:(file:File|null)=>void;
  onOriginalFile:(file:File|null)=>void;
  onSubmit:()=>void;
  onOpenPreview:()=>void;
  onOpenOriginal:()=>void;
  onComplete:()=>void;
  onRefund:()=>void;
}){
  const {order,side}=props;
  const delivery=Array.isArray(order.work_order_deliverables)?order.work_order_deliverables[0]:order.work_order_deliverables;
  const active=["funded","submitted"].includes(order.status);
  return <div className="work-escrow-card">
    <div className="work-escrow-head"><div><span>БЕЗОПАСНАЯ СДЕЛКА</span><b>{order.gross_points.toLocaleString("ru-RU")} KP защищены платформой</b></div><strong>{statusLabel(order.status)}</strong></div>
    {order.status==="completed"?<div className="delivery-actions"><p>Заказчик принял работу, оплата отправлена монтажёру. Оригинал доступен участникам сделки.</p><button className="btn btn-dark" type="button" onClick={props.onOpenOriginal}>Скачать оригинал</button></div>:order.status==="cancelled"?<p>Заказ отменён. Зарезервированные Points возвращены заказчику, оригинал остался закрыт.</p>:side==="editor"?<>
      <p>{order.status==="submitted"?"Заказчик уже видит защищённое превью. До принятия работы оригинал ему недоступен.":"Загрузите два файла: безопасное превью с водяным знаком и исходный оригинал без ограничений."}</p>
      {active?<div className="delivery-upload-grid">
        <label><span>1. Превью для проверки</span><small>Видео или изображение с водяным знаком KIVRONIX</small><input type="file" accept="video/mp4,video/quicktime,video/webm,image/jpeg,image/png" onChange={e=>props.onPreviewFile(e.target.files?.[0]||null)}/><em>{props.previewFile?.name||delivery?.preview_name||"Файл не выбран"}</em></label>
        <label><span>2. Оригинал для выдачи</span><small>Откроется заказчику только после оплаты</small><input type="file" accept="video/mp4,video/quicktime,video/webm,application/zip,image/jpeg,image/png" onChange={e=>props.onOriginalFile(e.target.files?.[0]||null)}/><em>{props.originalFile?.name||delivery?.original_name||"Файл не выбран"}</em></label>
        <button className="btn btn-dark" type="button" disabled={!props.previewFile||!props.originalFile||props.submitting} onClick={props.onSubmit}>{props.submitting?"Защищаем файлы…":delivery?"Заменить результат":"Отправить на просмотр"}</button>
        {delivery?<button className="btn btn-ghost" type="button" onClick={props.onOpenPreview}>Открыть превью</button>:null}
      </div>:null}
    </>:<>
      <p>{order.status==="submitted"?"Монтажёр передал работу. Проверьте превью: оригинал нельзя скачать, пока вы не подтвердите оплату.":"Points находятся в резерве и не переданы монтажёру. Ждём, когда он загрузит результат."}</p>
      <div className="delivery-actions">
        {order.status==="submitted"?<button className="btn btn-ghost" type="button" onClick={props.onOpenPreview}>Посмотреть защищённое превью</button>:null}
        {order.status==="submitted"?<button className="btn btn-dark" type="button" onClick={props.onComplete}>Всё нравится — оплатить и скачать</button>:null}
        {active?<button className="mini-btn danger" type="button" onClick={props.onRefund}>Отменить и вернуть Points</button>:null}
      </div>
    </>}
  </div>;
}

function statusLabel(status:NonNullable<Conversation["workOrder"]>["status"]){
  if(status==="funded")return "Деньги в резерве";
  if(status==="submitted")return "Режим просмотра";
  if(status==="completed")return "Оплачено";
  if(status==="cancelled")return "Возврат выполнен";
  return "Спор";
}

function sourceLabel(value:Conversation["source_kind"]){
  if(value==="campaign")return "Работа с компанией";
  if(value==="challenge")return "Конкурс компании";
  if(value==="job")return "Вакансия";
  return "Конкурс KIVRONIX";
}

function shortDate(value:string){
  const date=new Date(value);
  const today=new Date();
  return date.toDateString()===today.toDateString()?date.toLocaleTimeString("ru-RU",{hour:"2-digit",minute:"2-digit"}):date.toLocaleDateString("ru-RU",{day:"2-digit",month:"2-digit"});
}

function messageTime(value:string){
  return new Date(value).toLocaleString("ru-RU",{day:"numeric",month:"short",hour:"2-digit",minute:"2-digit"});
}

export default function ProfileAvatar({src,name,size="md"}:{src?:string|null;name?:string|null;size?:"sm"|"md"|"lg"}){
  const initial=(name||"E").trim().charAt(0).toUpperCase()||"E";
  return <span className={"profile-avatar "+size} aria-label={name||"Профиль"}>
    {src?<img src={src} alt="" loading="lazy"/>:<b aria-hidden="true">{initial}</b>}
  </span>;
}

"use client";

import {FormEvent,useEffect,useRef,useState} from "react";
import {getSupabaseBrowserClient} from "@/lib/supabase-browser";
import ProfileAvatar from "@/components/profile-avatar";

type ProfileForm={displayName:string;username:string;schoolName:string;avatarUrl:string;showSchoolPublicly:boolean};

export default function ProfileEditor({onSaved}:{onSaved?:(profile:ProfileForm)=>void}){
  const [form,setForm]=useState<ProfileForm>({displayName:"",username:"",schoolName:"",avatarUrl:"",showSchoolPublicly:false});
  const [loading,setLoading]=useState(true);
  const [saving,setSaving]=useState(false);
  const [message,setMessage]=useState("");
  const fileRef=useRef<HTMLInputElement>(null);

  useEffect(()=>{
    let active=true;
    async function load(){
      const supabase=getSupabaseBrowserClient();
      const {data:{user}}=await supabase.auth.getUser();
      if(!user){if(active){setMessage("Войди в аккаунт, чтобы изменить профиль.");setLoading(false)};return;}
      const {data:{session}}=await supabase.auth.getSession();
      if(!session?.access_token){if(active){setMessage("Сессия закончилась. Войди снова.");setLoading(false)};return;}
      const response=await fetch("/api/profile/settings",{headers:{Authorization:`Bearer ${session.access_token}`},cache:"no-store"});
      const data=response.ok?await response.json().catch(()=>null):null;
      if(active){
        if(!data)setMessage("Не удалось загрузить профиль.");
        else setForm({displayName:data.displayName||"",username:data.username||"",schoolName:data.schoolName||"",avatarUrl:data.avatarUrl||"",showSchoolPublicly:Boolean(data.showSchoolPublicly)});
        setLoading(false);
      }
    }
    void load();
    return()=>{active=false};
  },[]);

  async function save(event:FormEvent){
    event.preventDefault();
    if(saving)return;
    const displayName=form.displayName.trim().replace(/\s+/g," ");
    const username=form.username.trim().replace(/^@/,"").toLowerCase();
    const schoolName=form.schoolName.trim().replace(/\s+/g," ");
    if(displayName.length<2){setMessage("Имя должно содержать 2 символа или больше.");return;}
    if(!/^[a-z0-9][a-z0-9._-]{2,29}$/.test(username)){setMessage("Адрес страницы: 3–30 символов. Подойдут латинские буквы, цифры, точка, дефис и подчёркивание.");return;}
    if(schoolName&&schoolName.length<2){setMessage("Проверь название школы.");return;}

    setSaving(true);setMessage("");
    const supabase=getSupabaseBrowserClient();
    const {data:{user}}=await supabase.auth.getUser();
    if(!user){setSaving(false);setMessage("Сессия закончилась. Войди снова.");return;}
    const {data:{session}}=await supabase.auth.getSession();
    if(!session?.access_token){setSaving(false);setMessage("Сессия закончилась. Войди снова.");return;}

    let avatarUrl=form.avatarUrl;
    const file=fileRef.current?.files?.[0];
    if(file){
      if(!["image/jpeg","image/png","image/webp"].includes(file.type)){setSaving(false);setMessage("Аватар должен быть JPG, PNG или WebP.");return;}
      if(file.size>5*1024*1024){setSaving(false);setMessage("Аватар должен быть меньше 5 МБ.");return;}
      const ext=file.type==="image/png"?"png":file.type==="image/webp"?"webp":"jpg";
      const path=user.id+"/avatar."+ext;
      const {error:uploadError}=await supabase.storage.from("avatars").upload(path,file,{upsert:true,contentType:file.type,cacheControl:"3600"});
      if(uploadError){setSaving(false);setMessage("Ошибка загрузки изображения: "+uploadError.message);return;}
      avatarUrl=supabase.storage.from("avatars").getPublicUrl(path).data.publicUrl+"?v="+Date.now();
    }

    const next={
      displayName,
      username,
      schoolName,
      avatarUrl,
      showSchoolPublicly:Boolean(schoolName&&form.showSchoolPublicly)
    };
    const response=await fetch("/api/profile/settings",{
      method:"POST",
      headers:{Authorization:`Bearer ${session.access_token}`,"Content-Type":"application/json"},
      body:JSON.stringify(next),
    });
    const result=await response.json().catch(()=>null);
    setSaving(false);
    if(!response.ok||!result){
      setMessage(String(result?.error||"Не удалось сохранить профиль."));
      return;
    }
    const saved={displayName:String(result.displayName||""),username:String(result.username||""),schoolName:String(result.schoolName||""),avatarUrl:String(result.avatarUrl||""),showSchoolPublicly:Boolean(result.showSchoolPublicly)};
    setForm(saved);setMessage(saved.showSchoolPublicly?"Профиль сохранён. Школа участвует в командном рейтинге.":"Профиль сохранён. Название школы видно только тебе.");onSaved?.(saved);
    if(fileRef.current)fileRef.current.value="";
  }

  if(loading)return <section className="card"><p className="muted">Загружаю профиль…</p></section>;

  return <section className="card profile-editor-card">
    <div className="profile-editor-head"><ProfileAvatar src={form.avatarUrl} name={form.displayName} size="lg"/><div><div className="eyebrow">ТВОЙ ПРОФИЛЬ</div><h3>Фото, имя и команда</h3></div></div>
    <form className="business-form" onSubmit={save}>
      <label className="field-label">Фото профиля</label>
      <input ref={fileRef} type="file" accept="image/jpeg,image/png,image/webp"/>
      <label className="field-label">Имя</label>
      <input required maxLength={120} value={form.displayName} onChange={event=>setForm({...form,displayName:event.target.value})}/>
      <label className="field-label">Короткий адрес твоей страницы</label>
      <input required maxLength={30} value={form.username} onChange={event=>setForm({...form,username:event.target.value})} placeholder="editor-name"/>
      <label className="field-label">Школа, колледж или вуз</label>
      <input maxLength={160} value={form.schoolName} onChange={event=>setForm({...form,schoolName:event.target.value})} placeholder="Необязательно"/>
      <label className="consent-row"><input type="checkbox" checked={form.showSchoolPublicly} disabled={!form.schoolName.trim()} onChange={event=>setForm({...form,showSchoolPublicly:event.target.checked})}/><span>Показывать название учебного заведения в профиле и учитывать его в рейтинге школ.</span></label>
      <small className="field-hint">По умолчанию школа скрыта. Класс, адрес, смену и телефон оставь за пределами профиля.</small>
      <button className="btn btn-dark" disabled={saving}>{saving?"Сохраняю…":"Сохранить профиль"}</button>
    </form>
    {message?<div className="auth-msg">{message}</div>:null}
  </section>;
}

"use client";

