    if(typeof row.createdAt!=="string"||row.createdAt.length>64||!Number.isFinite(Date.parse(row.createdAt)))return null;
    seen.add(row.id);
    messages.push({id:row.id,content:row.content,createdAt:row.createdAt,author:row.author});
  }
  return {messages};
}

